/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE sys_menu (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        label TEXT,
        path TEXT,
        icon TEXT
      , subtitle TEXT DEFAULT '', page_key TEXT, route_key TEXT DEFAULT 'dashboard', `order` INTEGER DEFAULT 0, parent_id INTEGER DEFAULT NULL);
CREATE TABLE sys_page_template (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        page_key TEXT NOT NULL,
        title TEXT NOT NULL,
        schema_json TEXT NOT NULL,
        is_active INTEGER DEFAULT 1,
        version INTEGER DEFAULT 1,
        backup_time TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, source_template_id TEXT, source_params TEXT,
        UNIQUE(page_key, version)
      );
CREATE TABLE sys_component_library (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                component_id TEXT UNIQUE NOT NULL,
                component_name TEXT NOT NULL,
                category TEXT NOT NULL,
                description TEXT,
                template_path TEXT NOT NULL,
                params_schema TEXT NOT NULL,
                default_params TEXT,
                example_usage TEXT,
                is_active INTEGER DEFAULT 1,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE sys_page_templates_config (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_id TEXT UNIQUE NOT NULL,
                template_name TEXT NOT NULL,
                description TEXT,
                template_file TEXT NOT NULL,
                components TEXT NOT NULL,
                params_schema TEXT NOT NULL,
                default_params TEXT,
                preview_image TEXT,
                theme_id TEXT DEFAULT 'cxd',
                is_active INTEGER DEFAULT 1,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
COMMIT;
