a                                                                                {\u000a                                                                                    "type": "input-text",\u000a                                                                                    "name": "workflow_name",\u000a                                                                                    "label": "\\u5de5\\u4f5c\\u6d41\\u540d\\u79f0",\u000a                                                                                    "required": true\u000a                                                                                },\u000a                                                                                {\u000a                                                                                    "type": "select",\u000a                                                                                    "name": "workflow_type",\u000a                                                                                    "label": "\\u7c7b\\u578b",\u000a                                                                                    "options": [\u000a                                                                                        {\u000a                                                                                            "label": "\\ud83e\\udd16 AI \\u5206\\u6790",\u000a                                                                                            "value": "ai_analysis"\u000a                                                                                        },\u000a                                                                                        {\u000a                                                                                            "label": "\\ud83d\\udcdd \\u62a5\\u544a\\u751f\\u6210",\u000a                                                                                            "value": "report_generation"\u000a                                                                                        },\u000a                                                                                        {\u000a                                                                                            "label": "\\u2601\\ufe0f \\u6570\\u636e\\u5bfc\\u5165",\u000a                                                                                            "value": "data_import"\u000a                                                                                        }\u000a                                                                                    ]\u000a                                                                                },\u000a                                                                                {\u000a                                                                                    "type": "input-text",\u000a                                                                                    "name": "api_url",\u000a                                                                                    "label": "API \\u5730\\u5740",\u000a                                                                                    "required": true\u000a                                                                                },\u000a                                                                                {\u000a                                                                                    "type": "input-password",\u000a                                                                                    "name": "api_key",\u000a                                                                                    "label": "API Key",\u000a                                                                                    "required": true\u000a                                                                                },\u000a                                                                                {\u000a                                                                                    "type": "textarea",\u000a                                                                                    "name": "description",\u000a                                                                                    "label": "\\u63cf\\u8ff0",\u000a                                                                                    "maxRows": 3\u000a                                                                                }\u000a                                                                            ]\u000a                                                                        }\u000a                                                                    }\u000a                                                                },\u000a                                                                {\u000a                                                                    "label": "\\u5220\\u9664",\u000a                                                                    "icon": "fa fa-trash",\u000a                                                                    "level": "link",\u000a                                                                    "className": "text-danger",\u000a                                                                    "actionType": "ajax",\u000a                                                                    "confirmText": "\\u786e\\u8ba4\\u5220\\u9664\\u5de5\\u4f5c\\u6d41\\u3010${workflow_name}\\u3011\\uff1f",\u000a                                                                    "api": "delete:/api/dify/config/${id}"\u000a                                                                }\u000a                                                            ]\u000a                                                        }\u000a                                                    ]\u000a                                                }\u000a                                            }\u000a                                        },\u000a                                        {\u000a                                            "label": "\\u9884\\u89c8",\u000a                                            "icon": "fa fa-eye",\u000a                                            "level": "link",\u000a                                            "actionType": "link",\u000a                                            "link": "/dashboard/${page_key}",\u000a                                            "blank": true\u000a                                        },\u000a                                        {\u000a                                            "label": "\\u5220\\u9664",\u000a                                            "icon": "fa fa-trash",\u000a                                            "level": "link",\u000a                                            "className": "text-danger",\u000a                                            "actionType": "ajax",\u000a                                            "confirmText": "\\u786e\\u8ba4\\u5220\\u9664\\u9875\\u9762\\u3010${title}\\u3011\\uff1f\\u6b64\\u64cd\\u4f5c\\u4e0d\\u53ef\\u6062\\u590d\\u3002",\u000a                                            "api": {\u000a                                                "method": "post",\u000a                                                "url": "/api/system/template/delete",\u000a                                                "data": {\u000a                                                    "page_key": "${page_key}"\u000a                                                }\u000a                                            }\u000a                                        }\u000a                                    ]\u000a                                }\u000a                            ]\u000a                        }\u000a                    ]\u000a                },\u000a                {\u000a                    "title": "\\ud83c\\udfa8 \\u6a21\\u677f\\u5b9a\\u4e49\\u7ba1\\u7406",\u000a                    "icon": "fa fa-file-code-o",\u000a                    "body": [\u000a                        {\u000a                            "type": "alert",\u000a                            "level": "info",\u000a                            "body": "\\ud83d\\udca1 \\u6b64\\u9875\\u9762\\u7ba1\\u7406 Jinja2 \\u6a21\\u677f\\u6587\\u4ef6\\u7684\\u5143\\u6570\\u636e\\u3002\\u65b0\\u589e\\u6a21\\u677f\\u9700\\u8981\\u5728 `server/templates/pages/` \\u76ee\\u5f55\\u521b\\u5efa .j2 \\u6587\\u4ef6\\u540e\\u70b9\\u51fb\\u91cd\\u65b0\\u5206\\u6790\\u540c\\u6b65\\u5230\\u6570\\u636e\\u5e93\\u3002",\u000a                            "className": "m-b"\u000a                        },\u000a                        {\u000a                            "type": "crud",\u000a                            "syncLocation": false,\u000a                            "api": "/api/system/template-definitions",\u000a                            "headerToolbar": [\u000a                                {\u000a                                    "type": "button",\u000a                                    "label": "\\u91cd\\u65b0\\u5206\\u6790\\u6a21\\u677f",\u000a                                    "icon": "fa fa-refresh",\u000a                                    "level": "success",\u000a                                    "actionType": "ajax",\u000a                                    "api": {\u000a                                        "method": "post",\u000a                                        "url": "/api/system/analyze-templates"\u000a                                    },\u000a                                    "confirmText": "\\u786e\\u8ba4\\u91cd\\u65b0\\u626b\\u63cf server/templates/pages/ \\u76ee\\u5f55\\u5e76\\u66f4\\u65b0\\u6570\\u636e\\u5e93\\uff1f",\u000a                                    "reload": "window"\u000a                                },\u000a                                "pagination"\u000a                            ],\u000a                            "columns": [\u000a                                {\u000a                                    "name": "template_id",\u000a                                    "label": "\\u6a21\\u677fID",\u000a                                    "searchable": true,\u000a                                    "width": 150\u000a                                },\u000a                                {\u000a                                    "name": "template_name",\u000a                                    "label": "\\u6a21\\u677f\\u540d\\u79f0",\u000a                                    "width": 180\u000a                                },\u000a                                {\u000a                                    "name": "template_file",\u000a                                    "label": "\\u6587\\u4ef6\\u8def\\u5f84",\u000a                                    "copyable": true\u000a                                },\u000a                                {\u000a                                    "name": "is_active",\u000a                                    "label": "\\u72b6\\u6001",\u000a                                    "width": 80,\u000a                                    "type": "switch",\u000a                                    "quickEdit": {\u000a                                        "mode": "inline",\u000a                                        "saveImmediately": true,\u000a                                        "api": "put:/api/system/template-definitions/${template_id}"\u000a                                    }\u000a                                }\u000a                            ]\u000a                        }\u000a                    ]\u000a                },\u000a                {\u000a                    "title": "\\u2699\\ufe0f \\u540e\\u7aef\\u8bbe\\u7f6e",\u000a                    "icon": "fa fa-server",\u000a                    "body": [\u000a                        {\u000a                            "type": "alert",\u000a                            "level": "warning",\u000a                            "body": "\\u26a0\\ufe0f \\u540e\\u7aef\\u8bbe\\u7f6e\\u529f\\u80fd\\u5f00\\u53d1\\u4e2d..."\u000a                        }\u000a                    ]\u000a                }\u000a            ]\u000a        }\u000a    ]\u000a}'),0,24,'2025-12-18 20:56:38','2025-12-15 05:33:39','2025-12-18 20:03:41',NULL,NULL);
