INSERT INTO sys_page_template VALUES(47,'trace_test_v3','Traceability Test V3',unistr('\u000a\u000a{\u000a    "type": "page",\u000a    "body": [\u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "text-center",\u000a            "style": {\u000a                "width": "100%"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "tpl",\u000a                    "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>Traceability Test V3</h2>"\u000a                },\u000a                {\u000a                    "type": "tpl",\u000a                    "tpl": "<div style=''color: #8c8c8c; font-size: 13px;''>Trace Subtitle</div>"\u000a                }\u000a            ]\u000a        }\u000a        \u000a        \u000a        \u000a    ]\u000a},\u000a        \u000a\u000a{\u000a    "type": "tpl",\u000a    "tpl": "<div style=''margin-bottom: 12px;''></div>"\u000a}\u000a,\u000a        {\u000a            "type": "panel",\u000a            "title": "<div style=''padding-left: 12px; border-left: 4px solid #1890ff; font-weight: 600; font-size: 16px; color: #1d1d1f;''>风险分布分析</div>",\u000a            "className": "m-b-none",\u000a            "bodyClassName": "p-4",\u000a            "style": {\u000a                "boxShadow": "",\u000a                "borderRadius": "8px",\u000a                "border": "1px solid "\u000a            },\u000a            "body": {\u000a                "type": "grid",\u000a                "align": "middle",\u000a                "columns": [\u000a                    {\u000a                        "md": 8,\u000a                        "body": [\u000a                            \u000a{\u000a    "type": "chart",\u000a    "api": {\u000a        "url": "/api/chart",\u000a        "method": "get",\u000a        "adaptor": "const option = payload.data || {}; if (option.series && option.series[0]) { option.series[0].radius = [''50%'', ''70%'']; option.series[0].emphasis = { scale: true, scaleSize: 10 }; option.series[0].itemStyle = { borderRadius: 8, borderColor: ''#fff'', borderWidth: 2 }; } option.legend = { orient: ''horizontal'', bottom: ''0'', left: ''center'', icon: ''circle'', itemWidth: 14, itemHeight: 14, textStyle: { fontSize: 13, color: ''#666'' } }; return { ...payload, data: option };"\u000a    },\u000a    "height": 350,\u000a    "clickAction": {\u000a        "actionType": "dialog",\u000a        "dialog": {\u000a            "title": "${selectedName}客户清册",\u000a            "size": "xl",\u000a            "actions": [\u000a                {\u000a                    "type": "button",\u000a                    "label": "关闭",\u000a                    "actionType": "close"\u000a                }\u000a            ],\u000a            "data": {\u000a            "selectedId": "${data.itemId}",\u000a            "selectedName": "${data.name}"\u000a            },\u000a            "body": {\u000a                "type": "service",\u000a                "api": {\u000a                    "method": "get",\u000a                    "url": "/api/demo/risk-list/${selectedId}"\u000a                },\u000a                "body": {\u000a                    "type": "table",\u000a                    "affixHeader": true,\u000a                    "columns": [\u000a                        {\u000a                            "name": "id",\u000a                            "label": "ID",\u000a                            "width": 60\u000a                        },\u000a                        {\u000a                            "name": "customer_name",\u000a                            "label": "客户姓名"\u000a                        },\u000a                        {\u000a                            "name": "amount",\u000a                            "label": "贷款金额",\u000a                            "type": "tpl",\u000a                            "tpl": "¥${amount | number:0,0}"\u000a                        },\u000a                        {\u000a                            "name": "overdue_days",\u000a                            "label": "逾期天数",\u000a                            "type": "mapping",\u000a                            "map": {\u000a                                "*": "<span class=''label label-${overdue_days > 60 ? \\"danger\\" : overdue_days > 30 ? \\"warning\\" : \\"success\\"}''>${overdue_days}天</span>"\u000a                            }\u000a                        },\u000a                        {\u000a                            "name": "risk_score",\u000a                            "label": "风险评分",\u000a                            "type": "progress",\u000a                            "map": {\u000a                                "*": {\u000a                                    "value": "${risk_score}",\u000a                                    "color": "${risk_score >= 80 ? ''danger'' : risk_score >= 50 ? ''warning'' : ''success''}"\u000a                                }\u000a                            }\u000a                        },\u000a                        {\u000a                            "name": "status",\u000a                            "label": "处理状态",\u000a                            "type": "mapping",\u000a                            "map": {\u000a                                "pending": "<span class=''label label-warning''>待处理</span>",\u000a                                "processing": "<span class=''label label-info''>处理中</span>",\u000a                                "completed": "<span class=''label label-success''>已完成</span>"\u000a                            }\u000a                        },\u000a                        {\u000a                            "type": "operation",\u000a                            "label": "操作",\u000a                            "width": 180,\u000a                            "buttons": [\u000a                                {\u000a                                    "type": "button",\u000a                                    "label": "详情",\u000a                                    "level": "link",\u000a                                    "icon": "fa fa-eye",\u000a                                    "actionType": "dialog",\u000a                                    "dialog": {\u000a                                        "title": "客户详细信息 - ${customer_name}",\u000a                                        "size": "lg",\u000a                                        "body": {\u000a                                            "type": "form",\u000a                                            "mode": "horizontal",\u000a                                            "wrapWithPanel": false,\u000a                                            "initApi": {\u000a                                                "method": "get",\u000a                                                "url": "/api/demo/customer/${id}"\u000a                                            },\u000a                                            "api": {\u000a                                                "method": "post",\u000a                                                "url": "/api/demo/customer/${id}"\u000a                                            },\u000a                                            "body": [\u000a                                                {\u000a                                                    "type": "static",\u000a                                                    "name": "id",\u000a                                                    "label": "客户ID"\u000a                                                },\u000a                                                {\u000a                                                    "type": "input-text",\u000a                                                    "name": "customer_name",\u000a                                                    "label": "客户姓名",\u000a                                                    "required": true\u000a                                                },\u000a                                                {\u000a                                                    "type": "input-number",\u000a                                                    "name": "amount",\u000a                                                    "label": "贷款金额",\u000a                                                    "prefix": "¥",\u000a                                                    "required": true\u000a                                                },\u000a                                                {\u000a                                                    "type": "input-number",\u000a                                                    "name": "overdue_days",\u000a                                                    "label": "逾期天数",\u000a                                                    "min": 0\u000a                                                },\u000a                                                {\u000a                                                    "type": "input-number",\u000a                                                    "name": "risk_score",\u000a                                                    "label": "风险评分",\u000a                                                    "min": 0,\u000a                                                    "max": 100,\u000a                                                    "description": "0-100分，分数越高风险越大"\u000a                                                },\u000a                                                {\u000a                                                    "type": "select",\u000a                                                    "name": "status",\u000a                                                    "label": "处理状态",\u000a                                                    "options": [\u000a                                                        {\u000a                                                            "label": "待处理",\u000a                                                            "value": "pending"\u000a                                                        },\u000a                                                        {\u000a                                                            "label": "处理中",\u000a                                                            "value": "processing"\u000a                                                        },\u000a                                                        {\u000a                                                            "label": "已完成",\u000a                                                            "value": "completed"\u000a                                                        }\u000a                                                    ]\u000a                                                }\u000a                                            ]\u000a                                        }\u000a                                    }\u000a                                },\u000a                                {\u000a                                    "type": "button",\u000a                                    "label": "标记已处理",\u000a                                    "level": "link",\u000a                                    "className": "text-success",\u000a                                    "icon": "fa fa-check",\u000a                                    "visibleOn": "${status !== ''completed''}",\u000a                                    "actionType": "ajax",\u000a                                    "api": {\u000a                                        "method": "post",\u000a                                        "url": "/api/demo/customer/${id}/mark-processed"\u000a                                    },\u000a                                    "confirmText": "确认标记该客户为已处理？",\u000a                                    "reload": "window"\u000a                                }\u000a                            ]\u000a                        }\u000a                    ]\u000a                }\u000a            }\u000a        }\u000a    }\u000a}\u000a\u000a                        ]\u000a                    },\u000a                    {\u000a                        "md": 4,\u000a                        "style": {\u000a                            "borderLeft": "1px dashed ",\u000a                            "paddingLeft": "40px",\u000a                            "height": "80%",\u000a                            "margin": "auto 0",\u000a                            "display": "flex",\u000a                            "flexDirection": "column",\u000a                            "justifyContent": "center"\u000a                        },\u000a                        "body": \u000a\u000a[\u000a    \u000a]\u000a\u000a                    }\u000a                ]\u000a            }\u000a        },\u000a        {\u000a            "type": "panel",\u000a            "title": "<div style=''padding-left: 12px; border-left: 4px solid #1890ff; font-weight: 600; font-size: 16px; color: #1d1d1f;''>风险趋势分析</div>",\u000a            "className": "m-t-md m-b-none",\u000a            "bodyClassName": "p-4",\u000a            "style": {\u000a                "boxShadow": "",\u000a                "borderRadius": "8px",\u000a                "border": "1px solid "\u000a            },\u000a            "body": {\u000a                "type": "grid",\u000a                "align": "middle",\u000a                "columns": [\u000a                    {\u000a                        "md": 8,\u000a                        "body": [\u000a                            \u000a\u000a\u000a{\u000a    "type": "chart",\u000a    "api": {\u000a        "url": "/api/test",\u000a        "method": "get",\u000a        "adaptor": "const option = payload.data || {}; if (option.series && option.series[0]) { option.series[0].type = ''bar''; option.series[0].itemStyle = { borderRadius: [4, 4, 0, 0], color: ''#1890FF'' }; option.series[0].emphasis = { itemStyle: { color: '''' } }; option.series[0].label = { show: false, position: ''top'', formatter: ''{c}'' }; } option.grid = { left: ''3%'', right: ''4%'', bottom: ''10%'', top: ''10%'', containLabel: true }; option.tooltip = { trigger: ''axis'', axisPointer: { type: ''shadow'' }, formatter: ''{b}: {c}'' }; if (option.xAxis) { option.xAxis.axisLabel = { rotate: 0, interval: 0 }; } if (option.yAxis) { option.yAxis.name = ''数量''; option.yAxis.nameTextStyle = { padding: [0, 0, 0, 10] }; } return { ...payload, data: option };"\u000a    },\u000a    "height": 350,\u000a    \u000a    "clickAction": {\u000a        "actionType": "dialog",\u000a        "dialog": {\u000a            "title": "${event.name} - 详细数据 (共${event.value}条)",\u000a            "size": "xl",\u000a            "actions": [\u000a                {\u000a                    "type": "button",\u000a                    "label": "导出数据",\u000a                    "level": "primary",\u000a                    "actionType": "download",\u000a                    "api": {\u000a                        "method": "get",\u000a                        "url": "/api/export/bar-data?category=${event.name}"\u000a                    }\u000a                },\u000a                {\u000a                    "type": "button",\u000a                    "label": "关闭",\u000a                    "actionType": "close"\u000a                }\u000a            ],\u000a            "data": {\u000a                "selectedCategory": "${event.name}",\u000a                "selectedValue": "${event.value}"\u000a            },\u000a            "body": {\u000a                "type": "service",\u000a                "api": {\u000a                    "method": "get",\u000a                    "url": "/api/demo/bar-detail",\u000a                    "requestAdaptor": "const category = api.data?.selectedCategory || ''''; return { ...api, url: api.url + ''?category='' + encodeURIComponent(category) };"\u000a                },\u000a                "body": {\u000a                    "type": "crud",\u000a                    "syncLocation": false,\u000a                    "api": "${api}",\u000a                    "columns": [\u000a                        {\u000a                            "name": "id",\u000a                            "label": "ID",\u000a                            "width": 60\u000a                        },\u000a                        {\u000a                            "name": "name",\u000a                            "label": "名称"\u000a                        },\u000a                        {\u000a                            "name": "category",\u000a                            "label": "类别"\u000a                        },\u000a                        {\u000a                            "name": "value",\u000a                            "label": "数值",\u000a                            "type": "number"\u000a                        },\u000a                        {\u000a                            "name": "date",\u000a                            "label": "日期",\u000a                            "type": "date",\u000a                            "format": "YYYY-MM-DD"\u000a                        },\u000a                        {\u000a                            "name": "status",\u000a                            "label": "状态",\u000a                            "type": "mapping",\u000a                            "map": {\u000a                                "active": "<span class=''label label-success''>正常</span>",\u000a                                "pending": "<span class=''label label-warning''>待处理</span>",\u000a                                "inactive": "<span class=''label label-default''>已关闭</span>"\u000a                            }\u000a                        },\u000a                        {\u000a                            "type": "operation",\u000a                            "label": "操作",\u000a                            "width": 120,\u000a                            "buttons": [\u000a                                {\u000a                                    "type": "button",\u000a                                    "label": "详情",\u000a                                    "level": "link",\u000a                                    "icon": "fa fa-eye",\u000a                                    "actionType": "dialog",\u000a                                    "dialog": {\u000a                                        "title": "详细信息 - ${name}",\u000a                                        "size": "lg",\u000a                                        "body": {\u000a                                            "type": "form",\u000a                                            "mode": "horizontal",\u000a                                            "wrapWithPanel": false,\u000a                                            "initApi": {\u000a                                                "method": "get",\u000a                                                "url": "/api/demo/item/${id}"\u000a                                            },\u000a                                            "body": [\u000a                                                {\u000a                                                    "type": "static",\u000a                                                    "name": "id",\u000a                                                    "label": "ID"\u000a                                                },\u000a                                                {\u000a                                                    "type": "static",\u000a                                                    "name": "name",\u000a                                                    "label": "名称"\u000a                                                },\u000a                                                {\u000a                                                    "type": "static",\u000a                                                    "name": "category",\u000a                                                    "label": "类别"\u000a                                                },\u000a                                                {\u000a                                                    "type": "static",\u000a                                                    "name": "value",\u000a                                                    "label": "数值"\u000a                                                },\u000a                                                {\u000a                                                    "type": "static",\u000a                                                    "name": "date",\u000a                                                    "label": "日期"\u000a                                                }\u000a                                            ]\u000a                                        }\u000a                                    }\u000a                                }\u000a                            ]\u000a                        }\u000a                    ],\u000a                    "perPageAvailable": [10, 20, 50],\u000a                    "perPage": 10\u000a                }\u000a            }\u000a        }\u000a    }\u000a    \u000a}\u000a\u000a                        ]\u000a                    },\u000a                    {\u000a                        "md": 4,\u000a                        "style": {\u000a                            "borderLeft": "1px dashed ",\u000a                            "paddingLeft": "40px",\u000a                            "height": "80%",\u000a                            "margin": "auto 0",\u000a                            "display": "flex",\u000a                            "flexDirection": "column",\u000a                            "justifyContent": "center"\u000a                        },\u000a                        "body": \u000a\u000a[\u000a    \u000a]\u000a\u000a                    }\u000a                ]\u000a            }\u000a        },\u000a        {\u000a            "type": "tpl",\u000a            "tpl": "<div style=''text-align: center; color: #999; font-size: 12px; padding: 20px 0;''></div>"\u000a        }\u000a    ]\u000a}\u000a'),1,1,NULL,'2025-12-18 15:00:00','2025-12-18 15:00:00','chart_demo','{"title":"Trace Title","subtitle":"Trace Subtitle","height":350,"bar_height":350,"bar_api_url":"/api/test","line_height":350,"line_api_url":"/api/test","api_url":"/api/chart"}');
INSERT INTO sys_page_template VALUES(48,'config','系统配置中心',unistr('{\u000a    "type": "page",\u000a    "title": "\\u7cfb\\u7edf\\u914d\\u7f6e\\u4e2d\\u5fc3",\u000a    "titleClassName": "text-center",\u000a    "css": {\u000a        ".cxd-Page-title": {\u000a            "text-align": "center !important",\u000a            "display": "block !important",\u000a            "width": "100%",\u000a            "font-size": "28px",\u000a            "font-weight": "600",\u000a            "margin-bottom": "30px",\u000a            "color": "#1d1d1f"\u000a        }\u000a    },\u000a    "body": [\u000a        {\u000a            "type": "tabs",\u000a            "tabsMode": "line",\u000a            "tabs": [\u000a                {\u000a                    "title": "\\ud83d\\uddfa\\ufe0f \\u8def\\u7531\\u7ba1\\u7406",\u000a                    "icon": "fa fa-sitemap",\u000a                    "body": [\u000a                        {\u000a                            "type": "alert",\u000a                            "level": "info",\u000a                            "body": "\\ud83d\\udca1 \\u7ba1\\u7406\\u5e94\\u7528\\u7684\\u4e3b\\u8def\\u7531\\u914d\\u7f6e\\u3002\\u6bcf\\u4e2a\\u4e3b\\u8def\\u7531\\u5bf9\\u5e94\\u4e00\\u4e2a\\u72ec\\u7acb\\u7684\\u529f\\u80fd\\u6a21\\u5757\\uff08\\u5982 /dashboard, /system\\uff09\\u3002",\u000a                            "className": "m-b"\u000a                        },\u000a                        {\u000a                            "type": "crud",\u000a                            "syncLocation": false,\u000a                            "api": "/api/routes",\u000a                            "headerToolbar": [\u000a                                {\u000a                                    "type": "button",\u000a                                    "label": "\\u65b0\\u5efa\\u8def\\u7531",\u000a                                    "icon": "fa fa-plus",\u000a                                    "level": "primary",\u000a                                    "actio