 ''/''); return {...api, url: fullUrl}; } else { const baseData = {}; return {...api, data: {...baseData, selectedId}}; }"},"perPageAvailable":[10,20,50],"perPage":10,"footerToolbar":["statistics","switch-per-page","pagination"],"columns":[{"name":"id","label":"ID","width":60},{"name":"customer_name","label":"客户名称"},{"name":"risk_score","label":"风险评分","type":"number"},{"name":"status","label":"状态"},{"name":"amount","label":"金额","type":"number"},{"name":"overdue_days","label":"逾期天数"}]}}}}},{"md":4,"style":{"borderLeft":"1px dashed #e8e8e8","paddingLeft":"40px","height":"80%","margin":"auto 0","display":"flex","flexDirection":"column","justifyContent":"center"},"body":[{"type":"tpl","tpl":"<div style=''margin-bottom: 5px;''><span style=''background: #0050b3; color: #fff; padding: 4px 10px; border-radius: 4px; font-size: 12px; font-weight: bold;''>风险分析</span></div><div style=''margin-bottom: 25px; font-size: 14px; line-height: 1.6; color: #666;''>当前高风险客户占比较高，需要重点关注。极高风险和高风险客户合计占比约23%。</div>"},{"type":"tpl","tpl":"<div style=''margin-bottom: 5px;''><span style=''background: #006d75; color: #fff; padding: 4px 10px; border-radius: 4px; font-size: 12px; font-weight: bold;''>规避建议</span></div><div style=''font-size: 14px; line-height: 1.6; color: #666;''>1. 对极高、高风险客户实施每日监控<br/>2. 启动专项催收计划</div>"}]}]}]},{"type":"container","body":[{"type":"form","title":"向 AI 提问","target":"ai-result-service","mode":"horizontal","body":[{"type":"textarea","name":"userPrompt","label":"请输入分析需求","placeholder":"例如：生成贷款逾期分析图表","value":"生成贷款逾期分析图表","required":true,"minRows":3,"maxRows":6},{"type":"submit","label":"开始分析","level":"primary"}]},{"type":"divider"},{"type":"service","name":"ai-result-service","schemaApi":{"method":"post","url":"/api/ai/generate-page","data":{"pageId":"biaoti","query":"${userPrompt}"},"sendOn":"this.userPrompt"}}]}]},{"title":"趋势分析","body":[{"type":"container","body":[{"type":"tpl","tpl":"<h3 style=''margin: 0 0 16px 0; font-size: 18px; font-weight: 600; color: #262626;''>