INSERT INTO sys_page_template VALUES(61,'cs1222','cs1222',unistr('\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false             \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "text-center",\u000a            "style": {\u000a                "width": "100%"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "tpl",\u000a                    "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>cs1222</h2>"\u000a                },\u000a                {\u000a                    "type": "tpl",\u000a                    "tpl": "<div style=''color: #8c8c8c; font-size: 13px;''>静态文字</div>"\u000a                }\u000a            ]\u000a        }\u000a        \u000a        ,\u000a        \u000a    {\u000a        "type": "button",\u000a        "label": "生成风险分析报告",\u000a        "level": "danger",\u000a        "style": {\u000a            "position": "absolute",        \u000a            "right": "20px",               \u000a            "top": "50%",                  \u000a            "transform": "translateY(-50%)", \u000a            "zIndex": "10"\u000a        },\u000a        "onEvent": {\u000a            "click": {\u000a                "actions": [\u000a                    \u000a                    {\u000a    