INSERT INTO sys_page_template VALUES(128,'fwfx','住房公积金房屋风险',unistr('\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false             \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_risk/management=metrics_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": {     "cxlx":"{\\"titleKey\\": \\"fxgl_fwfx_title\\"}",     "jgbh": "1305282025" }\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>住房公积金房屋风险</h2>"\u000a                        },\u000a                        {\u000a                            "type": "tpl",\u000a    