offset=''60'' stroke-linecap=''round''></circle></svg><div style=''position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; font-size: 22px; font-weight: 700; color: #1890ff; font-feature-settings: \\"tnum\\";''><span id=''modal-timer-sec''>0</span><span style=''font-size: 12px; margin-left: 2px; font-weight: 400;''>s</span></div></div><div style=''font-size: 18px; font-weight: 600; color: #333; margin-bottom: 12px; letter-spacing: 0.5px; text-shadow: 0 2px 10px rgba(255,255,255,0.8);''>AI 智能分析中</div><div id=''modal-timer-text'' style=''font-size: 14px; color: #666; height: 20px; font-weight: 500;''>正在接入数据中心...</div><style>@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }</style></div>",\u000a                            "onMount": "const startTime = Date.now(); const secDom = document.getElementById(''modal-timer-sec''); const textDom = document.getElementById(''modal-timer-text''); const texts = [''正在加载业务数据...'', ''正在构建风险模型...'', ''AI 正在生成洞察...'', ''正在渲染分析报告...'']; window.modalTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                            "onUnmount": "clearInterval(window.modalTimer);"\u000a                        }\u000a                    ]\u000a                }\u000a            ]\u000a        }\u000a\u000a        \u000a        \u000a        \u000a         \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        ,{\u000a            "type": "service",\u000a            "id": "risk_analysis_service_inner", \u000a            \u000a            \u000a            "className": "${!show_analysis_result ? ''hidden'' : ''m-t-md''}",\u000a            \u000a            "initFetch": false,\u000a            "spinner": null, \u000a\u000a            "schemaApi": {\u000a                "method": "post",\u000a                "url": "/api/ai/generate-page",\u000a                \u000a                \u000a                "sendOn": "this.ai_loading === true",\u000a                \u000a                "data": {\u000a                    "pageId": "fwfx",\u000a                    "workflow_type": "ai_analysis",  \u000a                    \u000a                    "query": "${user_query}",\u000a                    \u000a                    "timestamp": "${date(now(), ''x'')}"\u000a                }\u000a            },\u000a            \u000a            "onEvent": {\u000a                \u000a                \u000a                "fetchSchemaInited": {\u000a                    "actions": [\u000a                        {\u000a                            "actionType": "setValue",\u000a                            "componentId": "global_page_root",\u000a                            "args": {\u000a                                "value": {\u000a                                    "ai_loading": false\u000a                                }\u000a                            }\u000a                        },\u000a                        {\u000a                            "actionType": "toast",\u000a                            "args": { "msgType": "success", "msg": "分析完成" }\u000a                        }\u000a                    ]\u000a                },\u000a                \u000a                \u000a                "fetchFailed": {\u000a                    "actions": [\u000a                        {\u000a                            "actionType": "setValue",\u000a                            "componentId": "global_page_root",\u000a                            "args": { "value": { "ai_loading": false } }\u000a                        },\u000a                        {\u000a                            "actionType": "toast",\u000a                            "args": { "msgType": "error", "msg": "服务异常，请