etElementById(''report-timer-text''); const texts = [''正在准备数据...'', ''正在调用AI分析...'', ''正在生成报告...'', ''即将完成...'']; window.reportTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                "onUnmount": "clearInterval(window.reportTimer);"\u000a            }]\u000a        },\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${show_report_result}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(0, 0, 0, 0.5)",\u000a                "zIndex": "9998",\u000a                "display": "flex",\u000a                "alignItems": "flex-start",\u000a                "justifyContent": "center",\u000a                "paddingTop": "20px",\u000a                "paddingBottom": "20px"\u000a            },\u000a            "body": [{\u000a                "type": "container",\u000a                "id": "report_dialog_box",\u000a                "style": {\u000a                    "backgroundColor": "#ffffff",\u000a                    "borderRadius": "8px",\u000a                    "width": "95%",\u000a                    "maxWidth": "1400px",\u000a                    "height": "80vh",\u000a                    "display": "flex",\u000a                    "flexDirection": "column",\u000a                    "boxShadow": "0 4px 20px rgba(0,0,0,0.3)",\u000a                    "position": "relative",\u000a                    "overflow": "hidden"\u000a                },\u000a                "body": [\u000a                    \u000a                    {\u000a                        "type": "button",\u000a                        "label": "✕",\u0