_report_button":true,"title":"住房公积金死亡提取政策","subtitle_api":"/HFB/common/dmx_policy/management=title_query.service","subtitle_api_method":"post","subtitle_api_data":"{ \t\"cxlx\":\"{\\\"titleKey\\\": \\\"zcyc_swtq_title\\\"}\", \t\"jgbh\": \"1305282025\"  }","report_button_label":"生成政策预测报告","columns":"4","api_url":"/HFB/common/dmx_policy/management=metrics_query.service","api_method":"post","api_data":"{     \"cxlx\": \"{\\\"metricsKey\\\":\\\"zcyc_swtq\\\"}\",     \"jgbh\": \"1305282025\" }","form_title":"调整政策参数","policy_groups":"[     {         \"title\": \"死亡提取参数\",         \"columns\": 4,         \"fields\": [             {                 \"name\": \"swtq_zmyq\",                 \"label\": \"死亡证明要求\",                 \"type\": \"input-text\",                 \"value\": \"医院/公安\"             },             {                 \"name\": \"swtq_gxzm\",                 \"label\": \"继承关系证明\",                 \"type\": \"input-text\",                 \"value\": \"公证书/法院判决\"             },             {                 \"name\": \"swtq_blsx\",                 \"label\": \"办理时限(天)\",                 \"type\": \"input-number\",                  \"value\":3             },             {                 \"name\": \"swtq_sfqbdc\",                 \"label\": \"是否要求全部继承人到场\",                 \"type\": \"select\",                 \"options\": [                     {                         \"label\": \"是\",                         \"value\": \"是\"                     },                     {                         \"label\": \"否\",                         \"value\": \"否\"                     }                 ],                 \"value\": \"是\"             }         ]     } ]","policy_actions":"[     {         \"label\": \"📊 智能分析\",         \"actionType\": \"ai_analysis\",         \"level\": \"danger\"     },     {         \"label\": \"🔄 重置\",         \"actionType\": \"reset\",         \"level\": \"default\",         \"style\": {             \"marginLeft\": \"10px\"         }     } ]","page_key":"swtq","alert_html":"<div style=\"margin: -13px -17px; background: white; padding: 16px 20px; border: 1px solid #e8e8e8;\"> \t<!-- 标题行 --> \t<div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 16px;\"> \t\t<div \t\t\tstyle=\"background: #3b82f6; color: white; border-radius: 3px; padding: 3px 8px; font-weight: bold; font-size: 11px;\"> \t\t\tATM </div> \t\t<div style=\"color: #1a202c; font-weight: 600; font-size: 15px;\"> 死亡提取政策</div> \t</div> <!-- 总则 --> \t<div style=\"margin-bottom: 14px;\"> \t\t<div style=\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\"> 总则 </div> \t\t<div style=\"color: #4a5568; font-size: 13px; line-height: 1.6;\">为规范住房公积金因职工死亡或被宣告死亡的提取行为，保障继承人合法权益，依据《住房公积金管理条例》及本市相关规定，制定本政策。</div> \t</div> <!-- 细则 --> \t<div> \t\t<div style=\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\"> 细则 </div> \t\t<div style=\"color: #4a5568; font-size: 13px; line-height: 1.7;\"> \t\t\t<div style=\"margin-bottom: 4px;\">1、职工死亡或被宣告死亡的，其合法继承人可申请提取住房公积金；</div> \t\t\t<div style=\"margin-bottom: 4px;\">2、提取金额为账户全部余额；</div> \t\t\t<div style=\"margin-bottom: 4px;\">3、需提供死亡证明和继承关系证明；</div> \t\t\t<div style=\"margin-bottom: 4px;\">4、提取后账户注销；</div> \t\t</div> \t</div> </div>"}');
INSERT INTO sys_page_template VALUES(216,'ltxtq','住房公积金离退休提取政策',unistr('\u000a\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false,            \u000a        "show_prediction": false        \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_policy/management=title_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": { \u0009"cxlx":"{\\"titleKey\\": \\"zcyc_ltxtq_title\\"}", \u0009"jgbh": "1305282025"  }\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>住房公积金离退休提取政策</h2>"\u000a                        },\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<div style=''color: #8c8c8c; font-size: 13px;''>${displayText}</div>"\u000a                        }\u000a                    ]\u000a                }\u000a                \u000a                ,\u000a                \u000a    {\u000a        "type": "button",\u000a        "label": "生成政策预测报告",\u000a        "level": "danger",\u000a        "style": {\u000a            "position": "absolute",        \u000a            "right": "20px",               \u000a            "top": "50%",                  \u000a            "transform": "translateY(-50%)", \u000a            "zIndex": "10"\u000a        },\u000a        "onEvent": {\u000a            "click": {\u000a                "actions": [\u000a                    \u000a                    \u000a                    {\u000a                        "actionType": "setValue",\u000a                        "componentId": "global_page_root",\u000a                        "args": {\u000a                            "value": {\u000a                                "show_report_result": true,\u000a                                "report_loading": true\u000a                            }\u000a                        }\u000a                    }\u000a                ]\u000a            }\u000a        }\u000a    }\u000a    \u000a                \u000a            ]\u000a        }\u000a        \u000a        \u000a        \u000a    ]\u000a}\u000a\u000a\u000a\u000a,{\u000a    "type": "service",\u000a    "id": "report_display_root",\u000a    "className": "p-none",\u000a    "body": [\u000a        \u000a        {\u000a            "type": "tpl",\u000a            "tpl": "<style>.report-content-area { max-height: calc(80vh - 120px) !important; overflow-y: auto !important; } .report-content-area > * { max-height: 100%; }</style>"\u000a        },\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${report_loading}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(255, 255, 255, 0.9)",\u000a                "zIndex": "10000",\u000a                "display": "flex",\u000a                "alignItems": "center",\u000a                "justifyContent": "center",\u000a                "backdropFilter": "blur(8px)"\u000a            },\u000a            "body": [{\u000a                "type": "custom",\u000a                "name": "report-timer",\u000a                "html": "<div style=''font-family: -apple-system, BlinkMacSystemFont, Helvetica Neue, Arial; color: #333;''><div style=''position: relative; width: 80px; height: 80px; margin: 0 auto 24px auto;''><svg viewBox=''0 0 50 50'' style=''width: 100%; height: 100%; animation: spin 2s linear infinite;''><circle cx=''25'' cy=''25'' r=''20'' fill=''none'' stroke=''#e6f7ff'' stroke-width=''4''></circle><circle cx=''25'' cy=''25'' r=''20'' fill=''none'' stroke=''#1890ff'' stroke-width=''4'' stroke-dasharray=''80'' stroke-dashoffset=''60'' stroke-linecap=''round''></circle></svg><div style=''position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; font-size: 22px; font-weight: 700; color: #1890ff;''><span id=''report-timer-sec''>0</span><span style=''font-size: 12px; margin-left: 2px; font-weight: 400;''>s</span></div></div><div style=''font-size: 18px; font-weight: 600; color: #333; margin-bottom: 12px;''>正在生成报告</div><div id=''report-timer-text'' style=''font-size: 14px; color: #666;''>正在准备数据...</div><style>@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }</style></div>",\u000a                "onMount": "const startTime = Date.now(); const secDom = document.getElementById(''report-timer-sec''); const textDom = document.getElementById(''report-timer-text''); const texts = [''正在准备数据...'', ''正在调用AI分析...'', ''正在生成报告...'', ''即将完成...'']; window.reportTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                "onUnmount": "clearInterval(window.reportTimer);"\u000a            }]\u000a        },\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${show_report_result}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(0, 0, 0, 0.5)",\u000a                "zIndex": "9998",\u000a                "display": "flex",\u000a                "alignItems": "flex-start",\u000a                "justifyContent": "center",\u000a                "paddingTop": "20px",\u000a                "paddingBottom": "20px"\u000a            },\u000a            "body": [{\u000a                "type": "container",\u000a                "id": "report_dialog_box",\u000a                "style": {\u000a                    "backgroundColor": "#ffffff",\u000a                    "borderRadius": "8px",\u000a                    "width": "95%",\u000a                    "maxWidth": "1400px",\u000a                    "height": "80vh",\u000a                    "display": "flex",\u000a                    "flexDirection": "column",\u000a                    "boxShadow": "0 4px 20px rgba(0,0,0,0.3)",\u000a                    "position": "relative",\u000a                    "overflow": "hidden"\u000a                },\u000a                "body": [\u000a                    \u000a                    {\u000a                        "type": "button",\u000a                        "label": "✕",\u000a                        "level": "link",\u000a                        "style": {\u000a                            "position": "absolute",\u000a                            "top": "12px",\u000a                            "right": "16px",\u000a                            "color": "white",\u000a                            "fontSize": "20px",\u000a                            "padding": "0",\u000a                            "width": "28px",\u000a                            "height": "28px",\u000a                            "minWidth": "28px",\u000a                            "zIndex": "10",\u000a                            "lineHeight": "28px",\u000a                            "textAlign": "center"\u000a                        },\u000a                        "onEvent": {\u000a                            "click": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "show_report_result": false,\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            }\u000a                        }\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "custom",\u000a                        "html": "<div id=''report-drag-header'' style=''background-color: #1a3c6e; color: white; padding: 14px 50px 14px 24px; border-radius: 8px 8px 0 0; cursor: move; user-select: none;''><span style=''font-size: 16px; font-weight: bold;''>📄 风险分析报告预览</span></div>",\u000a                        "onMount": "var header = document.getElementById(''report-drag-header''); var dialog = head