ired":false,"type":"input-text","placeholder":""},{"name":"actionType","label":"actionType (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"dialog","label":"dialog (自动推断)","required":false,"type":"input-text","placeholder":""}]}],"__debug":"adaptor executed","enable_report_button":true,"title":"住房公积金沟通提取政策","subtitle_api":"/HFB/common/dmx_policy/management=title_query.service","subtitle_api_method":"post","subtitle_api_data":"{ \t\"cxlx\":\"{\\\"titleKey\\\": \\\"zcyc_gftq_title\\\"}\", \t\"jgbh\": \"1305282025\"  }","report_button_label":"生成政策预测报告","alert_html":"<div style=\"margin: -13px -17px; background: white; padding: 16px 20px; border: 1px solid #e8e8e8;\">     <!-- 标题行 -->     <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 16px;\">         <div style=\"background: #3b82f6; color: white; border-radius: 3px; padding: 3px 8px; font-weight: bold; font-size: 11px;\">             AI         </div>         <div style=\"color: #1a202c; font-weight: 600; font-size: 15px;\">             购房提取政策</div>     </div> <!-- 总则 -->     <div style=\"margin-bottom: 14px;\">         <div style=\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\">             总则         </div>         <div style=\"color: #4a5568; font-size: 13px; line-height: 1.6;\">             为规范住房公积金购房提取行为，支持缴存职工购买自住住房，依据《住房公积金管理条例》及本市相关规定，制定本政策。</div>     </div>          <!-- 细则 -->     <div>         <div style=\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\">             细则         </div>         <div style=\"color: #4a5568; font-size: 13px; line-height: 1.7;\">             <div style=\"margin-bottom: 4px;\">1、职工购买自住住房的，可申请提取住房公积金；</div>             <div style=\"margin-bottom: 4px;\">2、提取额度不超过购房总价款，且不超过账户余额；</div>             <div style=\"margin-bottom: 4px;\">3、需在购房合同签订后两年内申请提取；</div>             <div style=\"margin-bottom: 4px;\">4、同一套住房只能提取一次，夫妻双方合计提取金额不超过购房总价款。</div>         </div>     </div> </div>","columns":"4","api_method":"post","api_url":"/HFB/common/dmx_policy/management=metrics_query.service","form_title":"调整政策参数","policy_groups":"[     {         \"title\": \"购房提取参数\",         \"columns\": 4,         \"fields\": [             {                 \"name\": \"gftq_maxtqje\",                 \"label\": \"购房总价提取上限(万元)\",                 \"type\": \"input-number\",                 \"value\": 150             },             {                 \"name\": \"gftq_tqbl\",                 \"label\": \"首次购房提取比例(%)\",                 \"type\": \"input-number\",                 \"value\": 100             },             {                 \"name\": \"gftq_sjjg\",                 \"label\": \"再次购房间隔要求(年)\",                 \"type\": \"input-number\",                 \"value\": 2             },             {                 \"name\": \"gftq_sfba\",                 \"label\": \"是否要求购房合同备案\",                 \"type\": \"select\",                 \"options\": [                     {                         \"label\": \"是\",                         \"value\": \"是\"                     },                     {                         \"label\": \"否\",                         \"value\": \"否\"                     }                 ],                 \"value\": \"是\"             }         ]     } ]","policy_actions":"[     {         \"label\": \"📊 智能分析\",         \"actionType\": \"ai_analysis\",         \"level\": \"danger\"     },     {         \"label\": \"🔄 重置\",         \"actionType\": \"reset\",         \"level\": \"default\",         \"style\": {             \"marginLeft\": \"10px\"         }     } ]","page_key":"gftq","api_data":"{     \"cxlx\": \"{\\\"metricsKey\\\":\\\"zcyc_gftq\\\"}\",     \"jgbh\": \"1305282025\" }"}');
