INSERT INTO sys_page_template VALUES(447,'tqfw','提取服务',unistr('\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a  \u000a\u000a  \u000a\u000a  \u000a\u000a  \u000a\u000a  \u000a\u000a  \u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a{\u000a  "type": "page",\u000a  "body": [\u000a    \u000a{\u000a  "type": "wrapper",\u000a  "className": "b-b p-b-md flex justify-between items-center bg-white",\u000a  "body": [\u000a    {\u000a      "type": "tpl",\u000a      "tpl": "<div class=''text-lg font-bold text-dark''>提取服务</div>"\u000a    }\u000a    \u000a    ,{\u000a      "type": "button",\u000a      "label": "刷新数据",\u000a      "icon": "fa fa-refresh",\u000a      "actionType": "reload",\u000a      "target": "card_service_1,card_service_2,card_service_3,card_service_4,card_service_5,card_service_6",\u000a      "level": "primary",\u000a      "size": "sm"\u000a    }\u000a    \u000a  ]\u000a}\u000a,\u000a    {\u000a      "type": "container",\u000a      "className": "p-md",\u000a      "body": [\u000a        \u000a\u000a{\u000a  "type": "container",\u000a  "name": "service_cards_grid",\u000a  "className": "service-cards-container",\u000a  "body": [\u000a    {\u000a      "type": "grid",\u000a      "columns": [\u000a        \u000a        {\u000a          "body": {\u000a            "type": "container",\u000a            "className": "service-card-item",\u000a            "style": {\u000a              "borderRadius": "12px",\u000a              "boxShadow": "0 4px 16px rgba(24,144,255,0.12)",\u000a              "border": "1px solid #e8f4ff",\u000a              "overflow": "hidden",\u000a              "background": "#fff",\u000a              "height": "100%",\u000a              "display": "flex",\u000a              "flexDirection": "column"\u000a            },\u000a            "body": [\u000a              \u000a              {\u000a                "type": "tpl",\u000a                "tpl": "<div style=''background: linear-gradient(135deg, #1890FF 0%, #40A9FF 100%); padding: 14px 18px; display: flex; align-items: center; gap: 12px; border-radius: 11px 11px 0 0;''><div style=''width: 40px; height: 40px; background: rgba(255,255,255,0.25); border-radius: 8px; display: flex; align-items: center; justify-content: center; backdrop-filter: blur(4px);''><i class=''fa fa-money'' style=''font-size: 20px; color: #fff;''></i></div><div style=''color: #fff; font-size: 15px; font-weight: 600; text-shadow: 0 1px 2px rgba(0,0,0,0.1);''>商业贷款提取精准推送</div></div>"\u000a              },\u000a              \u000a              {\u000a                "type": "container",\u000a                "style": {\u000a                  "padding": "16px 18px 12px 18px"\u000a                },\u000a                "body": [\u000a                  {\u000a                    "type": "tpl",\u000a                    "tpl": "<div style=''color: #555; font-size: 13px; line-height: 1.8; min-height: 56px;''>通过不动产登记与银行信贷数据分析，识别出符合提取办理条件但未办理商贷提取的缴存人，主动推送提取政策。</div>"\u000a                  }\u000a                ]\u000a              },\u000a              \u000a              \u000a              {\u000a                "type": "service",\u000a                "name": "card_service_1",\u000a                "api": {\u000a                  "method": "post",\u000a                  "dataType": "json",\u000a                  "url": "/HFB/common/dmx_proactive/management=metrics_query.service"\u000a                  \u000a                  ,"data": {"cxlx":{"metricsKey":"zdfw_sdtq"},"jgbh":"1305282025"}\u000a                  \u000a                },\u000a                "style": {\u000a                  "padding": "0 18px 16px 18px"\u000a                },\u000a                "body": {\u000a                  "type": "tpl",\u000a                  "tpl": "<div style=''background: linear-gradient(135deg, #E6F7FF 0%, #F0FAFF 100%); padding: 10px 14px; border-radius: 6px; border: 1px solid #91D5FF;''><span style=''color: #1890FF; font-weight: 500; font-size: 13px;