,                 \"options\": [                     {                         \"label\": \"是\",                         \"value\": \"是\"                     },                     {                         \"label\": \"否\",                         \"value\": \"否\"                     }                 ],                 \"value\": \"是\"             }         ]     } ]","policy_actions":"[     {         \"label\": \"📊 智能分析\",         \"actionType\": \"ai_analysis\",         \"level\": \"danger\"     },     {         \"label\": \"🔄 重置\",         \"actionType\": \"reset\",         \"level\": \"default\",         \"style\": {             \"marginLeft\": \"10px\"         }     } ]","id":486,"version":5,"mode":"update"}');
