\": [             {                 \"name\": \"zzldtq_lqsyx\",                 \"label\": \"失业保险领取要求\",                 \"type\": \"input-text\",                 \"value\": \"是\"             },             {                 \"name\": \"zzldtq_sysjyq\",                 \"label\": \"失业时间要求（月）\",                 \"type\": \"input-number\",                 \"value\": 6             }, \t\t\t{                 \"name\": \"zzldtq_tqsqsx\",                 \"label\": \"提取申请时限（月）\",                 \"type\": \"input-number\",                 \"value\": 24             },             {                 \"name\": \"zzldtq_sfyqcyz\",                 \"label\": \"是否要求就业创业证\",                  \"type\": \"select\",                 \"options\": [                     {                         \"label\": \"是\",                         \"value\": \"是\"                     },                     {                         \"label\": \"否\",                         \"value\": \"否\"                     }                 ],                 \"value\": \"是\"             }         ]     } ]","policy_actions":"[     {         \"label\": \"📊 智能分析\",         \"actionType\": \"ai_analysis\",         \"level\": \"danger\"     },     {         \"label\": \"🔄 重置\",         \"actionType\": \"reset\",         \"level\": \"default\",         \"style\": {             \"marginLeft\": \"10px\"         }     } ]","id":486,"version":5,"mode":"update","columns":"4","api_url":"/HFB/common/dmx_policy/management=metrics_query.service","api_method":"post","api_data":"{     \"cxlx\": \"{\\\"metricsKey\\\":\\\"zcyc_zzldtq\\\"}\",     \"jgbh\": \"1305282025\" }"}');
