INSERT INTO sys_page_template VALUES(582,'xypjzb','信用评价指标',unistr('\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a{\u000a  "type": "page",\u000a  "title": "信用评价指标",\u000a  "body": [\u000a    {\u000a      "type": "crud",\u000a      "name": "indicatorsCrud",\u000a      "api": {\u000a        "method": "post",\u000a        "url": "/HFB/aiyc/ywcj/xypjzbglcx",\u000a        "data": {\u000a          "jgbh": "1305282025",\u000a          \u000a          "subject": "${subject}",\u000a          "status": "${status}",\u000a          "page": "${page}",\u000a          "perPage": "${perPage}"\u000a        }\u000a      },\u000a\u000a      "syncLocation": false,\u000a      "headerToolbar": [\u000a        {\u000a          "type": "button",\u000a          "label": "新增指标",\u000a          "actionType": "dialog",\u000a          "level": "primary",\u000a          "icon": "fa fa-plus",\u000a          "dialog": {\u000a            "title": "新增信用评价指标",\u000a            "size": "md",\u000a            "body": {\u000a              "type": "form",\u000a              "api": {\u000a                "method": "post",\u000a                "url": "/api/demo/credit/indicators/create",\u000a                "data": {\u000a                  \u000a                  "&": "$$"\u000a                }\u000a              },\u000a              "body": [\u000a                {\u000a                  "type": "select",\u000a                  "name": "subject",\u000a                  "label": "主体类型",\u000a                  "required": true,\u000a                  "options": [\u000a                    { "label": "缴存单位", "value": "缴存单位" },\u000a                    { "label": "缴存人", "value": "缴存人" },\u000a                    { "label": "开发商", "value": "开发商" }\u000a                  ]\u000a                },\u000a                {\u000a                  "type": "input-text",\u000a                  "name": "name",\u000a                  "label": "监控指标",\u000a    