取政策\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"zzldtq_lqsyx\",\n        \"label\": \"失业保险领取要求\",\n        \"type\": \"input-text\",\n        \"value\": \"是\"\n      },\n      {\n        \"name\": \"zzldtq_sysjyq\",\n        \"label\": \"失业时间要求（月）\",\n        \"type\": \"input-number\",\n        \"value\": 6\n      },\n      {\n        \"name\": \"zzldtq_tqsqsx\",\n        \"label\": \"提取申请时限（月）\",\n        \"type\": \"input-number\",\n        \"value\": 24\n      },\n      {\n        \"name\": \"zzldtq_sfyqcyz\",\n        \"label\": \"是否要求就业创业证\",\n        \"type\": \"select\",\n        \"options\": [\n          {\n            \"label\": \"是\",\n            \"value\": \"是\"\n          },\n          {\n            \"label\": \"否\",\n            \"value\": \"否\"\n          }\n        ],\n        \"value\": \"是\"\n      }\n    ]\n  }\n]","policy_actions":"[\n  {\n    \"label\": \"📊 智能分析\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  },\n  {\n    \"label\": \"🔄 重置\",\n    \"actionType\": \"reset\",\n    \"level\": \"default\",\n    \"style\": {\n      \"marginLeft\": \"10px\"\n    }\n  }\n]","id":486,"version":5,"mode":"update","columns":"4","api_url":"/HFB/common/dmx_policy/management=metrics_query.service","api_method":"post","api_data":"{\n  \"cxlx\": \"{\\n  \\\"metricsKey\\\": \\\"zcyc_zzldtq\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}"}');
