  \"name\": \"czdbtq_bzce\",\n        \"label\": \"低保标准差额提取\",\n        \"type\": \"input-text\",\n        \"value\": \"100%\"\n      },\n      {\n        \"name\": \"czdbtq_tqcs\",\n        \"label\": \"年度提取次数上限\",\n        \"type\": \"input-number\",\n        \"value\": 6\n      },\n      {\n        \"name\": \"czdbtq_clyq\",\n        \"label\": \"证明材料要求\",\n        \"type\": \"input-text\",\n        \"value\": \"低保证+收入证明\"\n      },\n      {\n        \"name\": \"czdbtq_sfdc\",\n        \"label\": \"是否要求入户调查\",\n        \"type\": \"select\",\n        \"options\": [\n          {\n            \"label\": \"是\",\n            \"value\": \"是\"\n          },\n          {\n            \"label\": \"否\",\n            \"value\": \"否\"\n          }\n        ],\n        \"value\": \"是\"\n      }\n    ]\n  }\n]","policy_actions":"[\n  {\n    \"label\": \"📊 智能分析\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  },\n  {\n    \"label\": \"🔄 重置\",\n    \"actionType\": \"reset\",\n    \"level\": \"default\",\n    \"style\": {\n      \"marginLeft\": \"10px\"\n    }\n  }\n]","id":488,"version":2,"mode":"update","columns":"4","api_url":"/HFB/common/dmx_policy/management=metrics_query.service","api_method":"post","api_data":"{\n  \"cxlx\": \"{\\n  \\\"metricsKey\\\": \\\"zcyc_czdbtq\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}"}');
