'); var dialog = header.closest(''[data-component-id=\\"report_dialog_box\\"]'') || header.parentElement.parentElement; var isDragging = false; var offsetX = 0; var offsetY = 0; header.onmousedown = function(e) { isDragging = true; offsetX = e.clientX - dialog.offsetLeft; offsetY = e.clientY - dialog.offsetTop; dialog.style.position = ''fixed''; dialog.style.margin = ''0''; }; document.onmousemove = function(e) { if (isDragging) { dialog.style.left = (e.clientX - offsetX) + ''px''; dialog.style.top = (e.clientY - offsetY) + ''px''; } }; document.onmouseup = function() { isDragging = false; };",\u000a                        "onUnmount": "document.onmousemove = null; document.onmouseup = null;"\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "service",\u000a                        "id": "report_service_inner",\u000a                        "className": "report-content-area",\u000a                        "style": {\u000a                            "flex": "1 1 0",\u000a                            "minHeight": "0",\u000a                            "overflowY": "auto",\u000a                            "padding": "24px",\u000a                            "backgroundColor": "#ffffff"\u000a                        },\u000a                        "schemaApi": {\u000a                            "method": "post",\u000a                            "url": "/api/ai/generate-page",\u000a                            "sendOn": "${report_loading === true}",\u000a                            "data": {\u000a                                "pageId": "gftq",\u000a                                "workflow_type": "report_generation",\u000a                                "query": "生成 gftq 分析报告",\u000a                                "timestamp": "${date(now(), ''x'')}"\u000a                                \u000a                            }\u000a                        },\u000a                        "onEvent": {\u000a                            "fetchSchemaInited": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            },\u000a                            "fetchFailed": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            }\u000a                        }\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "flex",\u000a                        "justify": "space-between",\u000a                        "alignItems": "center",\u000a                        "style": {\u000a                            "padding": "16px 24px",\u000a                            "backgroundColor": "#fafafa",\u000a                            "borderTop": "1px solid #f0f0f0",\u000a                            "margin": 0\u000a                        },\u000a                        "items": [\u000a                            {\u000a                                "type": "tpl",\u000a                                "tpl": "<div style=''display: flex; align-items: center; color: #888; font-size: 13px;''><i cla