lert_html":"<div style=\"margin: -13px -17px; background: white; padding: 16px 20px; border: 1px solid #e8e8e8;\"> \t<!-- 标题行 --> \t<div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 16px;\"> \t\t<div style=\"color: #1a202c; font-weight: 600; font-size: 15px;\"> \t\t\t贷后政策调整预测 \t\t</div> \t</div> \t<!-- 定义 --> \t<div style=\"margin-bottom: 14px;\"> \t\t<div style=\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\"> \t\t\t总则 \t\t</div> \t\t<div style=\"color: #4a5568; font-size: 13px; line-height: 1.6;\"> \t\t\t为规范住房公积金贷款还款管理，优化贷后政策，提高资金回收效率，保障资金安全，依据《住房公积金管理条例》及相关规定，制定本贷后政策分析体系。 \t\t</div> \t</div> \t<!-- 细则 --> \t<div> \t\t<div style=\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\"> \t\t\t细则 \t\t</div> \t\t<div class=\"policy-details\" style=\"color: #4a5568; font-size: 13px; line-height: 1.6;\"> \t\t\t<div style=\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\"> \t\t\t\t一、提前还款 \t\t\t</div> \t\t\t<ul style=\"list-style-type: none; padding-left: 0;line-height: 1.8;\"> \t\t\t\t<li> \t\t\t\t\t1、提前还款需正常还贷满6个月且申请时贷款未逾期； \t\t\t\t\t</i> \t\t\t\t\t<li> \t\t\t\t\t\t2、提前还本业务需间隔12个月； \t\t\t\t\t\t</i> \t\t\t\t\t\t<li> \t\t\t\t\t\t\t3、提前还款金额单次不得少于1万元； \t\t\t\t\t\t\t</i> \t\t\t\t\t\t\t<li> \t\t\t\t\t\t\t\t4、提取住房公积金提前偿还部分贷款本金，还贷额应不得低于2.5万元； \t\t\t\t\t\t\t\t</i> \t\t\t</ul> \t\t\t<div style=\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\"> \t\t\t\t二、逾期贷款 \t\t\t</div> \t\t\t<ul style=\"list-style-type: none; padding-left: 0;line-height: 1.8;\"> \t\t\t\t<li> \t\t\t\t\t1、转逾期宽限期3天； \t\t\t\t\t</i> \t\t\t\t\t<li> \t\t\t\t\t\t2、免收罚息天数10天； \t\t\t\t\t\t</i> \t\t\t</ul> \t\t\t<div style=\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\"> \t\t\t\t三、期限变更 \t\t\t</div> \t\t\t<ul style=\"list-style-type: none; padding-left: 0;line-height: 1.8;\"> \t\t\t\t<li> \t\t\t\t\t1、期限变更后，月还款额不超过家庭月收入的50%； \t\t\t\t\t</i> \t\t\t</ul> \t\t\t<div style=\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\"> \t\t\t\t四、签约对冲还贷 \t\t\t</div> \t\t\t<ul style=\"list-style-type: none; padding-left: 0;line-height: 1.8;\"> \t\t\t\t<li> \t\t\t\t\t1、账户余额需大于6个月的月还款额。 \t\t\t\t\t</i> \t\t\t</ul> \t\t</div> \t</div> </div>","api_data":"{\n  \"cxlx\": \"{\\n  \\\"metricsKey\\\": \\\"zcyc_gjjdhzc_value\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}","api_url":"/HFB/common/dmx_policy/management=metrics_query.service","columns":"4","api_method":"post","form_title":"调整政策参数","footer_text":"","enable_query_input":true,"policy_groups":"[\n  {\n    \"title\": \"提前还款\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"dhzc_zchkys\",\n        \"label\": \"提前还款需正常还贷月数\",\n        \"type\": \"input-number\",\n        \"value\": 6,\n        \"precision\": 0\n      },\n      {\n        \"name\": \"dhzc_tqhkjg\",\n        \"label\": \"提前还本间隔（月）\",\n        \"type\": \"input-number\",\n        \"value\": 12,\n        \"precision\": 0\n      },\n      {\n        \"name\": \"dhzc_tqhkzde\",\n        \"label\": \"提前还款最低额（万元）\",\n        \"type\": \"input-number\",\n        \"value\": 1,\n        \"precision\": 0\n      },\n      {\n        \"name\": \"dhzc_tqgjjhkzde\",\n        \"label\": \"提取公积金还贷最低额（万元）\",\n        \"type\": \"input-number\",\n        \"value\": 2.5,\n        \"precision\": 1\n      }\n    ]\n  },\n  {\n    \"title\": \"逾期贷款\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"dhzc_zyqkxq\",\n        \"label\": \"转逾期宽限期（天）\",\n        \"type\": \"input-number\",\n        \"value\": 3,\n        \"precision\": 0\n      },\n      {\n        \"name\": \"dhzc_msfxts\",\n        \"label\": \"免收罚息天数（天）\",\n        \"type\": \"input-number\",\n        \"value\": 10,\n        \"precision\": 0\n      }\n    ]\n  },\n  {\n    \"title\": \"期限变更\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"dhzc_yhkesrb\",\n        \"label\": \"月还款额不超过家庭月收入(%)\",\n        \"type\": \"input-number\",\n        \"value\": 50,\n        \"precision\": 0\n      }\n    ]\n  },\n  {\n    \"title\": \"签约对冲还贷\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"dhzc_zhyebs\",\n        \"label\": \"账户余额需大于月还款额的倍数\",\n        \"type\": \"input-number\",\n        \"value\": 6,\n        \"precision\": 0\n      }\n    ]\n  }\n]","id":333,"version":11,"mode":"update","policy_actions":"[\n  {\n    \"label\": \"AI预测\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  }\n]"}');
INSERT INTO sys_page_template VALUES(655,'gjjdqzc','贷前政策调整预测',unistr('\u000a\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false,            \u000a        "show_prediction": false        \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_policy/management=title_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": {\u000a  "cxlx": "{\\n  \\"titleKey\\": \\"zcyc_gjjdqzc_title\\"\\n}",\u000a  "jgbh": "1305282025"\u000a}\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>贷前政策调整预测</h2>"\u000a                        },\u000a       