m_title":"调整政策参数","policy_groups":"[\n  {\n    \"title\": \"出境定居提取参数\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"cjdjtq_djyq\",\n        \"label\": \"定居国家要求\",\n        \"type\": \"input-text\",\n        \"value\": \"永久居留权\"\n      },\n      {\n        \"name\": \"cjdjtq_djsj\",\n        \"label\": \"定居时间要求(年)\",\n        \"type\": \"input-number\",\n        \"value\": 1\n      },\n      {\n        \"name\": \"cjdjtq_zmcl\",\n        \"label\": \"证明材料要求\",\n        \"type\": \"input-text\",\n        \"value\": \"护照+签证\"\n      },\n      {\n        \"name\": \"cjdjtq_sfqz\",\n        \"label\": \"是否要求公证\",\n        \"type\": \"select\",\n        \"options\": [\n          {\n            \"label\": \"是\",\n            \"value\": \"是\"\n          },\n          {\n            \"label\": \"否\",\n            \"value\": \"否\"\n          }\n        ],\n        \"value\": \"是\"\n      }\n    ]\n  }\n]","policy_actions":"[\n  {\n    \"label\": \"📊 智能分析\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  },\n  {\n    \"label\": \"🔄 重置\",\n    \"actionType\": \"reset\",\n    \"level\": \"default\",\n    \"style\": {\n      \"marginLeft\": \"10px\"\n    }\n  }\n]","page_key":"cjdjtq","enable_query_input":true}');
