og = header.closest(''[data-component-id=\\"report_dialog_box\\"]'') || header.parentElement.parentElement; var isDragging = false; var offsetX = 0; var offsetY = 0; header.onmousedown = function(e) { isDragging = true; offsetX = e.clientX - dialog.offsetLeft; offsetY = e.clientY - dialog.offsetTop; dialog.style.position = ''fixed''; dialog.style.margin = ''0''; }; document.onmousemove = function(e) { if (isDragging) { dialog.style.left = (e.clientX - offsetX) + ''px''; dialog.style.top = (e.clientY - offsetY) + ''px''; } }; document.onmouseup = function() { isDragging = false; };",\u000a                        "onUnmount": "document.onmousemove = null; document.onmouseup = null;"\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "service",\u000a                        "id": "report_service_inner",\u000a                        "className": "report-content-area",\u000a                        "style": {\u000a                            "flex": "1 1 0",\u000a                            "minHeight": "0",\u000a                            "overflowY": "auto",\u000a                            "padding": "24px",\u000a                            "backgroundColor": "#ffffff"\u000a                        },\u000a                        "schemaApi": {\u000a                            "method": "post",\u000a                            "url": "/api/ai/generate-page",\u000a                            "sendOn": "${report_loading === true}",\u000a                            "data": {\u000a                                "pageId": "swtq",\u000a                                "workflow_type": "report_generation",\u000a                                "query": "生成 swtq 分析报告",\u000a                                "timestamp": "${date(now(), ''x'')}"\u000a                                \u000a                            }\u000a                        },\u000a                        "onEvent": {\u000a                      