 = btn.textContent; btn.disabled = true; btn.textContent = ''正在生成...''; const loadScript = (src) => new Promise((resolve, reject) => { if (document.querySelector(`script[src=''${src}'']`)) return resolve(); const script = document.createElement(''script''); script.src = src; script.onload = resolve; script.onerror = reject; document.head.appendChild(script); }); Promise.all([loadScript(''https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js''), loadScript(''https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'')]).then(() => { const { jsPDF } = window.jspdf; const reportContent = document.querySelector(''.report-content-area .cxd-Service'') || document.querySelector(''.report-content-area''); if (!reportContent) { alert(''未找到报告内容''); btn.disabled = false; btn.textContent = originalText; return; } html2canvas(reportContent, { scale: 2, useCORS: true, logging: true, backgroundColor: ''#ffffff'', scrollY: 0, windowWidth: reportContent.scrollWidth || 1200 }).then(canvas => { const imgData = canvas.toDataURL(''image/png''); const pdf = new jsPDF({ orientation: ''portrait'', unit: ''mm'', format: ''a4'' }); const pdfWidth = 210; const pdfHeight = 297; const margin = 10; const imgWidth = pdfWidth - margin * 2; const imgHeight = (canvas.height * imgWidth) / canvas.width; let heightLeft = imgHeight; let position = margin; pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); while (heightLeft > 0) { pdf.addPage(); position = margin - (imgHeight - heightLeft); pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); } pdf.save(''风险分析报告_'' + new Date().toISOString().split(''T'')[0] + ''.pdf''); btn.disabled = false; btn.textContent = originalText; }).catch(err => { console.error(''PDF error:'', err); alert(''PDF生成失败''); btn.disabled = false; btn.textContent = originalText; }); }).catch(err => { alert(''加载库失败''); btn.disabled = false; btn.textContent = originalText; });"\u000a                                                }]\u000a                                            }\u000a                                        }\u000a                                    }\u000a                                ]\u000a                            }\u000a                        ]\u000a                    }\u000a                ]\u000a            }]\u000a        }\u000a    ]\u000a}\u000a,\u000a\u000a        \u000a        \u000a\u000a{\u000a    "type": "tpl",\u000a    "tpl": "<div style=''margin-bottom: 12px; padding: 12px 16px; border-radius: 4px; background-color: #e6f7ff; border: 1px solid #91d5ff; color: #1890ff;''><div style=\\"margin: -13px -17px; background: white; padding: 16px 20px; border: 1px solid #e8e8e8;\\">     <!-- 标题行 -->     <div style=\\"display: flex; align-items: center; gap: 8px; margin-bottom: 16px;\\">         <div style=\\"background: #3b82f6; color: white; border-radius: 3px; padding: 3px 8px; font-weight: bold; font-size: 11px;\\">             ATM         </div>         <div style=\\"color: #1a202c; font-weight: 600; font-size: 15px;\\">             偿还贷款本息提取政策</div>     </div> <!-- 总则 -->     <div style=\\"margin-bottom: 14px;\\">         <div style=\\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\\">             总则         </div>         <div style=\\"color: #4a5568; font-size: 13px; line-height: 1.6;\\">为规范住房公积金用于偿还购房贷款本息的提取行为，减轻缴存职工还贷压力，依据《住房公积金管理条例》及本市相关规定，制定本政策。</div>     </div>          <!-- 细则 -->     <div>         <div style=\\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\\">             细则         </div>         <div style=\\"color: #4a5568; font-size: 13px; line-height: 1.7;\\">             <div style=\\"margin-bottom: 4px;\\">1、职工偿还购房贷款本息的，可申请提取住房公积金；</div>             <div style=\\"margin-bottom: 4px;\\">2、提取额度不超过当期应还贷款本息，且不超过账户余额；</div>             <div style=\\"margin-bottom: 4px;\\">3、每年可提取一次；</div>             <div style=\\"margin-bottom: 4px;\\">4、需提供贷款合同和还款明细；</div>         </div>     </div> </div></div>"\u000a}\u000a,\u000a\u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "m-t-md",\u000a            "style": {\u000a                "backgroundColor": "#fff",\u000a                "borderRadius": "10px",\u000a                "boxShadow": "0 4px 8px rgba(0, 0, 0, 0.05)",\u000a                "padding": "25px",\u000a                "marginBottom": "20px"\u000a            },\u000a            "body": [\u000a                \u000a                \u000a    {\u000a      "type": "service",\u000a      \u000a      "api": {\u000a        "method": "post",\u000a        "url": "/HFB/common/dmx_policy/management=metrics_query.service"\u000a        \u000a        ,"data": {"cxlx":"{\\n  \\"metricsKey\\": \\"zcyc_chdktq\\"\\n}","jgbh":"1305282025"}\u000a        \u000a        \u000a      },\u000a      \u000a      "body": [\u000a        \u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a          "type": "each",\u000a          "name": "${groups || [{ items: [], title: '''', columns: 4, border_color: '''' }]}",\u000a          "items": {\u000a            "type": "container",\u000a            "className": "m-b-md",\u000a            "body": [\u000a              {\u000a                "type": "html",\u000a                "tpl": "<div style=''font-weight: 600; font-size: 15px; margin-bottom: 12px; color: #1a3c6e; display: flex; align-items: center; gap: 8px;''>${title}</div>",\u000a                "visibleOn": "this.title"\u000a              },\u000a              {\u000a                "type": "container",\u000a                "className": "stats-cards-grid ${border_color ? ''border-'' + border_color : ''''} m-b-md",\u000a                "style": {\u000a                  "display": "flex",\u000a                  "flexWrap": "wrap",\u000a                  "gap": "16px",\u000a                  "width": "100%"\u000a            