t.getElementById(''report-timer-text''); const texts = [''正在准备数据...'', ''正在调用AI分析...'', ''正在生成报告...'', ''即将完成...'']; window.reportTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                "onUnmount": "clearInterval(window.reportTimer);"\u000a            }]\u000a        },\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${show_report_result}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(0, 0, 0, 0.5)",\u000a                "zIndex": "9998",\u000a                "display": "flex",\u000a                "alignItems": "flex-start",\u000a                "justifyContent": "center",\u000a                "paddingTop": "20px",\u000a                "paddingBottom": "20px"\u000a            },\u000a            "body": [{\u000a                "type": "container",\u000a                "id": "report_dialog_box",\u000a                "style": {\u000a                    "backgroundColor": "#ffffff",\u000a                    "borderRadius": "8px",\u000a                    "width": "95%",\u000a                    "maxWidth": "1400px",\u000a                    "height": "80vh",\u000a                    "display": "flex",\u000a                    "flexDirection": "column",\u000a                    "boxShadow": "0 4px 20px rgba(0,0,0,0.3)",\u000a                    "position": "relative",\u000a                    "overflow": "hidden"\u000a                },\u000a                "body": [\u000a                    \u000a                    {\u000a                        "type": "button",\u000a                        "label": "✕",\u000a                        "level": "link",\u000a                        "style": {\u000a                            "position": "absolute",\u000a                            "top": "12px",\u000a                            "right": "16px",\u000a                            "color": "white",\u000a                            "fontSize": "20px",\u000a                            "padding": "0",\u000a                            "width": "28px",\u000a                            "height": "28px",\u000a                            "minWidth": "28px",\u000a                            "zIndex": "10",\u000a                            "lineHeight": "28px",\u000a                            "textAlign": "center"\u000a                        },\u000a                        "onEvent": {\u000a                            "click": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "show_report_result": false,\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            }\u000a                        }\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "custom",\u000a                        "html": "<div id=''report-drag-header'' style=''background-color: #1a3c6e; color: white; padding: 14px 50px 14px 24px; border-radius: 8px 8px 0 0; cursor: move; user-select: none;''><span style=''font-size: 16px; font-weight: bold;''>📄 风险分析报告预览</span></div>",\u000a                        "onMount": "var header = document.getElementById(''report-drag-header''); var dialog = header.closest(''[data-component-id=\\"report_dialog_box\\"]'') || header.parentElement.parentElement; var isDragging = false; var offsetX = 0; var offsetY = 0; header.onmousedown = function(e) { isDragging = true; offsetX = e.clientX - dialog.offsetLeft; offsetY = e.clientY - dialog.offsetTop; dialog.style.position = ''fixed''; dialog.style.margin = ''0''; }; document.onmousemove = function(e) { if (isDragging) { dialog.style.left = (e.clientX - offsetX) + ''px''; dialog.style.top = (e.clientY - offsetY) + ''px''; } }; document.onmouseup = function() { isDragging = false; };",\u000a                        "onUnmount": "document.onmousemove = null; document.onmouseup = null;"\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "service",\u000a                        "id": "report_service_inner",\u000a                        "className": "report-content-area",\u000a                        "style": {\u000a                            "flex": "1 1 0",\u000a                            "minHeight": "0",\u000a                            "overflowY": "auto",\u000a                            "padding": "24px",\u000a                            "backgroundColor": "#ffffff"\u000a                        },\u000a                        "schemaApi": {\u000a                            "method": "post",\u000a                            "url": "/api/ai/generate-page",\u000a                            "sendOn": "${report_loading === true}",\u000a                            "data": {\u000a                                "pageId": "gftq",\u000a                                "workflow_type": "report_generation",\u000a                                "query": "生成 gftq 分析报告",\u000a                                "timestamp": "${date(now(), ''x'')}"\u000a                                \u000a                            }\u000a                        },\u000a                        "onEvent": {\u000a                            "fetchSchemaInited": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            },\u000a                            "fetchFailed": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            }\u000a                        }\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "flex",\u000a                        "justify": "space-between",\u000a                        "alignItems": "center",\u000a                        "style": {\u000a                            "padding": "16px 24px",\u000a                            "backgroundColor": "#fafafa",\u000a                            "borderTop": "1px solid #f0f0f0",\u000a                            "margin": 0\u000a                        },\u000a                        "items": [\u000a                            {\u000a                                "type": "tpl",\u000a                                "tpl": "<div style=''display: flex; align-items: center; color: #888; font-size: 13px;''><i class=''fa fa-info-circle'' style=''margin-right: 6px; color: #1890ff;''></i><span>本报告由 AI 系统生成，仅供参考</span></div>",\u000a                                "style": { "flex": "0 0 auto" }\u000a                            },\u000a                            {\u000a                                "type": "flex",\u000a                                "justify": "flex-end",\u000a                                "alignItems": "center",\u000a                                "style": { "gap": "24px" },\u000a                                "items": [\u000a                                    {\u000a                                        "type": "button",\u000a                                        "label": "取消",\u000a                                        "level": "link",\u000a                                        "className": "text-gray-500 no-underline",\u000a                                        "onEvent": {\u000a                                            "click": {\u000a                                                "actions": [{\u000a                                                    "actionType": "setValue",\u000a                                                    "componentId": "global_page_root",\u000a                                                    "args": {\u000a                                                        "value": {\u000a                                                            "show_report_result": false,\u000a                                                            "report_loading": false\u000a                                                        }\u000a                                                    }\u000a                                                }]\u000a                                            }\u000a                                        }\u000a                                    },\u000a                                    {\u000a                                        "type": "button",\u000a                                        "label": "🖨️ 打印报告",\u000a                                        "level": "default",\u000a                                        "onEvent": {\u000a                                            "click": {\u000a                                                "actions": [{\u000a                                                    "actionType": "custom",\u000a                                                    "script": "const oldStyle = document.getElementById(''report-print-style''); if(oldStyle) oldStyle.remove(); const printStyle = document.createElement(''style''); printStyle.id = ''report-print-style''; printStyle.textContent = ''@media print { @page { size: A4 portrait; margin: 10mm; } body * { visibility: hidden !important; } .report-content-area, .report-content-area *, .report-content-area .cxd-Service, .report-content-area .cxd-Service * { visibility: visible !important; } .report-content-area { position: absolute !important; left: 0 !important; top: 0 !important; width: 100% !important; max-height: none !important; overflow: visible !important; } }''; document.head.appendChild(printStyle); window.print();"\u000a                                                }]\u000a                                            }\u000a                                        }\u000a                                    },\u000a                                    {\u000a                                        "type": "button",\u000a                                        "label": "📥 导出 PDF",\u000a                                        "level": "primary",\u000a                                        "onEvent": {\u000a                                            "click": {\u000a                                                "actions": [{\u000a                                                    "actionType": "custom",\u000a                                                    "script": "const btn = event.context.nativeEvent.target.closest(''button''); const originalText = btn.textContent; btn.disabled = true; btn.textContent = ''正在生成...''; const loadScript = (src) => new Promise((resolve, reject) => { if (document.querySelector(`script[src=''${src}'']`)) return resolve(); const script = document.createElement(''script''); script.src = src; script.onload = resolve; script.onerror = reject; document.head.appendChild(script); }); Promise.all([loadScript(''https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js''), loadScript(''https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'')]).then(() => { const { jsPDF } = window.jspdf; const reportContent = document.querySelector(''.report-content-area .cxd-Service'') || document.querySelector(''.report-content-area''); if (!reportContent) { alert(''未找到报告内容''); btn.disabled = false; btn.textContent = originalText; return; } html2canvas(reportContent, { scale: 2, useCORS: true, logging: true, backgroundColor: ''#ffffff'', scrollY: 0, windowWidth: reportContent.scrollWidth || 1200 }).then(canvas => { const imgData = canvas.toDataURL(''image/png''); const pdf = new jsPDF({ orientation: ''portrait'', unit: ''mm'', format: ''a4'' }); const pdfWidth = 210; const pdfHeight = 297; const margin = 10; const imgWidth = pdfWidth - margin * 2; const imgHeight = (canvas.height * imgWidth) / canvas.width; let heightLeft = imgHeight; let position = margin; pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); while (heightLeft > 0) { pdf.addPage(); position = margin - (imgHeight - heightLeft); pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); } pdf.save(''风险分析报告_'' + new Date().toISOString().split(''T'')[0] + ''.pdf''); btn.disabled = false; btn.textContent = originalText; }).catch(err => { console.error(''PDF error:'', err); alert(''PDF生成失败''); btn.disabled = false; btn.textContent = originalText; }); }).catch(err => { alert(''加载库失败''); btn.disabled = false; btn.textContent