n      {\n        \"name\": \"dbyltq_maxtqje\",\n        \"label\": \"医疗费用提取上限（万元）\",\n        \"type\": \"input-number\",\n        \"value\": \"100%\"\n      },\n      {\n        \"name\": \"dbyltq_dbfw\",\n        \"label\": \"疾病种类范围\",\n        \"type\": \"input-text\",\n        \"value\": \"25种\"\n      },\n      {\n        \"name\": \"dbyltq_sqsx\",\n        \"label\": \"申请时限（月）\",\n        \"type\": \"input-number\",\n        \"value\": 12\n      },\n      {\n        \"name\": \"dbyltq_sfyqjsd\",\n        \"label\": \"是否要求医保结算单\",\n        \"type\": \"select\",\n        \"options\": [\n          {\n            \"label\": \"是\",\n            \"value\": \"是\"\n          },\n          {\n            \"label\": \"否\",\n            \"value\": \"否\"\n          }\n        ],\n        \"value\": \"是\"\n      }\n    ]\n  }\n]","policy_actions":"[\n  {\n    \"label\": \"📊 智能分析\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  },\n  {\n    \"label\": \"🔄 重置\",\n    \"actionType\": \"reset\",\n    \"level\": \"default\",\n    \"style\": {\n      \"marginLeft\": \"10px\"\n    }\n  }\n]","columns":"4","api_url":"/HFB/common/dmx_policy/management=metrics_query.service","api_method":"post","api_data":"{\n  \"cxlx\": \"{\\n  \\\"metricsKey\\\": \\\"zcyc_dbyltq\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}"}');
