            "fetchSchemaInited": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            },\u000a                            "fetchFailed": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            }\u000a                        }\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "flex",\u000a                        "justify": "space-between",\u000a                        "alignItems": "center",\u000a                        "style": {\u000a                            "padding": "16px 24px",\u000a                            "backgroundColor": "#fafafa",\u000a                            "borderTop": "1px solid #f0f0f0",\u000a                            "margin": 0\u000a                        },\u000a                        "items": [\u000a                            {\u000a                                "type": "tpl",\u000a                                "tpl": "<div style=''display: flex; align-items: center; color: #888; font-size: 13px;''><i class=''f