xlx\": \"{\\n  \\\"metricsKey\\\": \\\"zcyc_ltxtq\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}","form_title":"调整政策参数","policy_groups":"[\n  {\n    \"title\": \"离退休提取参数\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"ltxtq_txnl_1\",\n        \"label\": \"退休年龄要求(男)\",\n        \"type\": \"input-number\",\n        \"value\": 60\n      },\n      {\n        \"name\": \"ltxtq_txnl_2\",\n        \"label\": \"退休年龄要求(女)\",\n        \"type\": \"input-number\",\n        \"value\": 55\n      },\n      {\n        \"name\": \"ltxtq_tqtx_gl\",\n        \"label\": \"提前退休工龄要求\",\n        \"type\": \"input-number\",\n        \"value\": 30\n      },\n      {\n        \"name\": \"ltxtq_sfxyzm\",\n        \"label\": \"是否要求退休证明\",\n        \"type\": \"select\",\n        \"options\": [\n          {\n            \"label\": \"是\",\n            \"value\": \"是\"\n          },\n          {\n            \"label\": \"否\",\n            \"value\": \"否\"\n          }\n        ],\n        \"value\": \"是\"\n      }\n    ]\n  }\n]","policy_actions":"[\n  {\n    \"label\": \"📊 智能分析\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  },\n  {\n    \"label\": \"🔄 重置\",\n    \"actionType\": \"reset\",\n    \"level\": \"default\",\n    \"style\": {\n      \"marginLeft\": \"10px\"\n    }\n  }\n]","subtitle_api_data":"{\n  \"cxlx\": \"{\\n  \\\"titleKey\\\": \\\"zcyc_ltxtq_title\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}","page_key":"ltxtq","enable_query_input":true}');
