yc_ssldtq\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}","form_title":"调整政策参数","policy_groups":"[\n  {\n    \"title\": \"丧失劳动能力提取参数\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"ssldtq_ssdj\",\n        \"label\": \"劳动能力丧失等级\",\n        \"type\": \"input-text\",\n        \"value\": \"1-4级\"\n      },\n      {\n        \"name\": \"ssldtq_jgyq\",\n        \"label\": \"鉴定机构要求\",\n        \"type\": \"input-text\",\n        \"value\": \"市级以上\"\n      },\n      {\n        \"name\": \"ssldtq_tqsx\",\n        \"label\": \"提取时限(天)\",\n        \"type\": \"input-number\",\n        \"value\": 3\n      },\n      {\n        \"name\": \"ssldtq_sfqz\",\n        \"label\": \"是否要求监护人签字\",\n        \"type\": \"select\",\n        \"options\": [\n          {\n            \"label\": \"是\",\n            \"value\": \"是\"\n          },\n          {\n            \"label\": \"否\",\n            \"value\": \"否\"\n          }\n        ],\n        \"value\": \"是\"\n      }\n    ]\n  }\n]","policy_actions":"[\n  {\n    \"label\": \"📊 智能分析\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  },\n  {\n    \"label\": \"🔄 重置\",\n    \"actionType\": \"reset\",\n    \"level\": \"default\",\n    \"style\": {\n      \"marginLeft\": \"10px\"\n    }\n  }\n]","page_key":"ssldtq","enable_query_input":true}');
