getElementById(''report-timer-text''); const texts = [''正在准备数据...'', ''正在调用AI分析...'', ''正在生成报告...'', ''即将完成...'']; window.reportTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                "onUnmount": "clearInterval(window.reportTimer);"\u000a            }]\u000a        },\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${show_report_result}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(0, 0, 0, 0.5)",\u000a                "zIndex": "9998",\u000a                "display": "flex",\u000a                "alignItems": "flex-start",\u000a                "justifyContent": "center",\u000a                "paddingTop": "20px",\u000a                "paddingBottom": "20px"\u000a            },\u000a            "body": [{\u000a                "type": "container",\u000a                "id": "report_dialog_box",\u000a                "style": {\u000a                    "backgroundColor": "#ffffff",\u000a                    "borderRadius": "8px",\u000a                    "width": "95%",\u000a                    "maxWidth": "1400px",\u000a                    "height": "80vh",\u000a                    "display": "flex",\u000a                    "flexDirection": "column",\u000a                    "boxShadow": "0 4px 20px rgba(0,0,0,0.3)",\u000a                    "position": "relative",\u000a                    "overflow": "hidden"\u000a                },\u000a                "body": [\u000a                    \u000a                    {\u000a                        "type": "button",\u000a                        "label": "✕",\u000a                        "level": "link",\u000a                        "style": {\u000a                            "position": "absolute",\u000a                            "top": "12px",\u000a                            "right": "16px",\u000a                            "color": "white",\u000a                            "fontSize": "20px",\u000a                            "padding": "0",\u000a                            "width": "28px",\u000a                            "height": "28px",\u000a                            "minWidth": "28px",\u000a                            "zIndex": "10",\u000a                            "lineHeight": "28px",\u000a                            "textAlign": "center"\u000a                        },\u000a                        "onEvent": {\u000a                            "click": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "show_report_result": false,\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            }\u000a                        }\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "custom",\u000a                        "html": "<div id=''report-drag-header'' style=''background-color: #1a3c6e; color: white; padding: 14px 50px 14px 24px; border-radius: 8px 8px 0 0; cursor: move; user-select: none;''><span style=''font-size: 16px; font-weight: bold;''>📄 风险分析报告预览</span></div>",\u000a                        "onMount": "var header = document.getElementById(''report-drag-header''); var dial