           }\n              ]\n            }\n          },\n          {\n            \"title\": \"外部数据\",\n            \"body\": {\n              \"type\": \"service\",\n              \"api\": {\n                \"method\": \"post\",\n                \"url\": \"/gjjrgzn/api/ai/get-history\",\n                \"data\": {\n                  \"&\": \"$$\",\n                  \"data_source\": \"external\"\n                }\n              },\n              \"body\": {\n                \"type\": \"container\",\n                \"body\": [\n                  {\n                    \"type\": \"button-toolbar\",\n                    \"className\": \"m-b-md\",\n                    \"buttons\": [\n                      {\n                        \"type\": \"button\",\n                        \"label\": \"📥 模板下载\",\n                        \"level\": \"default\",\n                        \"actionType\": \"download\",\n                        \"api\": {\n                          \"method\": \"get\",\n                          \"url\": \"/gjjrgzn/api/ai/download-template\"\n                        }\n                      },\n                      {\n                        \"type\": \"button\",\n                        \"label\": \"📤 导入\",\n                        \"level\": \"primary\",\n                        \"actionType\": \"dialog\",\n                        \"dialog\": {\n                          \"title\": \"导入外部数据\",\n                          \"size\": \"lg\",\n                          \"body\": {\n                            \"type\": \"form\",\n                            \"api\": {\n                              \"method\": \"post\",\n                              \"url\": \"/gjjrgzn/api/ai/import-external-data\",\n                              \"data\": {\n                                \"&\": \"$$\"\n                              }\n                            },\n                            \"body\": [\n                              {\n                      