         ]\n                          }\n                        }\n                      }\n                    ]\n                  },\n                  {\n                    \"type\": \"crud\",\n                    \"api\": \"[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]\",\n                    \"syncLocation\": false,\n                    \"perPage\": 10,\n                    \"perPageAvailable\": [\n                      10,\n                      20,\n                      50,\n                      100\n                    ],\n                    \"footerToolbar\": [\n                      \"statistics\",\n                      \"pagination\"\n                    ],\n                    \"columns\": [\n                      {\n                        \"name\": \"year_month\",\n                        \"label\": \"年月\",\n                        \"width\": 100\n                      },\n                      {\n                        \"name\": \"czdjsyl\",\n                        \"label\": \"城镇登记失业率(%)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"rjkzpsr\",\n                        \"label\": \"人均可支配收入(元)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"jmxfjgzs\",\n                        \"label\": \"居民消费价格指数(CPI)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"gdpzzl\",\n                        \"label\": \"GDP增长率(%)\",\n                        \"width\": 150\n                      }\n                    ]\n                  }\n                ]\n              }\n            }\n          }\n        ]\n      }\n    }\n  },\n  {\n    \"label\": \"AI预测\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  }\n]","footer_text":"","enable_query_input":true,"id":683,"version":76,"mode":"update","report_query":"{1:1}"}');
INSERT INTO sys_page_template VALUES(696,'zxgdl','个贷率调控建议',unistr('\u000a\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false,            \u000a        "show_prediction": false        \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_policy/management=title_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": {\u000a  "cxlx": "{\\n  \\"titleKey\\": \\"zcyc_zxgdl_title\\"\\n}",\u000a  "jgbh": "1305282025"\u000a}\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>个贷率调控建议</h2>"\u000a                        },\u000a             