             \"syncLocation\": false,\n              \"perPage\": 10,\n              \"perPageAvailable\": [\n                10,\n                20,\n                50,\n                100\n              ],\n              \"footerToolbar\": [\n                \"statistics\",\n                \"switch-per-page\",\n                \"pagination\"\n              ],\n              \"columns\": [\n                {\n                  \"name\": \"value1\",\n                  \"label\": \"年月\",\n                  \"width\": 100\n                },\n                {\n                  \"name\": \"value2\",\n                  \"label\": \"贷款总金额(万元)\",\n                  \"width\": 150\n                },\n                {\n                  \"name\": \"value3\",\n                  \"label\": \"逾期金额(万元)\",\n                  \"width\": 150\n                },\n                {\n                  \"name\": \"value4\",\n                  \"label\": \"逾期率(‰)\",\n                  \"width\": 150\n                }\n              ]\n            }\n          },\n          {\n            \"title\": \"外部数据\",\n            \"body\": {\n              \"type\": \"service\",\n              \"api\": {\n                \"method\": \"post\",\n                \"url\": \"/gjjrgzn/api/ai/get-history\",\n                \"data\": {\n                  \"&\": \"$$\",\n                  \"data_source\": \"external\"\n                }\n              },\n              \"body\": {\n                \"type\": \"container\",\n                \"body\": [\n                  {\n                    \"type\": \"button-toolbar\",\n                    \"className\": \"m-b-md\",\n                    \"buttons\": [\n                      {\n                        \"type\": \"button\",\n                        \"label\": \"📥 模板下载\",\n                        \"level\": \"default\",\n                        \"actionType\": \"download\",\n                        \"api\": {\n                          \"method\": \"get\",\n                          \"url\": \"/gjjrgzn/api/ai/download-template\"\n                        }\n                      },\n                      {\n                        \"type\": \"button\",\n                        \"label\": \"📤 导入\",\n                        \"level\": \"primary\",\n                        \"actionType\": \"dialog\",\n                        \"dialog\": {\n                          \"title\": \"导入外部数据\",\n                          \"size\": \"lg\",\n                          \"body\": {\n                            \"type\": \"form\",\n                            \"api\": {\n                              \"method\": \"post\",\n                              \"url\": \"/gjjrgzn/api/ai/import-external-data\",\n                              \"data\": {\n                                \"&\": \"$$\"\n                              }\n                            },\n                            \"body\": [\n                              {\n                                \"type\": \"input-excel\",\n                                \"name\": \"excel_data\",\n                                \"label\": \"上传Excel文件\",\n                                \"accept\": \".xlsx,.xls\",\n                                \"autoFill\": {\n                                  \"data_rows\": \"[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]\"\n                                },\n                                \"plainText\": false,\n                                \"parseMode\": \"array\"\n                              },\n                              {\n                                \"type\": \"static-json\",\n                                \"name\": \"data_rows\",\n                                \"label\": \"预览数据\",\n                                \"levelExpand\": 1\n                              },\n                              {\n                                \"type\": \"divider\"\n                              },\n                              {\n                                \"type\": \"alert\",\n                                \"level\": \"info\",\n                                \"body\": \"提示：上传后将自动解析Excel内容，请检查预览数据是否正确\"\n                              }\n                            ],\n                            \"actions\": [\n                              {\n                                \"type\": \"button\",\n                                \"label\": \"取消\",\n                                \"actionType\": \"cancel\"\n                              },\n                              {\n                                \"type\": \"submit\",\n                                \"label\": \"确认导入\",\n                                \"level\": \"primary\"\n                              }\n                            ]\n                          }\n                        }\n                      }\n                    ]\n                  },\n                  {\n                    \"type\": \"crud\",\n                    \"api\": \"[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]\",\n                    \"syncLocation\": false,\n                    \"perPage\": 10,\n                    \"perPageAvailable\": [\n                      10,\n                      20,\n                      50,\n                      100\n                    ],\n                    \"footerToolbar\": [\n                      \"statistics\",\n                      \"pagination\"\n                    ],\n                    \"columns\": [\n                      {\n                        \"name\": \"year_month\",\n                        \"label\": \"年月\",\n                        \"width\": 100\n                      },\n                      {\n                        \"name\": \"czdjsyl\",\n                        \"label\": \"城镇登记失业率(%)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"rjkzpsr\",\n                        \"label\": \"人均可支配收入(元)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"jmxfjgzs\",\n                        \"label\": \"居民消费价格指数(CPI)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"gdpzzl\",\n                        \"label\": \"GDP增长率(%)\",\n                        \"width\": 150\n                      }\n                    ]\n                  }\n                ]\n              }\n            }\n          }\n        ]\n      }\n    }\n  },\n  {\n    \"label\": \"AI预测\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  }\n]","footer_text":"","enable_query_input":true,"id":683,"version":76,"mode":"update","report_query":"{1:1}"}');
INSERT INTO sys_page_template VALUES(698,'dkyql','贷款逾期率调控建议',unistr('\u000a\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false,            \u000a        "show_prediction": false        \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_policy/management=title_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": {\u000a  "cxlx": "{\\n  \\"titleKey\\": \\"zcyc_zxgdl_title\\"\\n}",\u000a  "jgbh": "1305282025"\u000a}\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>贷款逾期率调控建议</h2>"\u000a                        },\u000a         