INSERT INTO sys_page_template VALUES(741,'jcfw','缴存服务',unistr('\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a  \u000a\u000a  \u000a\u000a  \u000a\u000a  \u000a\u000a  \u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a{\u000a  "type": "page",\u000a  "body": [\u000a    \u000a{\u000a  "type": "wrapper",\u000a  "className": "b-b p-b-md flex justify-between items-center bg-white",\u000a  "body": [\u000a    {\u000a      "type": "tpl",\u000a      "tpl": "<div class=''text-lg font-bold text-dark''>缴存服务</div>"\u000a    }\u000a    \u000a    ,{\u000a      "type": "button",\u000a      "label": "刷新数据",\u000a      "icon": "fa fa-refresh",\u000a      "actionType": "reload",\u000a      "target": "card_service_1,card_service_2,card_service_3,card_service_4,card_service_5",\u000a      "level": "primary",\u000a      "size": "sm"\u000a    }\u000a    \u000a  ]\u000a}\u000a,\u000a    {\u000a      "type": "container",\u000a      "className": "p-md",\u000a      "body": [\u000a        \u000a\u000a{\u000a  "type": "container",\u000a  "name": "service_cards_grid",\u000a  "className": "service-cards-container",\u000a  "body": [\u000a    {\u000a      "type": "grid",\u000a      "columns": [\u000a        \u000a        {\u000a          "body": {\u000a            "type": "container",\u000a            "className": "service-card-item",\u000a            "style": {\u000a              "borderRadius": "12px",\u000a              "boxShadow": "0 4px 16px rgba(24,144,255,0.12)",\u000a              "border": "1px solid #e8f4ff",\u000a              "overflow": "hidden",\u000a              "background": "#fff",\u000a              "height": "100%",\u000a              "display": "flex",\u000a              "flexDirection": "column"\u000a            },\u000a            "body": [\u000a              \u000a              {\u000a                "type": "tpl",\u000a                "tpl": "<div style=''background: linear-gradient(135deg, #1890FF 0%, #40A9FF 100%); pad