INSERT INTO sys_page_template VALUES(753,'fxjk','风险监控',unistr('\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a\u000a{\u000a  "type": "page",\u000a  "title": "",\u000a  "name": "riskPage",\u000a  "data": { "subject": "缴存单位" },\u000a\u000a  "body": [\u000a    {\u000a      "type": "wrapper",\u000a      "className": "bg-white p-md m-b-md",\u000a      "body": {\u000a        "type": "flex",\u000a        "justify": "space-between",\u000a        "alignItems": "center",\u000a        "items": [\u000a          { "type": "html", "html": "<h2 style=''margin:0;font-size:24px;font-weight:600;color:#1d39c4''>AI综合风险监控看板</h2>" },\u000a          {\u000a            "type": "select",\u000a            "name": "subject",\u000a            "value": "缴存单位",\u000a            "clearable": false,\u000a            "options": [\u000a              { "label": "缴存单位风险视图", "value": "缴存单位" },\u000a              { "label": "缴存人风险视图", "value": "缴存人" },\u000a              { "label": "开发商风险视图", "value": "开发商" }\u000a            ],\u000a            "onEvent": {\u000a              "change": {\u000a                "actions": [\u000a                  {\u000a                    "actionType": "setValue",\u000a                    "componentName": "riskPage",\u000a                    "args": { "value": { "subject": "${event.data.value}" } }\u000a                  },\u000a                  { "actionType": "reload", "componentId": "levelChart" },\u000a                  { "actionType": "reload", "componentId": "behaviorChart" },\u000a                  { "actionType": "reload", "componentId": "regionChart" },\u000a                  { "actionType": "reload", "componentId": "trendChart" }\u000a                ]\u000a              }\u000a            }\u000a          }\u000a        ]\u000a      }\u000a    },\u000a    {\u000a      "type": "alert",\u000a      "level": "warning",\u000a      "className": "m-b-md