gHeight = (canvas.height * imgWidth) / canvas.width; let heightLeft = imgHeight; let position = margin; pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); while (heightLeft > 0) { pdf.addPage(); position = margin - (imgHeight - heightLeft); pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); } pdf.save(''信用风险分析报告_'' + new Date().toISOString().split(''T'')[0] + ''.pdf''); btn.disabled = false; btn.textContent = originalText; }).catch(err => { console.error(''PDF error:'', err); alert(''PDF生成失败''); btn.disabled = false; btn.textContent = originalText; }); }).catch(err => { alert(''加载库失败''); btn.disabled = false; btn.textContent = originalText; });"\u000a                              }]\u000a                            }\u000a                          }\u000a                        }\u000a                      ]\u000a                    }\u000a                  ]\u000a                }\u000a              ],\u000a              "actions": []\u000a            }\u000a          }\u000a        ]\u000a      }\u000a    }\u000a  ]\u000a}\u000a'),0,24,'2026-01-16 15:52:26','2026-01-16 15:33:27','2026-01-16 15:33:27','credit_risk_monitor','{"template_id":"credit_risk_monitor","target_page_key":"fxjk","page_title":"风险监控","app_theme":"default","manual_page_key":"fxjk","formFields":[{"type":"fieldSet","title":"📊 信用级别饼图配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"chart_level_api","label":"信用级别饼图 URL","required":false,"type":"input-text","placeholder":"/api/demo/credit/risk/chart/level"},{"name":"chart_level_data","label":"信用级别饼图固定参数","required":false,"type":"editor","language":"json","placeholder":"{}"}]},{"type":"fieldSet","title":"📊 风险行为柱状图配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"chart_behavior_api","label":"风险行为柱状图 URL","required":false,"type":"input-text","placeholder":"/api/demo/credit/risk/chart/be