                "actionType": "custom",\u000a                        "script": "const btn = event.context.nativeEvent.target.closest(''button''); const originalText = btn.textContent; btn.disabled = true; btn.textContent = ''正在生成...''; const loadScript = (src) => new Promise((resolve, reject) => { if (document.querySelector(`script[src=''${src}'']`)) return resolve(); const script = document.createElement(''script''); script.src = src; script.onload = resolve; script.onerror = reject; document.head.appendChild(script); }); Promise.all([loadScript(''https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js''), loadScript(''https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'')]).then(() => { const { jsPDF } = window.jspdf; const reportContent = document.querySelector(''.cxd-Modal-content .cxd-Service'') || document.querySelector(''.cxd-Modal-content''); if (!reportContent) { alert(''未找到报告内容''); btn.disabled = false; btn.textContent = originalText; return; } html2canvas(reportContent, { scale: 2, useCORS: true, logging: true, backgroundColor: ''#ffffff'', scrollY: 0, windowWidth: reportContent.scrollWidth || 1200 }).then(canvas => { const imgData = canvas.toDataURL(''image/png''); const pdf = new jsPDF({ orientation: ''portrait'', unit: ''mm'', format: ''a4'' }); const pdfWidth = 210; const pdfHeight = 297; const margin = 10; const imgWidth = pdfWidth - margin * 2; const imgHeight = (canvas.height * imgWidth) / canvas.width; let heightLeft = imgHeight; let position = margin; pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); while (heightLeft > 0) { pdf.addPage(); position = margin - (imgHeight - heightLeft); pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); } pdf.save(''信用风险分析报告_'' + new Date().toISOString().split(''T'')[0] + ''.pdf''); btn.disabled = false; btn.textContent = originalText; }).catch(err => { console.error(''PDF error:'', err); alert(''PDF生成失败''); btn.disabled = false; btn.textContent = originalText; }); }).catch(err => { alert(''加载库失败''); btn.disabled = false; btn.textContent = originalText; });"\u000a                      }]\u000a                    }\u000a                  }\u000a                }\u000a              ]\u000a            }\u000a          }\u000a        ]\u000a      }\u000a    }\u000a  ]\u000a}\u000a'),1,28,NULL,'2026-01-16 16:26:36','2026-01-16 16:26:36','credit_risk_monitor','{"template_id":"credit_risk_monitor","target_page_key":"fxjk","page_title":"风险监控","app_theme":"default","manual_page_key":"fxjk","formFields":[{"type":"fieldSet","title":"📊 信用级别饼图配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"chart_level_api","label":"信用级别饼图 URL","required":false,"type":"input-text","placeholder":"/api/demo/credit/risk/chart/level"},{"name":"chart_level_data","label":"信用级别饼图固定参数","required":false,"type":"editor","language":"json","placeholder":"{}"}]},{"type":"fieldSet","title":"📊 风险行为柱状图配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"chart_behavior_api","label":"风险行为柱状图 URL","required":false,"type":"input-text","placeholder":"/api/demo/credit/risk/chart/behavior"},{"name":"chart_behavior_data","label":"风险行为柱状图固定参数","required":false,"type":"editor","language":"json","placeholder":"{}"}]},{"type":"fieldSet","title":"📊 区域风险柱状图配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"chart_region_api","label":"区域风险柱状图 URL","required":false,"type":"input-text","placeholder":"/api/demo/credit/risk/chart/region"},{"name":"chart_region_data","label":"区域风险柱状图固定参数","required":false,"type":"editor","language":"json","placeholder":"{}"}]},{"type":"fieldSet","title":"📈 风险趋势折线图配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"chart_trend_api","label":"风险趋势折线图 URL","required":false,"type":"input-text","placeholder":"/api/demo/credit/risk/chart/trend"},{"name":"chart_trend_d