      ,\u000a                                    \u000a                                    {\u000a                                        "type": "card",\u000a                                        "className": "m-b-md import-item-card",\u000a                                        "bodyClassName": "p-md",\u000a                                        "style": {\u000a                                            "border": "1px solid #e8e8e8",\u000a                                            "boxShadow": "0 2px 4px rgba(0,0,0,0.02)"\u000a                                        },\u000a                                        "header": {\u000a                                            "title": "本市房价指数 & 贷款余额趋势",\u000a                                            "subTitle": "支持格式: .xls,.xlsx"\u000a                                        },\u000a                                        "toolbar": [\u000a                                            {\u000a                                                "type": "button",\u000a                                                "label": "下载模板",\u000a                                                "icon": "fa fa-download",\u000a                                                "level": "default",\u000a                                                "className": "m-r-xs",\u000a                                                "onEvent": {\u000a                                                    "click": {\u000a                                                        "actions": [\u000a                                                            {\u000a                                                                "actionType": "download",\u000a                                                                "api": {\u000a                                                                    "method": "post",\u000a                                                                    "url": "/api/template/trend.xlsx",\u000a                                                                    "dataType": "json",\u000a                                                                    "data": {},\u000a                                                                    "responseType": "blob"\u000a                                                                }\u000a                                                            }\u000a                                                        ]\u000a                                                    }\u000a                                                }\u000a                                            },\u000a                                            \u000a                                            { \u000a                                                "type": "input-file", \u000a                                                "name": "file_trend", \u000a                                                "btnLabel": "上传文件",  \u000a                                                "level": "primary", \u000a                                                "icon": "fa fa-cloud-upload",\u000a                                                "accept": ".xls,.xlsx",\u000a                                                "drag": false,\u000a                                                "asBlob": true\u000a                                            }\u000a                                            \u000a                                        ]\u000a                                    }\u000a                                    \u000a                                    \u000a                                ],\u000a                                "actions": []\u000a                            }\u000a                        }\u000a                        \u000a\u000a                        \u000a                        \u000a                        ,\u000a                        {\u000a                            "type": "button",\u000a                            "label": "📊 智能分析",\u000a                            "level": "danger",\u000a                            "style": {\u000a                                "background": "linear-gradient(180deg, #ff4d4f 0%, #cf1322 100%)",\u000a                                "border": "none",\u000a                                "boxShadow": "0 4px 10px rgba(207, 19, 34, 0.3)",\u000a                                "fontWeight": "bold",\u000a                                "width": "140px",\u000a                                "height": "40px"\u000a                            },\u000a                            "onEvent": {\u000a                                "click": {\u000a                                    "actions": [\u000a                                        \u000a                                        {\u000a                                            "actionType": "setValue",\u000a                                            "componentId": "global_page_root",\u000a                                            "args": {\u000a                                                "value": {\u000a                                                    "show_analysis_result": true,\u000a                                                    "ai_loading": true\u000a                                                }\u000a                                            }\u000a                                        },\u000a                                        \u000a                                        {\u000a                                            "actionType": "reload",\u000a                                            "componentId": "risk_analysis_service_inner"\u000a                                        }\u000a                                    ]\u000a                                }\u000a                            }\u000a                        }\u000a                        \u000a                    ]\u000a                }\u000a            ]\u000a        },\u000a\u000a         \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${ai_loading}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                \u000a                "backgroundColor": "rgba(255, 255, 255, 0.6)",\u000a                "zIndex": "9999",\u000a                "display": "flex",\u000a                "alignItems": "center",\u000a                "justifyContent": "center",\u000a                "backdropFilter": "blur(8px)" \u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "container",\u000a                    "style": {\u000a                        \u000a                        "backgroundColor": "transparent",\u000a                        "boxShadow": "none",\u000a                        "border": "none",\u000a                        "padding": "0",\u000a                        "width": "auto",\u000a                        "textAlign": "center"\u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "custom",\u000a                            "name": "ai-modal-timer",\u000a                            \u000a                            "html": "<div style=''font-family: -apple-system, BlinkMacSystemFont, Helvetica Neue, Arial; color: #333;''><div style=''position: relative; width: 80px; height: 80px; margin: 0 auto 24px auto;''><svg viewBox=''0 0 50 50'' style=''width: 100%; height: 100%; animation: spin 2s linear infinite;''><circle cx=''25'' cy=''25'' r=''20'' fill=''none'' stroke=''#e6f7ff'' stroke-width=''4''></circle><circle cx=''25'' cy=''25'' r=''20'' fill=''none'' stroke=''#1890ff'' stroke-width=''4'' stroke-dasharray=''80'' stroke-dashoffset=''60'' stroke-linecap=''round''></circle></svg><div style=''position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; font-size: 22px; font-weight: 700; color: #1890ff; font-feature-settings: \\"tnum\\";''><span id=''modal-timer-sec''>0</span><span style=''font-size: 12px; margin-left: 2px; font-weight: 400;''>s</span></div></div><div style=''font-size: 18px; font-weight: 600; color: #333; margin-bottom: 12px; letter-spacing: 0.5px; text-shadow: 0 2px 10px rgba(255,255,255,0.8);''>AI 智能分析中</div><div id=''modal-timer-text'' style=''font-size: 14px; color: #666; height: 20px; font-weight: 500;''>正在接入数据中心...</div><style>@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }</style></div>",\u000a                            "onMount": "const startTime = Date.now(); const secDom = document.getElementById(''modal-timer-sec''); const textDom = document.getElementById(''modal-timer-text''); const texts = [''正在加载业务数据...'', ''正在构建风险模型...'', ''AI 正在生成洞察...'', ''正在渲染分析报告...'']; window.modalTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                            "onUnmount": "clearInterval(window.modalTimer);"\u000a                        }\u000a                    ]\u000a                }\u000a            ]\u000a        }\u000a\u000a        \u000a        \u000a        \u000a         \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        ,{\u000a            "type": "service",\u000a            "id": "risk_analysis_service_inner", \u000a            \u000a            \u000a            "className": "${!show_analysis_result ? ''hidden'' : ''m-t-md''}",\u000a            \u000a            "initFetch": false,\u000a            "spinner": null, \u000a\u000a            "schemaApi": {\u000a                "method": "post",\u000a                "url": "/api/ai/generate-page",\u000a                \u000a                \u000a                "sendOn": "this.ai_loading === true",\u000a                \u000a                "data": {\u000a                    "pageId": "dwkm",\u000a                    "workflow_type": "ai_analysis",  \u000a                    \u000a                    "query": "${user_query || ''用户未指定要求''}",\u000a                    \u000a                    "timestamp": "${date(now(), ''x'')}"\u000a                }\u000a            },\u000a            \u000a            "onEvent": {\u000a                \u000a                \u000a                "fetchSchemaInited": {\u000a                    "actions": [\u000a                        {\u000a                            "actionType": "setValue",\u000a                            "componentId": "global_page_root",\u000a                            "args": {\u000a                                "value": {\u000a                                    "ai_loading": false\u000a                                }\u000a                            }\u000a                        },\u000a                        {\u000a                            "actionType": "toast",\u000a                            "args": { "msgType": "success", "msg": "分析完成" }\u000a                        }\u000a                    ]\u000a                },\u000a                \u000a                \u000a                "fetchFailed": {\u000a                    "actions": [\u000a                        {\u000a                            "actionType": "setValue",\u000a                            "componentId": "global_page_root",\u000a                            "args": { "value": { "ai_loading": false } }\u000a                        },\u000a                        {\u000a                            "actionType": "toast",\u000a                            "args": { "msgType": "error", "msg": "服务异常，请重试" }\u000a                        }\u000a                    ]\u000a                }\u000a            },\u000a            \u000a            "body": {\u000a                "type": "tpl",\u000a                "tpl": "",\u000a                "visible": false\u000a            }\u000a        }\u000a        \u000a    ]\u000a},\u000a\u000a        \u000a        {\u000a            "type": "tpl",\u000a            "tpl": "<div style=''text-align: center; color: #999; font-size: 12px; padding: 20px 0;''></div>"\u000a        }\u000a    ]\u000a}'),0,4,NULL,'2026-01-21 20:12:20','2026-01-21 20:12:20','fx_demo','{"template_id":"fx_demo","target_page_key":"dwkm","page_title":"单位扩面","app_theme":"default","manual_page_key":"dwkm","formFields":[{"type":"fieldSet","title":"🎨 页面头部配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"title","label":"页面标题","required":false,"type":"input-text","placeholder":"页面标题"},{"name":"title_font_size","label":"标题字体大小","required":false,"type":"input-text","placeholder":"22px"},{"name":"subtitle_api","label":"副标题数据API地址（配置后，副标题将动态显示API返回的数据;不配置则使用静态副标题或不使用副标题）","required":false,"type":"input-text","placeholder":"/api/subtitle"},{"name":"subtitle_api_method","label":"副标题API请求方法","required":false,"type":"input-text","placeholder":"post"},{"name":"subtitle_api_data","label":"副标题API的固定请求参数（JSON对象或字符串）","required":false,"type":"input-text","placeholder":""},{"name":"subtitle_api_adaptor","label":"副标题API数据适配器（副标题API返回的数据不满足 amis 格式时可设置）","required":false,"type":"input-text","placeholder":""},{"name":"subtitle","label":"页面副标题(副标题静态文字)","required":false,"type":"input-text","placeholder":""},{"name":"subtitle_font_size","label":"副标题字体大小","required":false,"type":"input-text","placeholder":"13px"},{"name":"subtitle_color","label":"副标题颜色","required":false,"type":"input-text","placeholder":"theme.colors.text_secondary"},{"name":"enable_report_button","label":"是否显示报告生成按钮","required":false,"type":"switch","value":true},{"name":"report_button_label","label":"报告按钮文字","required":false,"type":"input-text","placeholder":"生成风险分析报告"},{"name":"page_key","label":"页面唯一标识（用于报告生成）","required":false,"type":"input-text","placeholder":""},{"name":"report_workflow_type","label":"报告工作流类型（默认：report_generation）","required":false,"type":"input-text","placeholder":"report_generation"},{"name":"report_query","label":"AI报告生成查询参数","required":false,"type":"input-text","placeholder":"生成 '' + page_key + '' 分析报告"},{"name":"report_api_data","label":"报告生成API的固定请求参数（JSON对象或字符串）","required":false,"type":"input-text","placeholder":""}]},{"type":"fieldSet","title":"💡 提示配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"alert_html","label":"提示框HTML内容","required":false,"type":"input-text","placeholder":""}]},{"type":"fieldSet","title":"🤖 AI分析配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"enable_data_import","label":"是否启用数据导入功能","required":false,"type":"switch","value":true},{"name":"import_dialog_title","label":"数据导入对话框标题","required":false,"type":"input-text","placeholder":"贷后资产质量数据导入"},{"name":"import_items","label":"导入项配置数组，每项包含：","required":false,"type":"input-text","placeholder":""},{"name":"enable_ai_analysis","label":"是否启用AI分析功能","required":false,"type":"switch","value":true},{"name":"enable_query_input","label":"是否启用分析需求输入框","required":false,"type":"switch","value":true},{"name":"query_label","label":"分析需求输入框标签","required":false,"type":"input-text","placeholder":"请输入分析需求"},{"name":"query_placeholder","label":"分析需求输入框占位符","required":false,"type":"input-text","placeholder":"例如：生成贷款逾期分析图表"},{"name":"ai_generate_api","label":"AI生成页面API地址","required":false,"type":"input-text","placeholder":"/api/ai/generate-page"},{"name":"workflow_type","label":"AI 工作流类型标识（默认：ai_analysis）","required":false,"type":"input-text","placeholder":"ai_analysis"},{"name":"query","label":"AI分析查询参数","required":false,"type":"input-text","placeholder":"用户未指定要求"}]},{"type":"fieldSet","title":"⚙️ 其他配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"footer_text","label":"底部文本 (自动推断)","required":false,"type":"input-text","placeholder":"© 2025"},{"name":"default_items","label":"default items (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"desc","label":"desc (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"template_url","label":"template url (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"template_data","label":"template data (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"upload_api","label":"upload api 地址 (自动推断)","required":false,"type":"input-text","placeholder":"/api/upload"},{"name":"key","label":"key (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"accept","label":"accept (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"upload_data","label":"upload data (自动推断)","required":false,"type":"input-text","placeholder":""}]}],"__debug":"adaptor executed","enable_report_button":false,"enable_data_import":true,"enable_ai_analysis":true,"enable_query_input":true,"key":"https://appcs.jbysoft.com/gjjrgzn/system/config?","title":"单位扩面","page_key":"dwkm","alert_html":"<div style=''margin-bottom: 12px;''> <div style=''background-color: #ffffff; border: 1px solid #d9d9d9; border-radius: 8px; padding: 20px 24px; line-height: 1.7;''> <div style=''color: #1d1d1f; font-weight: 700; font-size: 16px; margin-bottom: 18px; padding-left: 12px; border-left: 4px solid #1890ff;''> 定义与分类</div> <div style=''margin-bottom: 20px;''><div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''>定义</div><div style=''color: #333; font-size: 13px; line-height: 1.8; margin-bottom: 12px; text-align: justify;''>住房公积金单位缴存扩面，是指住房公积金管理部门通过市场监管部门企业注册数据、人社部门社保参保数据、统计部门单位用工数据的交叉核验与综合分析，精准识别出已符合住房公积金建制缴存法定条件但尚未建立住房公积金制度的单位，进而推动其依法办理缴存登记、为职工缴存住房公积金的专项工作，核心目标是扩大住房公积金制度覆盖范围，保障职工住房保障权益。</div></div><div style=''margin-bottom: 0;''><div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''>分类</div><div style=''padding-left: 0; margin-top: 10px;''><div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 24px; text-indent: -24px; text-align: justify;''>认知缺失类：单位已具备建制条件，但因对住房公积金缴存政策不了解、误认为 “可自愿选择” 等认知偏差未建制，通过政策宣传引导即可推动其办理缴存登记。</div><div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 24px; text-indent: -24px; text-align: justify;''>主动规避类：单位清楚缴存义务，但为降低用工成本，故意不建立住房公积金制度，此类单位需通过执法督促、信用约束等方式推进扩面。</div></div></div></div></div>","query_label":"若对大模型分析存在其他要求，可填写具体意见，大模型根据您的补充信息进行分析。","footer_text":"","query_placeholder":""}');
INSERT INTO sys_page_template VALUES(784,'tqzzl','提取增长率调控建议',unistr('\u000a\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false,            \u000a        "show_prediction": false        \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_policy/management=title_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": {\u000a  "cxlx": "{\\n  \\"titleKey\\": \\"zcyc_tqzzl_title\\"\\n}",\u000a  "jgbh": "1305282025"\u000a}\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>提取增长率调控建议</h2>"\u000a                        },\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<div style=''color: #8c8c8c; font-size: 13px;''>${displayText}</div>"\u000a                        }\u000a                    ]\u000a                }\u000a                \u000a                ,\u000a                \u000a    {\u000a        "type": "button",\u000a        "label": "生成分析报告",\u000a        "level": "danger",\u000a        "style": {\u000a            "position": "absolute",        \u000a            "right": "20px",               \u000a            "top": "50%",                  \u000a            "transform": "translateY(-50%)", \u000a            "zIndex": "10"\u000a        },\u000a        "onEvent": {\u000a            "click": {\u000a                "actions": [\u000a                    \u000a                    \u000a                    {\u000a                        "actionType": "setValue",\u000a                        "componentId": "global_page_root",\u000a                        "args": {\u000a                            "value": {\u000a                                "show_report_result": true,\u000a                                "report_loading": true\u000a                            }\u000a                        }\u000a                    }\u000a                ]\u000a            }\u000a        }\u000a    }\u000a    \u000a                \u000a            ]\u000a        }\u000a        \u000a        \u000a        \u000a    ]\u000a}\u000a\u000a\u000a\u000a,{\u000a    "type": "service",\u000a    "id": "report_display_root",\u000a    "className": "p-none",\u000a    "body": [\u000a        \u000a        {\u000a            "type": "tpl",\u000a            "tpl": "<style>.report-content-area { max-height: calc(80vh - 120px) !important; overflow-y: auto !important; } .report-content-area > * { max-height: 100%; }</style>"\u000a        },\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${report_loading}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(255, 255, 255, 0.9)",\u000a                "zIndex": "10000",\u000a                "display": "flex",\u000a                "alignItems": "center",\u000a                "justifyContent": "center",\u000a                "backdropFilter": "blur(8px)"\u000a            },\u000a            "body": [{\u000a                "type": "custom",\u000a                "name": "report-timer",\u000a                "html": "<div style=''font-family: -apple-system, BlinkMacSystemFont, Helvetica Neue, Arial; color: #333;''><div style=''position: relative; width: 80px; height: 80px; margin: 0 auto 24px auto;''><svg viewBox=''0 0 50 50'' style=''width: 100%; height: 100%; animation: spin 2s linear infinite;''><circle cx=''25'' cy=''25'' r=''20'' fill=''none'' stroke=''#e6f7ff'' stroke-width=''4''></circle><circle cx=''25'' cy=''25'' r=''20'' fill=''none'' stroke=''#1890ff'' stroke-width=''4'' stroke-dasharray=''80'' stroke-dashoffset=''60'' stroke-linecap=''round''></circle></svg><div style=''position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; font-size: 22px; font-weight: 700; color: #1890ff;''><span id=''report-timer-sec''>0</span><span style=''font-size: 12px; margin-left: 2px; font-weight: 400;''>s</span></div></div><div style=''font-size: 18px; font-weight: 600; color: #333; margin-bottom: 12px;''>正在生成报告</div><div id=''report-timer-text'' style=''font-size: 14px; color: #666;''>正在准备数据...</div><style>@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }</style></div>",\u000a                "onMount": "const startTime = Date.now(); const secDom = document.getElementById(''report-timer-sec''); const textDom = document.getElementById(''report-timer-text''); const texts = [''正在准备数据...'', ''正在调用AI分析...'', ''正在生成报告...'', ''即将完成...'']; window.reportTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                "onUnmount": "clearInterval(window.reportTimer);"\u000a            }]\u000a        },\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${show_report_result}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(0, 0, 0, 0.5)",\u000a                "zIndex": "9998",\u000a                "display": "flex",\u000a                "alignItems": "flex-start",\u000a                "justifyContent": "center",\u000a                "paddingTop": "20px",\u000a                "paddingBottom": "20px"\u000a            },\u000a            "body": [{\u000a                "type": "container",\u000a                "id": "report_dialog_box",\u000a                "style": {\u000a                    "backgroundColor": "#ffffff",\u000a                    "borderRadius": "8px",\u000a                    "width": "95%",\u000a                    "maxWidth": "1400px",\u000a                    "height": "80vh",\u000a                    "display": "flex",\u000a                    "flexDirection": "column",\u000a                    "boxShadow": "0 4px 20px rgba(0,0,0,0.3)",\u000a                    "position": "relative",\u000a                    "overflow": "hidden"\u000a                },\u000a                "body": [\u000a                    \u000a                    {\u000a                        "type": "button",\u000a                        "label": "✕",\u000a                        "level": "link",\u000a                        "style": {\u000a                            "position": "absolute",\u000a                            "top": "12px",\u000a                            "right": "16px",\u000a                            "color": "white",\u000a                            "fontSize": "20px",\u000a                            "padding": "0",\u000a                            "width": "28px",\u000a                            "height": "28px",\u000a                            "minWidth": "28px",\u000a                            "zIndex": "10",\u000a                            "lineHeight": "28px",\u000a                            "textAlign": "center"\u000a                        },\u000a                        "onEvent": {\u000a                            "click": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "show_report_result": false,\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            }\u000a                        }\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "custom",\u000a                        "html": "<div id=''report-drag-header'' style=''background-color: #1a3c6e; color: white; padding: 14px 50px 14px 24px; border-radius: 8px 8px 0 0; cursor: move; user-select: none;''><span style=''font-size: 16px; font-weight: bold;''>📄 风险分析报告预览</span></div>",\u000a                        "onMount": "var header = document.getElementById(''report-drag-header''); var dialog = header.closest(''[data-component-id=\\"report_dialog_box\\"]'') || header.parentElement.parentElement; var isDragging = false; var offsetX = 0; var offsetY = 0; header.onmousedown = function(e) { isDragging = true; offsetX = e.clientX - dialog.offsetLeft; offsetY = e.clientY - dialog.offsetTop; dialog.style.position = ''fixed''; dialog.style.margin = ''0''; }; document.onmousemove = function(e) { if (isDragging) { dialog.style.left = (e.clientX - offsetX) + ''px''; dialog.style.top = (e.clientY - offsetY) + ''px''; } }; document.onmouseup = function() { isDragging = false; };",\u000a                        "onUnmount": "document.onmousemove = null; document.onmouseup = null;"\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "service",\u000a                        "id": "report_service_inner",\u000a                        "className": "report-content-area",\u000a                        "style": {\u000a                            "flex": "1 1 0",\u000a                            "minHeight": "0",\u000a                            "overflowY": "auto",\u000a                            "padding": "24px",\u000a                            "backgroundColor": "#ffffff"\u000a                        },\u000a                        "schemaApi": {\u000a                            "method": "post",\u000a                            "url": "/api/ai/generate-page",\u000a                            "sendOn": "${report_loading === true}",\u000a                            "data": {\u000a                                "pageId": "tqzzl",\u000a                                "workflow_type": "report_generation",\u000a                                "query": "生成 tqzzl 分析报告",\u000a                                "timestamp": "${date(now(), ''x'')}"\u000a                                \u000a                            }\u000a                        },\u000a                        "onEvent": {\u000a                            "fetchSchemaInited": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            },\u000a                            "fetchFailed": {\u000a                                "actions": [{\u000a                                    "actionType": "setValue",\u000a                                    "componentId": "global_page_root",\u000a                                    "args": {\u000a                                        "value": {\u000a                                            "report_loading": false\u000a                                        }\u000a                                    }\u000a                                }]\u000a                            }\u000a                        }\u000a                    },\u000a                    \u000a                    {\u000a                        "type": "flex",\u000a                        "justify": "space-between",\u000a                        "alignItems": "center",\u000a                        "style": {\u000a                            "padding": "16px 24px",\u000a                            "backgroundColor": "#fafafa",\u000a                            "borderTop": "1px solid #f0f0f0",\u000a                            "margin": 0\u000a                        },\u000a                        "items": [\u000a                            {\u000a                                "type": "tpl",\u000a                                "tpl": "<div style=''display: flex; align-items: center; color: #888; font-size: 13px;''><i class=''fa fa-info-circle'' style=''margin-right: 6px; color: #1890ff;''></i><span>本报告由 AI 系统生成，仅供参考</span></div>",\u000a                                "style": { "flex": "0 0 auto" }\u000a                            },\u000a                            {\u000a                                "type": "flex",\u000a                                "justify": "flex-end",\u000a                                "alignItems": "center",\u000a                                "style": { "gap": "24px" },\u000a                                "items": [\u000a                                    {\u000a                                        "type": "button",\u000a                                        "label": "取消",\u000a                                        "level": "link",\u000a                                        "className": "text-gray-500 no-underline",\u000a                                        "onEvent": {\u000a                                            "click": {\u000a                                                "actions": [{\u000a                                                    "actionType": "setValue",\u000a                                                    "componentId": "global_page_root",\u000a                                                    "args": {\u000a                                                        "value": {\u000a                                                            "show_report_result": false,\u000a                                                            "report_loading": false\u000a                                                        }\u000a                                                    }\u000a                                                }]\u000a                                            }\u000a                                        }\u000a                                    },\u000a                                    {\u000a                                        "type": "button",\u000a                                        "label": "🖨️ 打印报告",\u000a                                        "level": "default",\u000a                                        "onEvent": {\u000a                                            "click": {\u000a                                                "actions": [{\u000a                                                    "actionType": "custom",\u000a                                                    "script": "const oldStyle = document.getElementById(''report-print-style''); if(oldStyle) oldStyle.remove(); const printStyle = document.createElement(''style''); printStyle.id = ''report-print-style''; printStyle.textContent = ''@media print { @page { size: A4 portrait; margin: 10mm; } body * { visibility: hidden !important; } .report-content-area, .report-content-area *, .report-content-area .cxd-Service, .report-content-area .cxd-Service * { visibility: visible !important; } .report-content-area { position: absolute !important; left: 0 !important; top: 0 !important; width: 100% !important; max-height: none !important; overflow: visible !important; } }''; document.head.appendChild(printStyle); window.print();"\u000a                                                }]\u000a                                            }\u000a                                        }\u000a                                    },\u000a                                    {\u000a                                        "type": "button",\u000a                                        "label": "📥 导出 PDF",\u000a                                        "level": "primary",\u000a                                        "onEvent": {\u000a                                            "click": {\u000a                                                "actions": [{\u000a                                                    "actionType": "custom",\u000a                                                    "script": "const btn = event.context.nativeEvent.target.closest(''button''); const originalText = btn.textContent; btn.disabled = true; btn.textContent = ''正在生成...''; const loadScript = (src) => new Promise((resolve, reject) => { if (document.querySelector(`script[src=''${src}'']`)) return resolve(); const script = document.createElement(''script''); script.src = src; script.onload = resolve; script.onerror = reject; document.head.appendChild(script); }); Promise.all([loadScript(''https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js''), loadScript(''https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'')]).then(() => { const { jsPDF } = window.jspdf; const reportContent = document.querySelector(''.report-content-area .cxd-Service'') || document.querySelector(''.report-content-area''); if (!reportContent) { alert(''未找到报告内容''); btn.disabled = false; btn.textContent = originalText; return; } html2canvas(reportContent, { scale: 2, useCORS: true, logging: true, backgroundColor: ''#ffffff'', scrollY: 0, windowWidth: reportContent.scrollWidth || 1200 }).then(canvas => { const imgData = canvas.toDataURL(''image/png''); const pdf = new jsPDF({ orientation: ''portrait'', unit: ''mm'', format: ''a4'' }); const pdfWidth = 210; const pdfHeight = 297; const margin = 10; const imgWidth = pdfWidth - margin * 2; const imgHeight = (canvas.height * imgWidth) / canvas.width; let heightLeft = imgHeight; let position = margin; pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); while (heightLeft > 0) { pdf.addPage(); position = margin - (imgHeight - heightLeft); pdf.addImage(imgData, ''PNG'', margin, position, imgWidth, imgHeight); heightLeft -= (pdfHeight - margin * 2); } pdf.save(''风险分析报告_'' + new Date().toISOString().split(''T'')[0] + ''.pdf''); btn.disabled = false; btn.textContent = originalText; }).catch(err => { console.error(''PDF error:'', err); alert(''PDF生成失败''); btn.disabled = false; btn.textContent = originalText; }); }).catch(err => { alert(''加载库失败''); btn.disabled = false; btn.textContent = originalText; });"\u000a                                                }]\u000a                                            }\u000a                                        }\u000a                                    }\u000a                                ]\u000a                            }\u000a                        ]\u000a                    }\u000a                ]\u000a            }]\u000a        }\u000a    ]\u000a}\u000a,\u000a\u000a        \u000a        \u000a\u000a{\u000a    "type": "tpl",\u000a    "tpl": "<div style=''margin-bottom: 12px; padding: 12px 16px; border-radius: 4px; background-color: #e6f7ff; border: 1px solid #91d5ff; color: #1890ff;''><div style=\\"margin: -13px -17px; background: white; padding: 16px 20px; border: 1px solid #e8e8e8;\\"> \\t<!-- 标题行 --> \\t<div style=\\"display: flex; align-items: center; gap: 8px; margin-bottom: 16px;\\"> \\t\\t<div style=\\"background: #3b82f6; color: white; border-radius: 3px; padding: 3px 8px; font-weight: bold; font-size: 11px;\\"> \\t\\t\\tAI \\t\\t</div> \\t\\t<div style=\\"color: #1a202c; font-weight: 600; font-size: 15px;\\"> \\t\\t\\t提取增长率政策 \\t\\t</div> \\t</div> \\t<!-- 定义 --> \\t<div style=\\"margin-bottom: 14px;\\"> \\t\\t<div style=\\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\\"> \\t\\t\\t定义 \\t\\t</div> \\t\\t<div style=\\"color: #4a5568; font-size: 13px; line-height: 1.6;\\"> \\t\\t\\t提取增长率是指一定时期内住房公积金提取额的增长幅度，计算公式为：（本期提取额-上期提取额）/上期提取额×100%。该指标反映了公积金资金流出情况，是衡量资金使用效率、预测资金流动性风险的重要指标。 \\t\\t</div> \\t</div> \\t<!-- 细则 --> \\t<div> \\t\\t<div style=\\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\\"> \\t\\t\\t影响政策 \\t\\t</div> \\t\\t<div class=\\"policy-details\\" style=\\"color: #4a5568; font-size: 13px; line-height: 1.6;\\"> \\t\\t\\t<div style=\\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\\"> \\t\\t\\t\\t一、购买、建造、翻建、大修自住住房提取 \\t\\t\\t</div> \\t\\t\\t<ul style=\\"list-style-type: none; padding-left: 0;line-height: 1.8;\\"> \\t\\t\\t\\t<li> \\t\\t\\t\\t\\t提取条件关键参数范围： \\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t1、购房行为与首付资金门槛： \\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t购买首套房：首付款比例 ≥ 房屋总价20% \\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t购买二套房：首付款比例 ≥ 房屋总价30% \\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t2、公积金账户余额与贷款额度联动： \\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t可贷额度 ≤ 账户余额 × 15 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t3、特殊政策支持（不可叠加，就高执行）： \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t城市品质提升政策：贷款额度上浮50%，可“存贷不挂钩”全额提取余额 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t人才安居政策：贷款额度上浮20%，可“存贷不挂钩”全额提取余额 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t二孩及以上家庭：贷款额度上浮20% \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t4、二手房特殊限制（间接影响提取额）： \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t贷款额度 ≤ 成交价与计税价低值的70% \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t房龄＞10年：贷款额度 ≤ 低值的60% \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t</ul> \\t\\t\\t<div style=\\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\\"> \\t\\t\\t\\t二、偿还购房贷款本息提取 \\t\\t\\t</div> \\t\\t\\t<ul style=\\"list-style-type: none; padding-left: 0;line-height: 1.8;\\"> \\t\\t\\t\\t<li> \\t\\t\\t\\t\\t提取条件与额度影响参数： \\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t1、贷款资格与还款能力门槛： \\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t连续缴存公积金满6个月 \\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t家庭月收入 ≥ 月还款额 × 2 \\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t2、贷款期限与提取周期： \\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t最长贷款年限：30年 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t二手房限制：房龄＋贷款年限 ≤ 50年 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t3、贷款额度上限（决定还贷提取需求基础）： \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t单人最高：30万元 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t双人及以上最高：60万元 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t建造住房定额：每户20万元 \\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t</ul> \\t\\t\\t<div style=\\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\\"> \\t\\t\\t\\t三、租赁住房提取 \\t\\t\\t</div> \\t\\t\\t<ul style=\\"list-style-type: none; padding-left: 0;line-height: 1.8;\\"> \\t\\t\\t\\t<li> \\t\\t\\t\\t\\t提取条件与政策关联参数： \\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t1、购房资格替代效应（反向关联）： \\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t若购房门槛降低（如首付比例降低、额度上浮），租赁提取需求可能相应减少 \\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t2、政策倾斜人群的提取转移： \\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t符合“城市品质提升”“人才安居”政策职工，因购房门槛降低，可能从租房提取转为购房提取 \\t\\t\\t\\t\\t\\t\\t\\t</li> \\t\\t\\t</ul> \\t\\t\\t<div style=\\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\\"> \\t\\t\\t\\t四、其他住房消费提取（如支付物业费等） \\t\\t\\t</div> \\t\\t\\t<ul style=\\"list-style-type: none; padding-left: 0;line-height: 1.8;\\"> \\t\\t\\t\\t<li> \\t\\t\\t\\t\\t提取条件关联参数： \\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t1、账户余额可用性约束： \\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t职工为保留“账户余额×15倍”的贷款额度，可能暂缓非紧急住房消费提取 \\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t2、特殊政策豁免余额约束： \\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t符合“存贷不挂钩”政策的职工，可更自由地提取余额用于其他住房消费 \\t\\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t</ul> \\t\\t\\t<div style=\\"font-size: 13px;font-weight: bold;color: #1a3c6e;margin: 15px 0 8px 0;padding-bottom: 5px;border-bottom: 2px solid #e3f2fd;\\"> \\t\\t\\t\\t五、销户提取（离退休、出境定居等） \\t\\t\\t</div> \\t\\t\\t<ul style=\\"list-style-type: none; padding-left: 0;line-height: 1.8;\\"> \\t\\t\\t\\t<li> \\t\\t\\t\\t\\t政策间接影响参数： \\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t1、贷款使用率影响： \\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t贷款政策宽松，公积金使用率高，账户沉淀资金减少，可能影响未来销户提取的平均金额 \\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t2、政策倾斜人群资金流动： \\t\\t\\t\\t\\t\\t\\t\\t</i> \\t\\t\\t\\t\\t\\t\\t\\t<li> \\t\\t\\t\\t\\t\\t\\t\\t\\t享受上浮额度且“存贷不挂钩”的职工，可能更早将余额用于购房，影响离退休时的账户余额 \\t\\t\\t\\t\\t\\t\\t\\t</li> \\t\\t\\t</ul> \\t\\t</div> \\t</div> </div></div>"\u000a}\u000a,\u000a\u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "m-t-md",\u000a            "style": {\u000a                "backgroundColor": "#fff",\u000a                "borderRadius": "10px",\u000a                "boxShadow": "0 4px 8px rgba(0, 0, 0, 0.05)",\u000a                "padding": "25px",\u000a                "marginBottom": "20px"\u000a            },\u000a            "body": [\u000a                \u000a                \u000a    {\u000a      "type": "service",\u000a      \u000a      "api": {\u000a        "method": "post",\u000a        "url": "/HFB/common/dmx_policy/management=metrics_query.service"\u000a        \u000a        ,"data": {"cxlx":"{\\n  \\"metricsKey\\": \\"zcyc_tqzzl\\"\\n}","jgbh":"1305282025"}\u000a        \u000a        \u000a      },\u000a      \u000a      "body": [\u000a        \u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a          "type": "each",\u000a          "name": "${groups || [{ items: [], title: '''', columns: 5, border_color: '''' }]}",\u000a          "items": {\u000a            "type": "container",\u000a            "className": "m-b-md",\u000a            "body": [\u000a              {\u000a                "type": "html",\u000a                "tpl": "<div style=''font-weight: 600; font-size: 15px; margin-bottom: 12px; color: #1a3c6e; display: flex; align-items: center; gap: 8px;''>${title}</div>",\u000a                "visibleOn": "this.title"\u000a              },\u000a              {\u000a                "type": "container",\u000a                "className": "stats-cards-grid ${border_color ? ''border-'' + border_color : ''''} m-b-md",\u000a                "style": {\u000a                  "display": "flex",\u000a                  "flexWrap": "wrap",\u000a                  "gap": "16px",\u000a                  "width": "100%"\u000a                },\u000a                "body": [\u000a                  {\u000a                    "type": "each",\u000a                    "name": "items",\u000a                    "style": {\u000a                      "display": "contents"\u000a                    },\u000a                    "items": {\u000a                      "type": "container",\u000a                      "className": "stat-card",\u000a                      "style": {\u000a                        "flex": "0 0 calc(${100 / (columns || 5)}% - 16px)",\u000a                        "minWidth": "120px"\u000a                      },\u000a                    