\n                              }\n                            ]\n                          }\n                        }\n                      }\n                    ]\n                  },\n                  {\n                    \"type\": \"crud\",\n                    \"api\": \"${items}\",\n                    \"syncLocation\": false,\n                    \"perPage\": 10,\n                    \"perPageAvailable\": [\n                      10,\n                      20,\n                      50,\n                      100\n                    ],\n                    \"footerToolbar\": [\n                      \"statistics\",\n                      \"pagination\"\n                    ],\n                    \"columns\": [\n                      {\n                        \"name\": \"year_month\",\n                        \"label\": \"年月\",\n                        \"width\": 100\n                      },\n                      {\n                        \"name\": \"fwmj\",\n                        \"label\": \"商品房成交面积(㎡)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"fwjj\",\n                        \"label\": \"新建商品住宅均价(元)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"jgzs\",\n                        \"label\": \"二手住宅价格指数\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"pjgz\",\n                        \"label\": \"平均工资(元)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"jyrs\",\n                        \"label\": \"新增城镇就业人数(人)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"lpr\",\n                        \"label\": \"LPR\",\n                        \