\u000a                                                "type": "input-file", \u000a                                                "name": "file_valuation", \u000a                                                "btnLabel": "上传文件",  \u000a                                                "level": "primary", \u000a                                                "icon": "fa fa-cloud-upload",\u000a                                                "accept": ".xls,.xlsx",\u000a                                                "drag": false,\u000a                                                "asBlob": true\u000a                                            }\u000a                                            \u000a                                        ]\u000a                                    }\u000a                                    ,\u000a                                    \u000a                                    {\u000a                                        "type": "card",\u000a                                        "className": "m-b-md import-item-card",\u000a                                        "bodyClassName": "p-md",\u000a                                        "style": {\u000a                                            "border": "1px solid #e8e8e8",\u000a                                            "boxShadow": "0 2px 4px rgba(0,0,0,0.02)"\u000a                                        },\u000a                                        "header": {\u000a                                            "title": "抵押物查封/冻结情况",\u000a                                            "subTitle": "支持格式: .xls,.xlsx"\u000a                                        },\u000a                                        "toolbar": [\u000a                                            {\u000a                                                "type": "button",\u000a                                                "label": "下载模板",\u000a                                                "icon": "fa fa-download",\u0