oxShadow": "0 2px 4px rgba(0,0,0,0.02)"\u000a                                        },\u000a                                        "header": {\u000a                                            "title": "各区县逾期率 & 房价跌幅数据",\u000a                                            "subTitle": "支持格式: .xls,.xlsx"\u000a                                        },\u000a                                        "toolbar": [\u000a                                            {\u000a                                                "type": "button",\u000a                                                "label": "下载模板",\u000a                                                "icon": "fa fa-download",\u000a                                                "level": "default",\u000a                                                "className": "m-r-xs",\u000a                                                "onEvent": {\u000a                                                    "click": {\u000a                                                        "actions": [\u000a                                                            {\u000a                                                                "actionType": "download",\u000a                                                                "api": {\u000a                                                                    "method": "post",\u000a                                                                    "url": "/api/template/rate.xlsx",\u000a                                                                    "dataType": "json",\u000a                                                                    "data": {},\u000a                                                                    "responseType": "blob"\u000a                                                                }\u000a                                                            }\u000a                                                        ]\u000a                                              