bal_page_root", "args": { "value": { "ai_loading": false } } },\u000a                        { "actionType": "toast", "args": { "msgType": "error", "msg": "生成失败，请稍后重试" } }\u000a                    ]\u000a                }\u000a            },\u000a            "body": {\u000a                "type": "tpl",\u000a                "tpl": "",\u000a                "visible": false\u000a            }\u000a        },\u000a\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${ai_loading}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(255, 255, 255, 0.6)",\u000a                "zIndex": "9999",\u000a                "display": "flex",\u000a                "alignItems": "center",\u000a                "justifyContent": "center",\u000a                "backdropFilter": "blur(8px)"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "container",\u000a                    "style": {\u000a                        "backgroundColor": "transparent",\u000a                        "boxShadow": "none",\u000a                        "border": "none",\u000a                        "padding": "0",\u000a                        "width": "auto",\u000a                        "textAlign": "center"\u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "custom",\u000a                            "name": "ai-modal-timer",\u000a                            "html": "<div style=''font-family: -apple-system, BlinkMacSystemFont, Helvetica Neue, Arial; color: #333;''><div style=''position: relative; width: 80px; height: 80px; margin: 0 auto 24px auto;''><svg viewBox=''0 0 50 50'' style=''width: 100%; height: 100%; animation: sp