       "actionType": "setValue",\u000a                            "componentId": "global_page_root",\u000a                            "args": { "value": { "ai_loading": false } }\u000a                        },\u000a                        {\u000a                            "actionType": "toast",\u000a                            "args": { "msgType": "error", "msg": "服务异常，请重试" }\u000a                        }\u000a                    ]\u000a                }\u000a            },\u000a            \u000a            "body": {\u000a                "type": "tpl",\u000a                "tpl": "",\u000a                "visible": false\u000a            }\u000a        }\u000a        \u000a    ]\u000a},\u000a\u000a        \u000a        {\u000a            "type": "tpl",\u000a            "tpl": "<div style=''text-align: center; color: #999; font-size: 12px; padding: 20px 0;''></div>"\u000a        }\u000a    ]\u000a}\u000a'),0,2,'2026-01-22 16:32:38','2026-01-22 16:24:23','2026-01-22 16:24:23','gjznkm_demo','{"app_theme":"default","template_id":"gjznkm_demo","manual_page_key":"lhjckm","page_title":"灵活缴存扩面","formFields":[{"type":"fieldSet","title":"🎨 页面头部配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"title","label":"页面标题","required":false,"type":"input-text","placeholder":"归集智能扩面"},{"name":"title_font_size","label":"标题字体大小","required":false,"type":"input-text","placeholder":"22px"},{"name":"subtitle_api","label":"副标题数据API地址（配置后，副标题将动态显示API返回的数据;不配置则使用静态副标题或不使用副标题）","required":false,"type":"input-text","placeholder":"/api/subtitle"},{"name":"subtitle_api_method","label":"副标题API请求方法","required":false,"type":"input-text","placeholder":"post"},{"name":"subtitle_api_data","label":"副标题API的固定请求参数（JSON对象或字符串）","required":false,"type":"input-text","placeholder":""},{"name":"subtitle_api_adaptor","label":"副标题API数据适配器（副标题API返回的数据不满足 amis 格式时可设置）","required":false,"type":"input-text","placeholder":""},{"name":"subtitle","label":"页面副标题(副标题静态文字)","required":false,"type