); alert(''下载出错: '' + err.message); });"\u000a                                                                    }\u000a                                                                ]\u000a                                                            }\u000a                                                        }\u000a                                                    }\u000a                                                ]\u000a                                            },\u000a                                            \u000a                                            { \u000a                                                "type": "input-file", \u000a                                                "name": "", \u000a                                                "btnLabel": "上传文件", \u000a                                                "level": "primary", \u000a                                                "icon": "fa fa-cloud-upload",\u000a                                                "accept": ".xlsx",\u000a                                                "autoUpload": true,\u000a                                                "drag": false,\u000a                                                "receiver": {\u000a                                                    "method": "post",\u000a                                                    "url": "/HFB/common/dmx/management=gjznkm_dr.service",\u000a                                                    "data": {"cxlx":"lhsbxx_dr","jgbh":"1305282025"}\u000a                                                }\u000a                                            }\u000a                                            \u000a                                        ]\u000a                                    }\u000a                                    ,\u000a                                    \u000a                                    {\u000a                                        "type": "card",\u000a                             