                                   \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            "labelWidth": 150\u000a                                        }\u000a                                    ],\u000a                                    "md": 3\u000a                                },\u000a                                \u000a                                {\u000a                                    \u000a                                    \u000a                                    "body": [\u000a                                        {\u000a                                            "type": "select",\u000a                                            "name": "ltxtq_sfxyzm",\u000a                                            "label": "是否要求退休证明",\u000a                                            "value": "是",\u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            "options": [{"label":"是","value":"是"},{"label":"否","value":"否"}],\u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a               