ommon/dmx_policy/management=metrics_query.service","api_method":"post","api_data":"{\n  \"cxlx\": \"{\\n  \\\"metricsKey\\\": \\\"zcyc_ltxtq\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}","form_title":"调整政策参数","policy_groups":"[\n  {\n    \"title\": \"离退休提取参数\",\n    \"columns\": 4,\n    \"fields\": [\n      {\n        \"name\": \"ltxtq_txnl_1\",\n        \"label\": \"退休年龄要求(男)\",\n        \"type\": \"input-number\",\n        \"value\": 60\n      },\n      {\n        \"name\": \"ltxtq_txnl_2\",\n        \"label\": \"退休年龄要求(女)\",\n        \"type\": \"input-number\",\n        \"value\": 55\n      },\n      {\n        \"name\": \"ltxtq_tqtx_gl\",\n        \"label\": \"提前退休工龄要求\",\n        \"type\": \"input-number\",\n        \"value\": 30\n      },\n      {\n        \"name\": \"ltxtq_sfxyzm\",\n        \"label\": \"是否要求退休证明\",\n        \"type\": \"select\",\n        \"options\": [\n          {\n            \"label\": \"是\",\n            \"value\": \"是\"\n          },\n          {\n            \"label\": \"否\",\n            \"value\": \"否\"\n          }\n        ],\n        \"value\": \"是\"\n      }\n    ]\n  }\n]","policy_actions":"[\n  {\n    \"label\": \"📊 智能分析\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  },\n  {\n    \"label\": \"🔄 重置\",\n    \"actionType\": \"reset\",\n    \"level\": \"default\",\n    \"style\": {\n      \"marginLeft\": \"10px\"\n    }\n  }\n]","subtitle_api_data":"{\n  \"cxlx\": \"{\\n  \\\"titleKey\\\": \\\"zcyc_ltxtq_title\\\"\\n}\",\n  \"jgbh\": \"1305282025\"\n}","page_key":"ltxtq","enable_query_input":true}');
INSERT INTO sys_page_template VALUES(822,'gftq','购房提取政策调整预测',unistr('\u000a\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false,            \u000a        "show_prediction": false        \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_policy/management=title_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": {\u000a  "cxlx": "{\\n  \\"titleKey\\": \\"zcyc_gftq_title\\"\\n}",\u000a  "jgbh": "1305282025"\u000a}\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>购房提取政策调整预测</h2>"\u000a                        },\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<div style=''color: #8c8c8c; font-size: 13px;''>${displayText}</div>"\u000a                        }\u000a                    ]\u000a                }\u000a                \u000a            ]\u000a        }\u000a        \u000a        \u000a        \u000a    ]\u000a}\u000a\u000a\u000a,\u000a\u000a        \u000a        \u000a\u000a{\u000a    "type": "tpl",\u000a    "tpl": "<div style=''margin-bottom: 12px; padding: 12px 16px; border-radius: 4px; background-color: #e6f7ff; border: 1px solid #91d5ff; color: #1890ff;''><div style=\\"margin: -13px -17px; background: white; padding: 16px 20px; border: 1px solid #e8e8e8;\\">     <!-- 标题行 -->     <div style=\\"display: flex; align-items: center; gap: 8px; margin-bottom: 16px;\\">         <div style=\\"background: #3b82f6; color: white; border-radius: 3px; padding: 3px 8px; font-weight: bold; font-size: 11px;\\">             AI         </div>         <div style=\\"color: #1a202c; font-weight: 600; font-size: 15px;\\">             购房提取政策</div>     </div> <!-- 总则 -->     <div style=\\"margin-bottom: 14px;\\">         <div style=\\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\\">             总则         </div>         <div style=\\"color: #4a5568; font-size: 13px; line-height: 1.6;\\">             为规范住房公积金购房提取行为，支持缴存职工购买自住住房，依据《住房公积金管理条例》及本市相关规定，制定本政策。</div>     </div>          <!-- 细则 -->     <div>         <div style=\\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\\">             细则         </div>         <div style=\\"color: #4a5568; font-size: 13px; line-height: 1.7;\\">             <div style=\\"margin-bottom: 4px;\\">1、职工购买自住住房的，可申请提取住房公积金；</div>             <div style=\\"margin-bottom: 4px;\\">2、提取额度不超过购房总价款，且不超过账户余额；</div>             <div style=\\"margin-bottom: 4px;\\">3、需在购房合同签订后两年内申请提取；</div>             <div style=\\"margin-bottom: 4px;\\">4、同一套住房只能提取一次，夫妻双方合计提取金额不超过购房总价款。</div>         </div>     </div> </div></div>"\u000a}\u000a,\u000a\u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "m-t-md",\u000a            "style": {\u000a                "backgroundColor": "#fff",\u000a                "borderRadius": "10px",\u000a                "boxShadow": "0 4px 8px rgba(0, 0, 0, 0.05)",\u000a                "padding": "25px",\u000a                "marginBottom": "20px"\u000a            },\u000a            "body": [\u000a                \u000a                \u000a    {\u000a      "type": "service",\u000a      \u000a      "api": {\u000a        "method": "post",\u000a        "url": "/HFB/common/dmx_policy/management=metrics_query.service"\u000a        \u000a        ,"data": {"cxlx":"{\\n  \\"metricsKey\\": \\"zcyc_gftq\\"\\n}","jgbh":"1305282025"}\u000a        \u000a        \u000a      },\u000a      \u000a      "body": [\u000a        \u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a          "type": "each",\u000a          "name": "${groups || [{ items: [], title: '''', columns: 4, border_color: '''' }]}",\u000a          "items": {\u000a            "type": "container",\u000a            "className": "m-b-md",\u000a            "body": [\u000a              {\u000a                "type": "html",\u000a                "tpl": "<div style=''font-weight: 600; font-size: 15px; margin-bottom: 12px; color: #1a3c6e; display: flex; align-items: center; gap: 8px;''>${title}</div>",\u000a                "visibleOn": "this.title"\u000a              },\u000a              {\u000a                "type": "container",\u000a                "className": "stats-cards-grid ${border_color ? ''border-'' + border_color : ''''} m-b-md",\u000a                "style": {\u000a                  "display": "flex",\u000a                  "flexWrap": "wrap",\u000a                  "gap": "16px",\u000a                  "width": "100%"\u000a                },\u000a                "body": [\u