       \"body\": {\n              \"type\": \"service\",\n              \"api\": {\n                \"method\": \"post\",\n                \"url\": \"/gjjrgzn/api/ai/get-history\",\n                \"data\": {\n                  \"&\": \"$$\",\n                  \"data_source\": \"external\"\n                }\n              },\n              \"body\": {\n                \"type\": \"container\",\n                \"body\": [\n                  {\n                    \"type\": \"button-toolbar\",\n                    \"className\": \"m-b-md\",\n                    \"buttons\": [\n                      {\n                        \"type\": \"button\",\n                        \"label\": \"📥 模板下载\",\n                        \"level\": \"default\",\n                        \"actionType\": \"download\",\n                        \"api\": {\n                          \"method\": \"get\",\n                          \"url\": \"/gjjrgzn/api/ai/download-template\"\n                        }\n                      },\n                      {\n                        \"type\": \"button\",\n                        \"label\": \"📤 导入\",\n                        \"level\": \"primary\",\n                        \"actionType\": \"dialog\",\n                        \"dialog\": {\n                          \"title\": \"导入外部数据\",\n                          \"size\": \"lg\",\n                          \"body\": {\n                            \"type\": \"form\",\n                            \"api\": {\n                              \"method\": \"post\",\n                              \"url\": \"/gjjrgzn/api/ai/import-external-data\",\n                              \"data\": {\n                                \"&\": \"$$\"\n                              }\n                            },\n                            \"body\": [\n                              {\n                                \"type\": \"input-excel\",\n                                \"name\": \"excel_data\",\n                                \"label\": \"上传Excel文件\",\n                                \"accept\": \".xlsx,.xls\",\n                                \"autoFill\": {\n                                  \"data_rows\": \"[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]\"\n                                },\n                                \"plainText\": false,\n                                \"parseMode\": \"array\"\n                              },\n                              {\n                                \"type\": \"static-json\",\n                                \"name\": \"data_rows\",\n                                \"label\": \"预览数据\",\n                                \"levelExpand\": 1\n                              },\n                              {\n                                \"type\": \"divider\"\n                              },\n                              {\n                                \"type\": \"alert\",\n                                \"level\": \"info\",\n                                \"body\": \"提示：上传后将自动解析Excel内容，请检查预览数据是否正确\"\n                              }\n                            ],\n                            \"actions\": [\n                              {\n                                \"type\": \"button\",\n                                \"label\": \"取消\",\n                                \"actionType\": \"cancel\"\n                              },\n                              {\n                                \"type\": \"submit\",\n                                \"label\": \"确认导入\",\n                                \"level\": \"primary\"\n                              }\n                            ]\n                          }\n                        }\n                      }\n                    ]\n                  },\n                  {\n                    \"type\": \"crud\",\n                    \"api\": \"[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]\",\n                    \"syncLocation\": false,\n                    \"perPage\": 10,\n                    \"perPageAvailable\": [\n                      10,\n                      20,\n                      50,\n                      100\n                    ],\n                    \"footerToolbar\": [\n                      \"statistics\",\n                      \"pagination\"\n                    ],\n                    \"columns\": [\n                      {\n                        \"name\": \"year_month\",\n                        \"label\": \"年月\",\n                        \"width\": 100\n                      },\n                      {\n                        \"name\": \"spfcjmj\",\n                        \"label\": \"商品房成交面积(万㎡)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"spzzjj\",\n                        \"label\": \"新建商品住宅均价(元/㎡)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"esfjgsz\",\n                        \"label\": \"二手住宅价格指数\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"pjgz\",\n                        \"label\": \"平均工资(元)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"lprf\",\n                        \"label\": \"LPR(5年期以上)(%)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"gdpzs\",\n                        \"label\": \"GDP增速(%)\",\n                        \"width\": 150\n                      },\n                      {\n                        \"name\": \"xzjyrs\",\n                        \"label\": \"新增城镇就业人数(万人)\",\n                        \"width\": 150\n                      }\n                    ]\n                  }\n                ]\n              }\n            }\n          }\n        ]\n      }\n    }\n  },\n  {\n    \"label\": \"AI预测\",\n    \"actionType\": \"ai_analysis\",\n    \"level\": \"danger\"\n  }\n]"}');
INSERT INTO sys_page_template VALUES(839,'jcdwkm','单位缴存扩面',unistr('\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false             \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "text-center",\u000a            "style": {\u000a                "width": "100%"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "tpl",\u000a                    "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>单位缴存扩面</h2>"\u000a                },\u000a                {\u000a                    "type": "tpl",\u000a                    "tpl": "<div style=''color: #8c8c8c; font-size: 13px;''></div>"\u000a                }\u000a            ]\u000a        }\u000a        \u000a        \u000a        \u000a    ]\u000a}\u000a\u000a\u000a,\u000a\u000a        \u000a        \u000a\u000a{\u000a    "type": "tpl",\u000a    "tpl": "<div style=''margin-bottom: 12px; padding: 12px 16px; border-radius: 4px; background-color: #e6f7ff; border: 1px solid #91d5ff; color: #1890ff;''><div style=''margin-bottom: 12px;''> <div style=''background-color: #ffffff; border: 1px solid #d9d9d9; border-radius: 8px; padding: 20px 24px; line-height: 1.7;''> <div style=''color: #1d1d1f; font-weight: 700; font-size: 16px; margin-bottom: 18px; padding-left: 12px; border-left: 4px solid #1890ff;''> 定义与分类</div> <div style=''margin-bottom: 20px;''><div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''>定义</div><div style=''color: #333; font-size: 13px; line-height: 1.8; margin-bottom: 12px; text-align: justify;''>住房公积金单位缴存扩面，是指住房公积金管理部门通过市场监管部门企业注册数据、人社部门社保参保数据、统计部门单位用工数据的交叉核验与综合分析，精准识别出已符合住房公积金建制缴存法定条件但尚未建立住房公积金制度的单位，进而推动其依法办理缴存登记、为职工缴存住房公积金的专项工作，核心目标是扩大住房公积金制度覆盖范围，保障职工住房保障权益。</div></div><div style=''margin-bottom: 0;''><div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''>分类</div><div style=''padding-left: 0; margin-top: 10px;''><div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 24px; text-indent: -24px; text-align: justify;''>认知缺失类：单位已具备建制条件，但因对住房公积金缴存政策不了解、误认为 “可自愿选择” 等认知偏差未建制，通过政策宣传引导即可推动其办理缴存登记。</div><div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 24px; text-indent: -24px; text-align: justify;''>主动规避类：单位清楚缴存义务，但为降低用工成本，故意不建立住房公积金制度，此类单位需通过执法督促、信用约束等方式推进扩面。</div></div></div></div></div></div>"\u000a}\u000a,\u000a\u000a        \u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "service",\u000a    "id": "risk_analysis_root",\u000a    "className": "p-none",\u000a    \u000a    "body": [\u000a        \u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "m-t-lg m-b-md",\u000a            "style": {\u000a                "backgroundColor": "#fff",\u000a                "borderRadius": "8px",\u000a                "padding": "20px"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "tpl",\u000a                    "tpl": "<div style=''font-size: 14px; color: #333; margin-bottom: 10px; font-weight: 500;''>若对大模型分析存在其他要求，可填写具体意见，大模型根据您的补充信息进行分析。</div>"\u000a                },\u000a                {\u000a                    "type": "textarea",\u000a                    "name": "user_query",\u000a                    "id": "user_query_input",\u000a                    "placeholder": "",\u000a                    "minRows": 2,\u000a                    "maxRows": 5,\u000a                    "showCounter": false,\u000a                    "className": "w-full",\u000a                    "style": {\u000a                        "border": "1px solid #d9d9d9",\u000a                        "borderRadius": "6px"\u000a                    }\u000a                }\u000a            ]\u000a        },\u000a        \u000a\u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "m-t-lg",\u000a            "style": {\u000a                "border": "1px dashed #1890ff",\u000a                "borderRadius": "8px",\u000a                "backgroundColor": "#f0f7ff",\u000a                "padding": "30px",\u000a                "textAlign": "center"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "button-group",\u000a                    "buttons": [\u000a                        \u000a                        \u000a                        \u000a                        \u000a                        {\u000a                            "type": "button",\u000a                            "label": "☁️ 数据导入",\u000a                            "className": "m-r-lg",\u000a                            "style": { "border": "1px solid #1890ff", "color": "#003a8c", "backgroundColor": "#e6f7ff", "fontWeight": "bold", "width": "140px", "height": "40px" },\u000a                            "actionType": "dialog",\u000a                            "dialog": {\u000a                                "title": "",\u000a                                "showCloseButton": true,\u000a                                "size": "md",\u000a                                "closeOnEsc": false,\u000a                                "bodyClassName": "p-0",\u000a                                "className"