                 "header": {\u000a                                            "title": "质监局数据",\u000a                                            "subTitle": "支持格式: .xlsx"\u000a                                        },\u000a                                        "toolbar": [\u000a                                            {\u000a                                                "type": "service",\u000a                                                "className": "m-0 p-0",\u000a                                                "style": { "display": "inline-block", "marginRight": "10px" },\u000a                                                "data": {\u000a                                                    "injected_tpl_data": "{\\n  \\"cxlx\\": \\"zjjxx_mbxz\\",\\n  \\"jgbh\\": \\"1305282025\\",\\n  \\"value1\\": \\"质监局数据模板\\"\\n}"\u000a                                                },\u000a                                                "body": [\u000a                                                    {\u000a                                                        "type": "button",\u000a                                                        "label": "下载模板",\u000a                                                        "icon": "fa fa-download",\u000a                                                        "level": "default",\u000a                                                        "onEvent": {\u000a                                                            "click": {\u000a                                                                "actions": [\u000a                                                                    {\u000a                                                                        "actionType": "custom",\u000a                                                                        "script": "console.log(''v4.6 (Gateway Support) fetch start''); let token = localStorage.getItem(''auth_token'') || localStorage.getItem(''token'') || localStorage.getItem(''amis-token''); const headers = { ''Content-Type'': ''application/json'' }; if (token) { headers[''Authorization''] = ''Bearer '' + token; } const gatewayInfoStr = localStorage.getItem(''gateway_info''); if (gatewayInfoStr) { try { const info = JSON.parse(gatewayInfoStr); if (info.login_token) { const parts = info.login_token.split('':''); if (parts.length > 1) { headers[''channel''] = parts[1]; } headers[''login-token''] = info.login_token; } if (info.jgbh) headers[''jgbh''] = info.jgbh; if (info.zzbs) headers[''zzbs''] = info.zzbs; if (info.zzjgdmz) headers[''zzjgdmz''] = info.zzjgdmz; headers[''x-requested-with''] = ''XMLHttpRequest''; console.log(''Gateway headers added''); } catch(e) { console.warn(''Parse gateway_info failed'', e); } } let url = ''/HFB/common/dmx/management=gjznkm_mbxz.service''; console.log(''Fetching URL:'', url); console.log(''DEBUG: Full Event Data'', event.data); let tplData = (event.data && event.data.injected_tpl_data); console.log(''DEBUG: Raw tplData'', tplData); if (typeof tplData === ''string'') { try { tplData = JSON.parse(tplData); } catch(e) { console.warn(''Parse tplData failed'', e); } } console.log(''DEBUG: Parsed tplData'', tplData); let contextData = {}; try { if (typeof event !== ''undefined'' && event.data) { contextData = JSON.parse(JSON.stringify(event.data)); } } catch(e) { contextData = event.data || {}; } const requestBody = { ...contextData, ...(tplData || {}) }; console.log(''Request body:'', requestBody); fetch(url, { method: ''POST'', headers: headers, body: JSON.stringify(requestBody) }).then(res => { console.log(''Fetch response status:'', res.status); if(!res.ok) throw new Error(''Network error: '' + res.status); return res.blob(); }).then(blob => { console.log(''Blob received'', blob.size); var url = window.URL.createObjectURL(blob); var a = document.createElement(''a''); a.href = url; a.download = ''模板文件.xlsx''; document.body.appendChild(a); a.click(); document.body.removeChild(a); window.URL.revokeObjectURL(url); }).catch(err => { console.error(''Download error:'', err); alert(''下载出错: '' + err.message); });"\u000a                                                                    }\u000a                                                                ]\u000a                                                            }\u000a                                                        }\u000a                                                    }\u000a                                                ]\u000a                                            },\u000a                                            \u000a                                            { \u000a                                                "type": "input-file", \u000a                                                "name": "", \u000a                                                "btnLabel": "上传文件", \u000a                                                "level": "primary", \u000a                                                "icon": "fa fa-cloud-upload",\u000a                                                "accept": ".xlsx",\u000a                                                "autoUpload": true,\u000a                                                "drag": false,\u000a                                                "receiver": {\u000a                                                    "method": "post",\u000a                                                    "url": "/HFB/common/dmx/management=gjznkm_dr.service",\u000a                                                    "data": {"cxlx":"zjjxx_dr","jgbh":"1305282025"}\u000a                                                }\u000a                                            }\u000a                                            \u000a                                        ]\u000a                                    }\u000a                                    ,\u000a                                    \u000a                                    {\u000a                                        "type": "card",\u000a                                        "className": "m-b-md import-item-card",\u000a                                        "bodyClassName": "p-md",\u000a                                        "style": {\u000a                                            "border": "1px solid #e8e8e8",\u000a                                            "boxShadow": "0 2px 4px rgba(0,0,0,0.02)"\u000a                                        },\u000a                                        "header": {\u000a                                            "title": "社保数据",\u000a                                            "subTitle": "支持格式: .xlsx"\u000a                                        },\u000a                                        "toolbar": [\u000a                                            {\u000a                                                "type": "service",\u000a                                                "className": "m-0 p-0",\u000a                                                "style": { "display": "inline-block", "marginRight": "10px" },\u000a                                                "data": {\u000a                                                    "injected_tpl_data": "{\\n  \\"cxlx\\": \\"dwsbxx_mbxz\\",\\n  \\"jgbh\\": \\"1305282025\\",\\n  \\"value1\\": \\"社保数据模板\\"\\n}"\u000a                                                },\u000a                                                "body": [\u000a                                                    {\u000a                                                        "type": "button",\u000a                                                        "label": "下载模板",\u000a                                                        "icon": "fa fa-download",\u000a                                                        "level": "default",\u000a                                                        "onEvent": {\u000a                                                            "click": {\u000a                                                                "actions": [\u000a                                                                    {\u000a                                                                        "actionType": "custom",\u000a                                                                        "script": "console.log(''v4.6 (Gateway Support) fetch start''); let token = localStorage.getItem(''auth_token'') || localStorage.getItem(''token'') || localStorage.getItem(''amis-token''); const headers = { ''Content-Type'': ''application/json'' }; if (token) { headers[''Authorization''] = ''Bearer '' + token; } const gatewayInfoStr = localStorage.getItem(''gateway_info''); if (gatewayInfoStr) { try { const info = JSON.parse(gatewayInfoStr); if (info.login_token) { const parts = info.login_token.split('':''); if (parts.length > 1) { headers[''channel''] = parts[1]; } headers[''login-token''] = info.login_token; } if (info.jgbh) headers[''jgbh''] = info.jgbh; if (info.zzbs) headers[''zzbs''] = info.zzbs; if (info.zzjgdmz) headers[''zzjgdmz''] = info.zzjgdmz; headers[''x-requested-with''] = ''XMLHttpRequest''; console.log(''Gateway headers added''); } catch(e) { console.warn(''Parse gateway_info failed'', e); } } let url = ''/HFB/common/dmx/management=gjznkm_mbxz.service''; console.log(''Fetching URL:'', url); console.log(''DEBUG: Full Event Data'', event.data); let tplData = (event.data && event.data.injected_tpl_data); console.log(''DEBUG: Raw tplData'', tplData); if (typeof tplData === ''string'') { try { tplData = JSON.parse(tplData); } catch(e) { console.warn(''Parse tplData failed'', e); } } console.log(''DEBUG: Parsed tplData'', tplData); let contextData = {}; try { if (typeof event !== ''undefined'' && event.data) { contextData = JSON.parse(JSON.stringify(event.data)); } } catch(e) { contextData = event.data || {}; } const requestBody = { ...contextData, ...(tplData || {}) }; console.log(''Request body:'', requestBody); fetch(url, { method: ''POST'', headers: headers, body: JSON.stringify(requestBody) }).then(res => { console.log(''Fetch response status:'', res.status); if(!res.ok) throw new Error(''Network error: '' + res.status); return res.blob(); }).then(blob => { console.log(''Blob received'', blob.size); var url = window.URL.createObjectURL(blob); var a = document.createElement(''a''); a.href = url; a.download = ''模板文件.xlsx''; document.body.appendChild(a); a.click(); document.body.removeChild(a); window.URL.revokeObjectURL(url); }).catch(err => { console.error(''Download error:'', err); alert(''下载出错: '' + err.message); });"\u000a                                                                    }\u000a                                                                ]\u000a                                                            }\u000a                                                        }\u000a                                                    }\u000a                                                ]\u000a                                            },\u000a                                            \u000a                                            { \u000a                                                "type": "input-file", \u000a                                                "name": "", \u000a                                                "btnLabel": "上传文件", \u000a                                                "level": "primary", \u000a                                                "icon": "fa fa-cloud-upload",\u000a                                                "accept": ".xlsx",\u000a                                                "autoUpload": true,\u000a                                                "drag": false,\u000a                                                "receiver": {\u000a                                                    "method": "post",\u000a                                                    "url": "/HFB/common/dmx/management=gjznkm_dr.service",\u000a                                                    "data": {"cxlx":"dwsbxx_dr","jgbh":"1305282025"}\u000a                                                }\u000a                                            }\u000a                                            \u000a                                        ]\u000a                                    }\u000a                                    \u000a                                    \u000a                                ],\u000a                                "actions": []\u000a                            }\u000a                        }\u000a                        \u000a\u000a                        \u000a                        \u000a                        ,\u000a                        {\u000a                            "type": "button",\u000a                            "label": "📊 智能分析",\u000a                            "level": "danger",\u000a                            "style": {\u000a                                "background": "linear-gradient(180deg, #ff4d4f 0%, #cf1322 100%)",\u000a                                "border": "none",\u000a                                "boxShadow": "0 4px 10px rgba(207, 19, 34, 0.3)",\u000a                                "fontWeight": "bold",\u000a                                "width": "140px",\u000a                                "height": "40px"\u000a                            },\u000a                            "onEvent": {\u000a                                "click": {\u000a                                    "actions": [\u000a                                        \u000a                                        {\u000a                                            "actionType": "setValue",\u000a                                            "componentId": "global_page_root",\u000a                                            "args": {\u000a                                                "value": {\u000a                                                    "show_analysis_result": true,\u000a        