Time = Date.now(); const secDom = document.getElementById(''modal-timer-sec''); const textDom = document.getElementById(''modal-timer-text''); const texts = [''正在加载业务数据...'', ''正在构建风险模型...'', ''AI 正在生成洞察...'', ''正在渲染分析报告...'']; window.modalTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                            "onUnmount": "clearInterval(window.modalTimer);"\u000a                        }\u000a                    ]\u000a                }\u000a            ]\u000a        }\u000a\u000a        \u000a        \u000a        \u000a         \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        \u000a        ,{\u000a            "type": "service",\u000a            "id": "risk_analysis_service_inner", \u000a            \u000a            \u000a            "className": "${!show_analysis_result ? ''hidden'' : ''m-t-md''}",\u000a            \u000a            "initFetch": false,\u000a            "spinner": null, \u000a\u000a            "schemaApi": {\u000a                "method": "post",\u000a                "url": "/api/ai/generate-page",\u000a                \u000a                \u000a                "sendOn": "this.ai_loading === true",\u000a                \u000a                "data": {\u000a                    "pageId": "lhjckm",\u000a                    "workflow_type": "ai_analysis",  \u000a                    \u000a                    "query": "${user_query || ''用户未指定要求''}",\u000a                    \u000a                    "timestamp": "${date(now(), ''x'')}"\u000a                }\u000a            },\u000a            \u000a            "onEvent": {\u000a                \u000a                \u000a                "fetchSchemaInited": {\u000a                    "actions": [\u000a                        {\u000a                            "actionType": "setValue",\u000a                            "componentId": "global_page_root",\u000a                            "args": {\u000a                                "value": {\u000a                                    "ai_loading": false\u000a                                }\u000a                            }\u000a                        },\u000a                        {\u000a                            "actionType": "toast",\u000a                            "args": { "msgType": "success", "msg": "分析完成" }\u000a                        }\u000a                    ]\u000a                },\u000a                \u000a                \u000a                "fetchFailed": {\u000a                    "actions": [\u000a                        {\u000a                            "actionType": "setValue",\u000a                            "componentId": "global_page_root",\u000a                            "args": { "value": { "ai_loading": false } }\u000a                        },\u000a                        {\u000a                            "actionType": "toast",\u000a                            "args": { "msgType": "error", "msg": "服务异常，请重试" }\u000a                        }\u000a                    ]\u000a                }\u000a            },\u000a            \u000a            "body": {\u000a                "type": "tpl",\u000a                "tpl": "",\u000a                "visible": false\u000a            }\u000a        }\u000a        \u000a    ]\u000a},\u000a\u000a        \u000a        {\u000a            "type": "tpl",\u000a            "tpl": "<div style=''text-align: center; color: #999; font-size: 12px; padding: 20px 0;''></div>"\u000a        }\u000a    ]\u000a}\u000a'),0,4,'2026-05-06 15:23:53','2026-01-30 15:05:01','2026-01-30 15:05:01','gjznkm_demo','{"template_id":"gjznkm_demo","target_page_key":"lhjckm","page_title":"灵活缴存扩面","app_theme":"default","manual_page_key":"lhjckm","formFields":[{"type":"fieldSet","title":"🎨 页面头部配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"title","label":"页面标题","required":false,"type":"input-text","placeholder":"归集智能扩面"},{"name":"title_font_size","label":"标题字体大小","required":false,"type":"input-text","placeholder":"22px"},{"name":"subtitle_api","label":"副标题数据API地址（配置后，副标题将动态显示API返回的数据;不配置则使用静态副标题或不使用副标题）","required":false,"type":"input-text","placeholder":"/api/subtitle"},{"name":"subtitle_api_method","label":"副标题API请求方法","required":false,"type":"input-text","placeholder":"post"},{"name":"subtitle_api_data","label":"副标题API的固定请求参数（JSON对象或字符串）","required":false,"type":"input-text","placeholder":""},{"name":"subtitle_api_adaptor","label":"副标题API数据适配器（副标题API返回的数据不满足 amis 格式时可设置）","required":false,"type":"input-text","placeholder":""},{"name":"subtitle","label":"页面副标题(副标题静态文字)","required":false,"type":"input-text","placeholder":""},{"name":"subtitle_font_size","label":"副标题字体大小","required":false,"type":"input-text","placeholder":"13px"},{"name":"subtitle_color","label":"副标题颜色","required":false,"type":"input-text","placeholder":"theme.colors.text_secondary"},{"name":"enable_report_button","label":"是否显示报告生成按钮","required":false,"type":"switch","value":true},{"name":"report_button_label","label":"报告按钮文字","required":false,"type":"input-text","placeholder":"生成风险分析报告"},{"name":"page_key","label":"页面唯一标识（用于报告生成）","required":false,"type":"input-text","placeholder":""},{"name":"report_workflow_type","label":"报告工作流类型（默认：report_generation）","required":false,"type":"input-text","placeholder":"report_generation"},{"name":"report_query","label":"AI报告生成查询参数","required":false,"type":"input-text","placeholder":"生成 '' + page_key + '' 分析报告"},{"name":"report_api_data","label":"报告生成API的固定请求参数（JSON对象或字符串）","required":false,"type":"input-text","placeholder":""}]},{"type":"fieldSet","title":"💡 提示配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"alert_html","label":"提示框HTML内容","required":false,"type":"input-text","placeholder":""}]},{"type":"fieldSet","title":"📥 数据导入与AI分析配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"enable_data_import","label":"是否启用数据导入功能","required":false,"type":"switch","value":true},{"name":"import_dialog_title","label":"数据导入对话框标题","required":false,"type":"input-text","placeholder":"贷后资产质量数据导入"},{"name":"enable_ai_analysis","label":"是否启用AI分析功能","required":false,"type":"switch","value":true},{"name":"enable_query_input","label":"是否启用分析需求输入框","required":false,"type":"switch","value":true},{"name":"query_label","label":"分析需求输入框标签","required":false,"type":"input-text","placeholder":"请输入分析需求"},{"name":"query_placeholder","label":"分析需求输入框占位符","required":false,"type":"input-text","placeholder":"例如：生成贷款逾期分析图表"},{"name":"ai_generate_api","label":"AI生成页面API地址","required":false,"type":"input-text","placeholder":"/api/ai/generate-page"},{"name":"workflow_type","label":"AI 工作流类型标识（默认：ai_analysis）","required":false,"type":"input-text","placeholder":"ai_analysis"},{"name":"query","label":"AI分析查询参数","required":false,"type":"input-text","placeholder":"用户未指定要求"},{"name":"import_items","label":"数据导入项配置（每项包含标题、接口、参数等）","required":false,"type":"combo","multiple":true,"multiLine":true,"draggable":true,"addButtonText":"新增 项目","items":[{"name":"title","label":"显示标题","required":false,"type":"input-text","placeholder":""},{"name":"key","label":"字段名","required":false,"type":"input-text","placeholder":""},{"name":"desc","label":"描述文字","required":false,"type":"input-text","placeholder":""},{"name":"accept","label":"上传文件类型限制 (默认 .xls,.xlsx)","required":false,"type":"input-text","placeholder":""},{"name":"template_url","label":"模板下载接口","required":false,"type":"input-text","placeholder":""},{"name":"template_data","label":"模板下载参数(JSON)","required":false,"type":"input-text","placeholder":""},{"name":"upload_api","label":"上传接口","required":false,"type":"input-text","placeholder":""},{"name":"upload_data","label":"上传参数(JSON)","required":false,"type":"input-text","placeholder":""}],"value":[]}]},{"type":"fieldSet","title":"⚙️ 其他配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"footer_text","label":"底部文本 (自动推断)","required":false,"type":"input-text","placeholder":"© 2025"},{"name":"default_items","label":"default items (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"length","label":"length (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"desc","label":"desc (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"template_url","label":"template url (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"upload_api","label":"upload api 地址 (自动推断)","required":false,"type":"input-text","placeholder":"/api/upload"},{"name":"key","label":"key (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"accept","label":"accept (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"upload_data","label":"upload data (自动推断)","required":false,"type":"input-text","placeholder":""}]}],"__debug":"adaptor executed","enable_report_button":false,"enable_data_import":true,"enable_ai_analysis":true,"enable_query_input":true,"import_items":[{"title":"社保数据","key":"","desc":"支持格式: .xlsx","accept":".xlsx","template_url":"/HFB/common/dmx/management=gjznkm_mbxz.service","template_data":"{\n  \"cxlx\": \"lhsbxx_mbxz\",\n  \"jgbh\": \"1305282025\",\n  \"value1\": \"社保数据模板\"\n}","upload_api":"/HFB/common/dmx/management=gjznkm_dr.service","upload_data":"{\n  \"cxlx\": \"lhsbxx_dr\",\n  \"jgbh\": \"1305282025\"\n}","sortOrder":10},{"title":"婚姻数据","accept":".xlsx","desc":"支持格式: .xlsx","template_url":"/HFB/common/dmx/management=gjznkm_mbxz.service","template_data":"{\n  \"cxlx\": \"lhhyxx_mbxz\",\n  \"jgbh\": \"1305282025\",\n  \"value1\": \"婚姻数据模板\"\n}","upload_api":"/HFB/common/dmx/management=gjznkm_dr.service","upload_data":"{\n  \"cxlx\": \"lhhyxx_dr\",\n  \"jgbh\": \"1305282025\"\n}","sortOrder":20},{"upload_data":"{\n  \"cxlx\": \"lhbdcxx_dr\",\n  \"jgbh\": \"1305282025\"\n}","upload_api":"/HFB/common/dmx/management=gjznkm_dr.service","template_data":"{\n  \"cxlx\": \"lhbdcxx_mbxz\",\n  \"jgbh\": \"1305282025\",\n  \"value1\": \"不动产数据模板\"\n}","desc":"支持格式: .xlsx","accept":".xlsx","template_url":"/HFB/common/dmx/management=gjznkm_mbxz.service","title":"不动产数据","sortOrder":30}],"key":"https://appcs.jbysoft.com/gjjrgzn/system/config?","title":"灵活缴存扩面","page_key":"lhjckm","id":814,"version":1,"mode":"create","footer_text":"","alert_html":"<div style=''margin-bottom: 12px;''> <div style=''background-color: #ffffff; border: 1px solid #d9d9d9; border-radius: 8px; padding: 20px 24px; line-height: 1.7;''> <div style=''color: #1d1d1f; font-weight: 700; font-size: 16px; margin-bottom: 18px; padding-left: 12px; border-left: 4px solid #1890ff;''> 定义与分类</div> <div style=''margin-bottom: 20px;''><div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''>定义</div><div style=''color: #333; font-size: 13px; line-height: 1.8; margin-bottom: 12px; text-align: justify;''>灵活缴存职工扩面，是指住房公积金管理部门通过社保、婚姻、不动产数据的交叉比对与综合分析，精准识别出未缴纳住房公积金的灵活就业人员，为其提供差异化、针对性的缴存政策指导与服务支持，从而吸纳该群体纳入公积金制度覆盖范围，保障灵活就业人员住房消费与资金储备权益的专项工作。</div></div><div style=''margin-bottom: 0;''><div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''>分类</div><div style=''padding-left: 0; margin-top: 10px;''><div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 24px; text-indent: -24px; text-align: justify;''>高潜力群体：高潜力群体有稳定社保缴费记录，叠加不动产交易、婚姻住房需求等数据，缴存意愿和能力双高。</div><div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 24px; text-indent: -24px; text-align: justify;''>中潜力群体：中潜力群体社保缴费断续，有潜在购房刚需但暂未落实行动，具备一定储蓄规划基础，需政策激励激活缴存意愿。</div></div></div></div></div>","import_dialog_title":"","query_label":"若对大模型分析存在其他要求，可填写具体意见，大模型根据您的补充信息进行分析。","query_placeholder":""}');
INSERT INTO sys_page_template VALUES(843,'dqyqfx','当前逾期风险分析',unistr('\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false             \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_risk/management=metrics_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": {\u000a  "cxlx": "{\\n  \\"titleKey\\": \\"fxgl_dhhkfx_dqyqfx_title\\"\\n}",\u000a  "jgbh": "1305282025"\u000a}\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>当前逾期风险分析</h2>"\u000a                        },\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<div style=''color: #8c8c8c; font-size: 13px;''>${displayText}</div>"\u000a                        }\u000a                    ]\u000a                }\u000a                \u000a            ]\u000a        }\u000a        \u000a        \u000a        \u000a    ]\u000a}\u000a\u000a\u000a,\u000a\u000a        \u000a        \u000a\u000a{\u000a    "type": "tpl",\u000a    "tpl": "<div style=''margin-bottom: 12px; padding: 12px 16px; border-radius: 4px; background-color: #e6f7ff; border: 1px solid #91d5ff; color: #1890ff;''><div style=''margin-bottom: 12px;''> \\t<div style=''background-color: #ffffff; border: 1px solid #d9d9d9; border-radius: 8px; padding: 20px 24px; line-height: 1.7;''> \\t\\t<div style=''color: #1d1d1f; font-weight: 700; font-size: 16px; margin-bottom: 18px; padding-left: 12px; border-left: 4px solid #1890ff;''> \\t\\t\\t定义与分类 \\t\\t</div> \\t\\t<div style=''margin-bottom: 20px;''> \\t\\t\\t<div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''> \\t\\t\\t\\t定义 \\t\\t\\t</div> \\t\\t\\t<div style=''color: #333; font-size: 13px; line-height: 1.8; margin-bottom: 12px; text-align: justify;''> \\t\\t\\t\\t<strong> \\t\\t\\t\\t\\t当前逾期风险 \\t\\t\\t\\t</strong> \\t\\t\\t\\t是指对公积金贷款中已经发生、但尚未结清的逾期贷款进行实时评估，识别风险聚集点和潜在损失，为制定差异化催收策略和资产保全措施提供直接依据。 \\t\\t\\t</div> \\t\\t</div> \\t\\t<div style=''margin-bottom: 0;''> \\t\\t\\t<div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''> \\t\\t\\t\\t分类 \\t\\t\\t</div> \\t\\t\\t<div style=''padding-left: 0; margin-top: 10px;''> \\t\\t\\t\\t<div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 1px; text-indent: 0px; text-align: justify;''> \\t\\t\\t\\t\\t<strong> \\t\\t\\t\\t\\t\\t1. 逾期原因： \\t\\t\\t\\t\\t</strong> \\t\\t\\t\\t\\t区分借款人是因遗忘等技术性原因造成的短期非恶意逾期，还是因失业、病痛等客观困难，亦或是恶意拒付的主观违约。 \\t\\t\\t\\t</div> \\t\\t\\t\\t<div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 1px; text-indent: 0px; text-align: justify;''> \\t\\t\\t\\t\\t<strong> \\t\\t\\t\\t\\t\\t2. 逾期天数： \\t\\t\\t\\t\\t</strong> \\t\\t\\t\\t\\t逾期天数越长，借款人偿还意愿和能力通常越低，坏账转化率呈指数级上升。 \\t\\t\\t\\t</div> \\t\\t\\t\\t<div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 1px; text-indent: 0px; text-align: justify;''> \\t\\t\\t\\t\\t<strong> \\t\\t\\t\\t\\t\\t3. 逾期金额： \\t\\t\\t\\t\\t</strong> \\t\\t\\t\\t\\t金额大小直接决定了借款人的补救难度以及一旦形成坏账对中心造成的资金损失规模。 \\t\\t\\t\\t</div> \\t\\t\\t\\t<div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 1px; text-indent: 0px; text-align: justify;''> \\t\\t\\t\\t\\t<strong> \\t\\t\\t\\t\\t\\t4. 借款人账户状态： \\t\\t\\t\\t\\t</strong> \\t\\t\\t\\t\\t直接反映了其是否具备持续稳定的还款来源。 \\t\\t\\t\\t</div> \\t\\t\\t\\t<div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 1px; text-indent: 0px; text-align: justify;''> \\t\\t\\t\\t\\t<strong> \\t\\t\\t\\t\\t\\t5. 借款人管理部： \\t\\t\\t\\t\\t</strong> \\t\\t\\t\\t\\t按所属管理部分析，有助于识别特定区域的经济环境变化或各管理部催收工作的执行效能差异。 \\t\\t\\t\\t</div> \\t\\t\\t\\t<div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 1px; text-indent: 0px; text-align: justify;''> \\t\\t\\t\\t\\t<strong> \\t\\t\\t\\t\\t\\t6. 借款人单位： \\t\\t\\t\\t\\t</strong> \\t\\t\\t\\t\\t统计各单位的逾期人数，识别是否存在单位系统性经营风险或群体性违约倾向。 \\t\\t\\t\\t</div> \\t\\t\\t</div> \\t\\t</div> \\t</div> </div></div>"\u000a}\u000a,\u000a\u000a        \u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "service",\u000a    "id": "risk_analysis_root",\u000a    "className": "p-none",\u000a    \u000a    "body": [\u000a        \u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "m-t-lg m-b-md",\u000a            "style": {\u000a                "backgroundColor": "#fff",\u000a                "borderRadius": "8px",\u000a                "padding": "20px"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "tpl",\u000a                    "tpl": "<div style=''font-size: 14px; color: #333; margin-bottom: 10px; font-weight: 500;''>若对大模型分析存在其他要求，可填写具体意见，大模型根据您的补充信息进行分析。</div>"\u000a                },\u000a                {\u000a                    "type": "textarea",\u000a                    "name": "user_query",\u000a                    "id": "user_query_input",\u000a                    "placeholder": "",\u000a                    "minRows": 2,\u000a                    "maxRows": 5,\u000a                    "showCounter": false,\u000a                    "className": "w-full",\u000a                    "style": {\u000a                        "border": "1px solid #d9d9d9",\u000a                        "borderRadius": "6px"\u000a                    }\u000a                }\u000a            ]\u000a        },\u000a        \u000a\u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "m-t-lg",\u000a            "style": {\u000a                "border": "1px dashed #1890ff",\u000a                "borderRadius": "8px",\u000a                "backgroundColor": "#f0f7ff",\u000a                "padding": "30px",\u000a                "textAlign": "center"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "button-group",\u000a                    "buttons": [\u000a                        \u000a                        \u000a                        \u000a\u000a                        \u000a                        \u000a                        \u000a                        {\u000a                            "type": "button",\u000a                            "label": "📊 智能分析",\u000a                            "level": "danger",\u000a                            "style": {\u000a                                "background": "linear-gradient(180deg, #ff4d4f 0%, #cf1322 100%)",\u000a                               