     \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            "labelWidth": 150\u000a                                        }\u000a                                    ],\u000a                                    "md": 3\u000a                                }\u000a                                \u000a                            ]\u000a                        }\u000a                    ]\u000a                }\u000a                \u000a\u000a                \u000a\u000a                \u000a                \u000a                ,\u000a                {\u000a                    "type": "container",\u000a                    "className": "m-t-md m-b-md",\u000a                    "style": {\u000a                        "backgroundColor": "#f9fbff",\u000a                        "borderRadius": "8px",\u000a                        "padding": "20px",\u000a                        "border": "1px dashed #adc6ff"\u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<div style=''font-size: 14px; color: #333; margin-bottom: 10px; font-weight: 500;''>请输入分析需求</div>"\u000a                        },\u000a                        {\u000a                            "type": "textarea",\u000a                            "name": "query",\u000a                            "id": "query_input",\u000a                            "placeholder": "例如：请根据以上参数，分析该政策调整对不同收入群体的具体影响。",\u000a                            "minRows": 3,\u000a                            "maxRows": 6,\u000a                            "showCounter": true,\u000a                            "maxLength": 500,\u000a                            "className": "w-full",\u0