                         \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            "labelWidth": 150\u000a                                        }\u000a                                    ],\u000a                                    "md": 4\u000a                                },\u000a                                \u000a                                {\u000a                                    \u000a                                    \u000a                                    "body": [\u000a                                        {\u000a                                            "type": "input-number",\u000a                                            "name": "dkyql_mbyql",\u000a                                            "label": "目标逾期率(%)",\u000a                                            "value": "",\u000a                                            "placeholder": "-",\u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            "precision": 2,\u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a  