                  "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<div style=''font-size: 14px; color: #333; margin-bottom: 10px; font-weight: 500;''>请输入分析需求</div>"\u000a                        },\u000a                        {\u000a                            "type": "textarea",\u000a                            "name": "query",\u000a                            "id": "query_input",\u000a                            "placeholder": "例如：请根据以上参数，分析该政策调整对不同收入群体的具体影响。",\u000a                            "minRows": 3,\u000a                            "maxRows": 6,\u000a                            "showCounter": true,\u000a                            "maxLength": 500,\u000a                            "className": "w-full",\u000a                            "style": {\u000a                                "border": "1px solid #d9d9d9",\u000a                                "borderRadius": "6px"\u000a                            }\u000a                        }\u000a                    ]\u000a                }\u000a                \u000a            ],\u000a            "actions": [\u000a                \u000a                \u000a                \u000a                \u000a                \u000a                {\u000a                    "type": "button",\u000a                    "label": "历史数据",\u000a                    "level": "info",\u000a                    \u000a                    "style": {"marginLeft":"10px"},\u000a                    \u000a                    "onEvent": {\u000a                        "click": {\u000a                            "actions": [\u000a                                \u000a                                {\u000a                                    "actionType": "dialog",\u000a                                    "dialog": {"title":"历史数据清册","size":"xl","body":{"type":"tabs","tabs":[{"title":"内部数据","body":{"type":"crud","api":{"method":"post","url":"/HFB/common/dmx_policy/management=detail_query.service","data":{"&":"$$","cxlx":{"mxKey":"zcyc_dkyql_lsmx"},"jgbh":"1305282025"}},"perPageField":"size","syncLocation":false,"perPage":10,"perPageAvailable":[10,20,50,100],"footerToolbar":["statistics","switch-per-page","pagination"],"columns":[{"name":"value1","label":"年月","width":100},{"name":"value2","label":"贷款总金额(万元)","width":150},{"name":"value3","label":"逾期金额(万元)","width":150},{"name":"value4","label":"逾期率(‰)","width":150}]}},{"title":"外部数据","body":{"type":"service","api":{"method":"post","url":"/gjjrgzn/api/ai/get-history","data":{"&":"$$","data_source":"external"}},"body":{"type":"container","body":[{"type":"button-toolbar","className":"m-b-md","buttons":[{"type":"button","label":"📥 模板下载","level":"default","actionType":"download","api":{"method":"get","url":"/gjjrgzn/api/ai/download-template"}},{"type":"button","label":"📤 导入","level":"primary","actionType":"dialog","dialog":{"title":"导入外部数据","size":"lg","body":{"type":"form","api":{"method":"post","url":"/gjjrgzn/api/ai/import-external-data","data":{"&":"$$"}},"body":[{"type":"input-excel","name":"excel_data","label":"上传Excel文件","accept":".xlsx,.xls","autoFill":{"data_rows":"[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]"},"plainText":false,"parseMode":"array"},{"type":"static-json","name":"data_rows","label":"预览数据","levelExpand":1},{"type":"divider"},{"type":"alert","level":"info","body":"提示：上传后将自动解析Excel内容，请检查预览数据是否正确"}],"actions":[{"type":"button","label":"取消","actionType":"cancel"},{"type":"submit","label":"确认导入","level":"primary"}]}}}]},{"type":"crud","api":"[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]","syncLocation":false,"perPage":10,"perPageAvailable":[10,20,50,100],"footerToolbar":["statistics","pagination"],"columns":[{"name":"year_month","label":"年月","width":100},{"name":"czdjsyl","label":"城镇登记失业率(%)","width":150},{"name":"rjkzpsr","label":"人均可支配收入(元)","width":150},{"name":"jmxfjgzs","label":"居民消费价格指数(CPI)","width":150},{"name":"gdpzzl","label":"GDP增长率(%)","width":150}]}]}}}]}}\u000a                                }\u000a                                \u000a                            ]\u000a                        }\u000a                    }\u000a                },\u000a                \u000a                {\u000a                    "type": "button",\u000a                    "label": "AI预测",\u000a                    "level": "danger",\u000a                    \u000a                    "style": {\u000a                        "background": "linear-gradient(180deg, #ff4d4f 0%, #cf1322 100%)",\u000a                        "border": "none",\u000a                        "boxShadow": "0 4px 10px rgba(207, 19, 34, 0.3)",\u000a                        "fontWeight": "bold",\u000a                        "padding": "10px 24px"\u000a                    },\u000a                    \u000a                    "onEvent": {\u000a                        "click": {\u000a                            "actions": [\u000a                                \u000a                                 \u000a                                 {\u000a                                     "actionType": "custom",\u000a                                     "script": "(function(){ const checkboxes = Array.from(document.querySelectorAll(''.policy-param-checkbox'')); const readCard = (checkbox) => ({ key: checkbox.dataset.key || checkbox.dataset.label || '''', label: checkbox.dataset.label || '''', value: checkbox.dataset.value || '''', unit: checkbox.dataset.unit || '''' }); const allItems = checkboxes.map(readCard); const selectedItems = checkboxes.filter(item => item.checked).map(readCard); const unselectedItems = checkboxes.filter(item => !item.checked).map(readCard); const toSummary = (items) => items.length ? items.map(item => item.label + ''='' + item.value + (item.unit || '''')).join(''；'') : ''无''; const policyPrompt = allItems.length ? ''【政策参数约束】\\\\n当前政策参数：'' + toSummary(allItems) + ''\\\\n允许AI调整：'' + toSummary(selectedItems) + ''\\\\n禁止AI调整：'' + toSummary(unselectedItems) + ''\\\\n要求：后续分析、预测和建议时，只能调整“允许AI调整”中的政策参数，严禁调整“禁止AI调整”中的政策参数。'' : ''''; event.setData({ ...event.data, policy_params_all_json: JSON.stringify(allItems), policy_params_selected_json: JSON.stringify(selectedItems), policy_params_unselected_json: JSON.stringify(unselectedItems), policy_params_selected_labels: selectedItems.map(item => item.label).join(''、''), policy_params_unselected_labels: unselectedItems.map(item => item.label).join(''、''), policy_adjustment_prompt: policyPrompt }); })();"\u000a                                 },\u000a                                 \u000a                                 \u000a                                 {\u000a                                     "actionType": "setValue",\u000a                                     "componentId": "global_page_root",\u000a                                     "args": {\u000a                                         "value": {\u000a                                             "show_analysis_result": true,\u000a                                             "ai_loading": true\u000a                                         }\u000a                                     }\u000a                                 },\u000a                                 {\u000a                                    "actionType": "reload",\u000a                                    "componentId": "unified_analysis_service",\u000a                                    "args": {\u000a                                        "data": {\u000a                                            "&": 