INSERT INTO sys_page_template VALUES(852,'zxgdl','个贷率调控建议',unistr('\u000a\u000a\u000a{\u000a    "type": "page",\u000a    \u000a    \u000a    "id": "global_page_root",     \u000a    "className": "p-none",\u000a    \u000a    \u000a    "data": {\u000a        "show_analysis_result": false,  \u000a        "ai_loading": false,            \u000a        "show_prediction": false        \u000a    },\u000a\u000a    "body": [\u000a        \u000a        \u000a\u000a\u000a\u000a{\u000a    "type": "container",\u000a    "className": "page-header-component",\u000a    "style": {\u000a        "backgroundColor": "",\u000a        "padding": "20px 20px", \u000a        "marginBottom": "20px",\u000a        "position": "relative"  \u000a    },\u000a    \u000a    \u000a    \u000a\u000a    "body": [\u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a            "type": "service",\u000a            "style": {\u000a                "width": "100%" \u000a            },\u000a            "api": {\u000a                "method": "post",\u000a                "url": "/HFB/common/dmx_policy/management=title_query.service",\u000a                "dataType": "json"\u000a                ,\u000a                "data": {\u000a  "cxlx": "{\\n  \\"titleKey\\": \\"zcyc_zxgdl_title\\"\\n}",\u000a  "jgbh": "1305282025"\u000a}\u000a                \u000a                \u000a            },\u000a            "body": [\u000a                \u000a                \u000a                {\u000a                    "type": "container",\u000a                    "className": "text-center",\u000a                    "style": {\u000a                        "position": "static" \u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<h2 style=''font-size: 22px; font-weight: 600; color: #262626; margin: 5px 0;''>个贷率调控建议</h2>"\u000a                        },\u000a                        {\u000a                            "type": "tpl",\u000a                            "tpl": "<div style=''color: #8c8c8c; font-size: 13px;''>${displayText}</div>"\u000a                        }\u000a                    ]\u000a                }\u000a                \u000a            ]\u000a        }\u000a        \u000a        \u000a        \u000a    ]\u000a}\u000a\u000a\u000a,\u000a\u000a        \u000a        \u000a\u000a{\u000a    "type": "tpl",\u000a    "tpl": "<div style=''margin-bottom: 12px; padding: 12px 16px; border-radius: 4px; background-color: #e6f7ff; border: 1px solid #91d5ff; color: #1890ff;''><div style=\\"margin: -13px -17px; background: white; padding: 16px 20px; border: 1px solid #e8e8e8;\\"> \\t<div style=\\"display: flex; align-items: center; gap: 8px; margin-bottom: 16px;\\"> \\t\\t<div style=\\"background: #3b82f6; color: white; border-radius: 3px; padding: 3px 8px; font-weight: bold; font-size: 11px;\\"> \\t\\t\\tAI \\t\\t</div> \\t\\t<div style=\\"color: #1a202c; font-weight: 600; font-size: 15px;\\"> \\t\\t\\t个贷率政策 \\t\\t</div> \\t</div> \\t<div style=\\"margin-bottom: 14px;\\"> \\t\\t<div style=\\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\\"> \\t\\t\\t定义 \\t\\t</div> \\t\\t<div style=\\"color: #4a5568; font-size: 13px; line-height: 1.6;\\"> \\t\\t\\t中心个贷率是指住房公积金个人住房贷款余额占归集余额的比例，计算公式为：个贷率 = 贷款余额 / 归集余额 × 100%。该指标是衡量住房公积金资金使用效率和风险水平的核心指标，反映公积金中心的资金流动性状况和贷款发放能力。个贷率过高可能导致资金流动性紧张，影响正常提取和贷款发放；个贷率过低则表明资金使用效率不高，未能充分发挥公积金制度的住房保障作用。 \\t\\t</div> \\t</div> \\t<div style=\\"color: #1890ff; font-weight: 600; font-size: 13px; margin-bottom: 6px;\\"> \\t\\t影响政策 \\t</div> \\t<div style=\\"color: #4a5568; font-size: 13px; line-height: 1.7;\\"> \\t\\t<div style=\\"margin-bottom: 4px;\\"> \\t\\t\\t1、单缴存职工最高贷款额度30万元、双职工家庭最高额度60万元； \\t\\t</div> \\t\\t<div style=\\"margin-bottom: 4px;\\"> \\t\\t\\t2、最高可贷额度不高于账户余额的15倍； \\t\\t</div> \\t\\t<div style=\\"margin-bottom: 4px;\\"> \\t\\t\\t3、首套房首付款不低于房屋总价的20%，二套房不低于房屋总价的30%； \\t\\t</div> \\t\\t<div style=\\"margin-bottom: 4px;\\"> \\t\\t\\t4、连续缴存住房公积金满6个月方可申请贷款； \\t\\t</div> \\t\\t<div style=\\"margin-bottom: 4px;\\"> \\t\\t\\t5、二手房房龄加贷款年限不超过50年； \\t\\t</div> \\t\\t<div style=\\"margin-bottom: 4px;\\"> \\t\\t\\t6、贷款年限不超过借款人退休年龄，最长可延长5年； \\t\\t</div>\\t\\t \\t\\t<div style=\\"margin-bottom: 4px;\\"> \\t\\t\\t7、享受人才安居政策额度上浮20%； \\t\\t</div>\\t\\t \\t\\t<div style=\\"margin-bottom: 4px;\\"> \\t\\t\\t8、二孩及以上家庭成员额度上浮20%。 \\t\\t</div>\\t\\t \\t</div> </div> </div></div>"\u000a}\u000a,\u000a\u000a        \u000a        {\u000a            "type": "container",\u000a            "className": "m-t-md",\u000a            "style": {\u000a                "backgroundColor": "#fff",\u000a                "borderRadius": "10px",\u000a                "boxShadow": "0 4px 8px rgba(0, 0, 0, 0.05)",\u000a                "padding": "25px",\u000a                "marginBottom": "20px"\u000a            },\u000a            "body": [\u000a                \u000a                \u000a    {\u000a      "type": "service",\u000a      \u000a      "api": {\u000a        "method": "post",\u000a        "url": "/HFB/common/dmx_policy/management=metrics_query.service"\u000a        \u000a        ,"data": {"cxlx":"{\\n  \\"metricsKey\\": \\"zcyc_zxgdl_value\\"\\n}","jgbh":"1305282025"}\u000a        \u000a        \u000a      },\u000a      \u000a      "body": [\u000a        \u000a        \u000a\u000a        \u000a        \u000a        \u000a        {\u000a          "type": "each",\u000a          "name": "${groups || [{ items: [], title: '''', columns: 5, border_color: '''' }]}",\u000a          "items": {\u000a            "type": "container",\u000a            "className": "m-b-md",\u000a            "body": [\u000a              {\u000a                "type": "html",\u000a                "tpl": "<div style=''font-weight: 600; font-size: 15px; margin-bottom: 12px; color: #1a3c6e; display: flex; align-items: center; gap: 8px;''>${title}</div>",\u000a                "visibleOn": "this.title"\u000a              },\u000a              {\u000a                "type": "container",\u000a                "className": "stats-cards-grid ${border_color ? ''border-'' + border_color : ''''} m-b-md",\u000a                "style": {\u000a                  "display": "flex",\u000a                  "flexWrap": "wrap",\u000a                  "gap": "16px",\u000a                  "width": "100%"\u000a                },\u000a                "body": [\u000a                  {\u000a                    "type": "each",\u000a                    "name": "items",\u000a                    "style": {\u000a                      "display": "contents"\u000a                    },\u000a                    "items": {\u000a                      "type": "container",\u000a                      "className": "stat-card",\u000a                      "style": {\u000a                        "flex": "0 0 calc(${100 / (columns || 5)}% - 16px)",\u000a                        "minWidth": "120px"\u000a                      },\u000a                      "body": [\u000a                        {\u000a                          "type": "html",\u000a                          "html": "<div class=''stat-label''>${label}</div><div class=''stat-value'' style=''color: #007bff; font-weight: bold;''>${value}${unit ? ''<span class=\\"stat-unit\\" style=\\"font-size: 14px; font-weight: normal; margin-left: 4px;\\">'' + unit + ''</span>'' : ''''}</div><div class=''stat-trend trend-${trend_color || trend}'' style=''display: ${trend ? \\"inline-block\\" : \\"none\\"}''>${trend == ''up'' ? ''↑'' : (trend == ''down'' ? ''↓'' : '''')} ${trend_value}</div>"\u000a                        }\u000a                      ]\u000a                    }\u000a                  }\u000a                ]\u000a              }\u000a            ]\u000a          }\u000a        }\u000a        \u000a      ]\u000a    }\u000a\u000a            ]\u000a        },\u000a\u000a        \u000a        \u000a        \u000a        \u000a\u000a{\u000a    "type": "c