     \u000a                                {\u000a                                    \u000a                                    \u000a                                    "body": [\u000a                                        {\u000a                                            "type": "select",\u000a                                            "name": "zxgdl_dqgdl",\u000a                                            "label": "当前个贷率(%)",\u000a                                            "value": "",\u000a                                            \u000a                                            \u000a                                            "static": true,\u000a                                            \u000a                                            \u000a                                            "source": {"method":"post","url":"/HFB/common/dmx_policy/management=static_query.service","data":{"cxlx":{"metricsKey":"zcyc_zxgdl_newvalue"},"jgbh":"1305282025"},"adaptor":"return { ...payload, options: payload.data.options }"},\u000a                                            \u000a                                            \u000a                                            \u000a                                            "selectFirst": true,\u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            "labelWidth": 150\u000a                                        }\u000a                                    ],\u000a                                    "md": 4\u000a                                },\u000a                                \u00