 \u000a                                {\u000a                                    \u000a                                    \u000a                                    "body": [\u000a                                        {\u000a                                            "type": "checkbox",\u000a                                            "name": "lock_zftq_sfba",\u000a                                            "label": "锁定",\u000a                                            "value": false,\u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            \u000a                                            "labelWidth": 150\u000a                                        }\u000a                                    ],\u000a                                    "md": 6\u000a                                }\u000a                                \u000a                            ]\u000a                        }\u000a                    ]\u000a                }\u000a                \u000a\u000a                \u000a\u000a                \u000a                \u000a            ],\u000a            "actions": [\u000a                \u000a                \u000a                \u000a                \u000a                \u000a                {\u000a                    "type": "button",\u000a                    "label": "📊 智能分析",\u000a                    "level": "danger",\u000a                    \u000a                    "style": {\u000a                        "background": "linear-gradient(180deg, #ff4d4f 0%, #cf1322 100%)",\u000a                        "border": "none",\u000a                        "boxShadow": "0 4px 10px rgba(207, 19, 34, 0.3)",\u000a                        "fontWeight": "bold",\u000a                        "padding": "10px 24px"\u000a                    },\u000a                    \u000a                    "onEvent": {\u000a                        "click": {\u000a                            "actions": [\u000a                                \u000a                                 \u000a                                 {\u000a                                     "actionType": "setValue",\u000a                                     "componentId": "global_page_root",\u000a                                     "args": {\u000a                                         "value": {\u000a                                             "show_analysis_result": true,\u000a                                             "ai_loading": true\u000a                                         }\u000a                                     }\u000a                                 },\u000a                                 {\u000a                                    "actionType": "reload",\u000a                                    "componentId": "unified_analysis_service",\u000a                                    "args": {\u000a                                        "data": {\u000a                                            "&": "$$"\u000a                                        }\u000a                                    }\u000a                                }\u000a                                \u000a                            ]\u000a                        }\u000a                    }\u000a                },\u000a                \u000a                {\u000a                    "type": "button",\u000a                    "label": "🔄 重置",\u000a                    "level": "default",\u000a                    \u000a                    "style": {"marginLeft":"10px"},\u000a                    \u000a                    "onEvent": {\u000a                        "click": {\u000a                            "actions": [\u000a                                \u000a                            ]\u000a                        }\u000a                    }\u000a                }\u000a                \u000a            ]\u000a        },\u000a\u000a        \u000a        {\u000a            "type": "service",\u000a            "id": "unified_analysis_service",\u000a            "className": "${!show_analysis_result ? ''hidden'' : ''m-t-md''}",\u000a            "initFetch": false,\u000a            "schemaApi": {\u000a                "method": "post",\u000a                "url": "/api/ai/generate-page",\u000a                "sendOn": "this.ai_loading === true",\u000a                "data": {\u000a                    "&": "$$",\u000a                    "pageId": "zftq",\u000a                    "workflow_type": "ai_analysis",\u000a                    "timestamp": "${date(now(), ''x'')}",\u000a                    "query": "${data.query || query || ''用户未指定要求''}"\u000a                }\u000a            },\u000a            "onEvent": {\u000a                "fetchSchemaInited": {\u000a                    "actions": [\u000a                        { "actionType": "setValue", "componentId": "global_page_root", "args": { "value": { "ai_loading": false } } },\u000a                        { "actionType": "toast", "args": { "msgType": "success", "msg": "分析完成" } }\u000a                    ]\u000a                },\u000a                "fetchFailed": {\u000a                    "actions": [\u000a                        { "actionType": "setValue", "componentId": "global_page_root", "args": { "value": { "ai_loading": false } } },\u000a                        { "actionType": "toast", "args": { "msgType": "error", "msg": "生成失败，请稍后重试" } }\u000a                    ]\u000a                }\u000a            },\u000a            "body": {\u000a                "type": "tpl",\u000a                "tpl": "",\u000a                "visible": false\u000a            }\u000a        },\u000a\u000a        \u000a        {\u000a            "type": "container",\u000a            "visibleOn": "${ai_loading}",\u000a            "style": {\u000a                "position": "fixed",\u000a                "top": "0",\u000a                "left": "0",\u000a                "width": "100vw",\u000a                "height": "100vh",\u000a                "backgroundColor": "rgba(255, 255, 255, 0.6)",\u000a                "zIndex": "9999",\u000a                "display": "flex",\u000a                "alignItems": "center",\u000a                "justifyContent": "center",\u000a                "backdropFilter": "blur(8px)"\u000a            },\u000a            "body": [\u000a                {\u000a                    "type": "container",\u000a                    "style": {\u000a                        "backgroundColor": "transparent",\u000a                        "boxShadow": "none",\u000a                        "border": "none",\u000a                        "padding": "0",\u000a                        "width": "auto",\u000a                        "textAlign": "center"\u000a                    },\u000a                    "body": [\u000a                        {\u000a                            "type": "custom",\u000a                            "name": "ai-modal-timer",\u000a                            "html": "<div style=''font-family: -apple-system, BlinkMacSystemFont, Helvetica Neue, Arial; color: #333;''><div style=''position: relative; width: 80px; height: 80px; margin: 0 auto 24px auto;''><svg viewBox=''0 0 50 50'' style=''width: 100%; height: 100%; animation: spin 2s linear infinite;''><circle cx=''25'' cy=''25'' r=''20'' fill=''none'' stroke=''#e6f7ff'' stroke-width=''4''></circle><circle cx=''25'' cy=''25'' r=''20'' fill=''none'' stroke=''#1890ff'' stroke-width=''4'' stroke-dasharray=''80'' stroke-dashoffset=''60'' stroke-linecap=''round''></circle></svg><div style=''position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; font-size: 22px; font-weight: 700; color: #1890ff; font-feature-settings: \\"tnum\\";''><span id=''policy-timer-sec''>0</span><span style=''font-size: 12px; margin-left: 2px; font-weight: 400;''>s</span></div></div><div style=''font-size: 18px; font-weight: 600; color: #333; margin-bottom: 12px; letter-spacing: 0.5px; text-shadow: 0 2px 10px rgba(255,255,255,0.8);''>AI 智能分析中</div><div id=''policy-timer-text'' style=''font-size: 14px; color: #666; height: 20px; font-weight: 500;''>正在接入数据中心...</div><style>@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }</style></div>",\u000a                            "onMount": "const startTime = Date.now(); const secDom = document.getElementById(''policy-timer-sec''); const textDom = document.getElementById(''policy-timer-text''); const texts = [''正在加载政策数据...'', ''正在分析参数影响...'', ''AI 正在生成洞察...'', ''正在渲染分析报告...'']; window.policyTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                            "onUnmount": "clearInterval(window.policyTimer);"\u000a                        }\u000a                    ]\u000a                }\u000a            ]\u000a        }\u000a    ]\u000a}\u000a,\u000a\u000a        \u000a        {\u000a            "type": "tpl",\u000a            "tpl": "<div style=''text-align: cent