                "onMount": "const startTime = Date.now(); const secDom = document.getElementById(''policy-timer-sec''); const textDom = document.getElementById(''policy-timer-text''); const texts = [''正在加载政策数据...'', ''正在分析参数影响...'', ''AI 正在生成洞察...'', ''正在渲染分析报告...'']; window.policyTimer = setInterval(() => { const elapsed = ((Date.now() - startTime) / 1000).toFixed(1); if(secDom) secDom.innerText = elapsed; const step = Math.floor(elapsed / 3) % texts.length; if(textDom) textDom.innerText = texts[step]; }, 100);",\u000a                            "onUnmount": "clearInterval(window.policyTimer);"\u000a                        }\u000a                    ]\u000a                }\u000a            ]\u000a        }\u000a    ]\u000a}\u000a,\u000a\u000a        \u000a        {\u000a            "type": "tpl",\u000a            "tpl": "<div style=''text-align: center; color: #999; font-size: 12px; padding: 20px 0;''>住房公积金管理中心 © 2025</div>"\u000a        }\u000a    ]\u000a}\u000a'),1,24,NULL,'2026-04-22 11:38:06','2026-04-22 11:38:06','policy_demo','{"template_id":"policy_demo","target_page_key":"zftq","page_title":"租房提取政策调整预测","app_theme":"default","manual_page_key":"zftq","formFields":[{"type":"fieldSet","title":"🎨 页面头部配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"title","label":"页面标题","required":false,"type":"input-text","placeholder":"页面标题"},{"name":"title_font_size","label":"标题字体大小","required":false,"type":"input-text","placeholder":"22px"},{"name":"subtitle_api","label":"副标题数据API地址（配置后，副标题将动态显示API返回的数据;不配置则使用静态副标题或不使用副标题）","required":false,"type":"input-text","placeholder":"/api/subtitle"},{"name":"subtitle_api_method","label":"副标题API请求方法","required":false,"type":"input-text","placeholder":"post"},{"name":"subtitle_api_data","label":"副标题API的固定请求参数（JSON对象或字符串）","required":false,"type":"input-text","placeholder":""},{"name":"subtitle_api_adaptor","label":"副标题API数据适配器（副标题API返回的数据不满足 amis 格式时可设置）","required":false,"type":"input-text","placeholder":""