": "/HFB/common/dmx/management=gjznkm_dr.service",\u000a\u0009                                                    "data": {"cxlx":"dwsbxx_dr","jgbh":"1305282025"}\u000a\u0009                                                }\u000a\u0009                                            }\u000a\u0009                                            \u000a                                        ]\u000a                                    }\u000a                                    \u000a                                    \u000a                                ],\u000a                                "actions": []\u000a                            }\u000a                        }\u000a                        \u000a\u000a                        \u000a                        \u000a                        ,\u000a                        {\u000a\u0009                            "type": "button",\u000a\u0009                            "label": "📊 智能分析",\u000a\u0009                            "level": "danger",\u000a\u0009                            "style": {\u000a                                "background": "linear-gradient(180deg, #ff4d4f 0%, #cf1322 100%)",\u000a                                "border": "none",\u000a                                "boxShadow": "0 4px 10px rgba(207, 19, 34, 0.3)",\u000a                                "fontWeight": "bold",\u000a                                "width": "140px",\u000a                                "height": "40px"\u000a                            },\u000a\u0009                            "onEvent": {\u000a\u0009                                "click": {\u000a\u0009                                    "actions": [\u000a\u0009                                        \u000a\u0009                                        {\u000a\u0009                                            "actionType": "ajax",\u000a\u0009                                            "outputVar": "importCheckResult",\u000a\u0009                                            "api": {\