e":"enable_data_import","label":"是否启用数据导入功能","required":false,"type":"switch","value":true},{"name":"import_dialog_title","label":"数据导入对话框标题","required":false,"type":"input-text","placeholder":"贷后资产质量数据导入"},{"name":"enable_ai_analysis","label":"是否启用AI分析功能","required":false,"type":"switch","value":true},{"name":"enable_query_input","label":"是否启用分析需求输入框","required":false,"type":"switch","value":true},{"name":"query_label","label":"分析需求输入框标签","required":false,"type":"input-text","placeholder":"请输入分析需求"},{"name":"query_placeholder","label":"分析需求输入框占位符","required":false,"type":"input-text","placeholder":"例如：生成贷款逾期分析图表"},{"name":"ai_generate_api","label":"AI生成页面API地址","required":false,"type":"input-text","placeholder":"/api/ai/generate-page"},{"name":"workflow_type","label":"AI 工作流类型标识（默认：ai_analysis）","required":false,"type":"input-text","placeholder":"ai_analysis"},{"name":"query","label":"AI分析查询参数","required":false,"type":"input-text","placeholder":"用户未指定要求"},{"name":"import_items","label":"数据导入项配置（每项包含标题、接口、参数等）","required":false,"type":"combo","multiple":true,"multiLine":true,"draggable":true,"addButtonText":"新增 项目","items":[{"name":"title","label":"显示标题","required":false,"type":"input-text","placeholder":""},{"name":"key","label":"字段名","required":false,"type":"input-text","placeholder":""},{"name":"desc","label":"描述文字","required":false,"type":"input-text","placeholder":""},{"name":"accept","label":"上传文件类型限制 (默认 .xls,.xlsx)","required":false,"type":"input-text","placeholder":""},{"name":"template_url","label":"模板下载接口","required":false,"type":"input-text","placeholder":""},{"name":"template_data","label":"模板下载参数(JSON)","required":false,"type":"input-text","placeholder":""},{"name":"upload_api","label":"上传接口","required":false,"type":"input-text","placeholder":""},{"name":"upload_data","label":"上传参数(JSON)","required":false,"type":"input-text","placeholder":""}],"value":[]}]},{"type":"fieldSet","title":"⚙️ 其他配置","className":"m-t","collapsable":true,"collapsed":true,"body":[{"name":"footer_text","label":"底部文本 (自动推断)","required":false,"type":"input-text","placeholder":"© 2025"},{"name":"default_items","label":"default items (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"length","label":"length (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"desc","label":"desc (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"template_url","label":"template url (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"upload_api","label":"upload api 地址 (自动推断)","required":false,"type":"input-text","placeholder":"/api/upload"},{"name":"key","label":"key (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"accept","label":"accept (自动推断)","required":false,"type":"input-text","placeholder":""},{"name":"upload_data","label":"upload data (自动推断)","required":false,"type":"input-text","placeholder":""}]}],"__debug":"adaptor executed","enable_report_button":false,"enable_data_import":true,"enable_ai_analysis":true,"enable_query_input":true,"import_items":[{"title":"社保数据","key":"","desc":"支持格式: .xlsx","accept":".xlsx","template_url":"/HFB/common/dmx/management=gjznkm_mbxz.service","template_data":"{\n  \"cxlx\": \"lhsbxx_mbxz\",\n  \"jgbh\": \"1305282025\",\n  \"value1\": \"社保数据模板\"\n}","upload_api":"/HFB/common/dmx/management=gjznkm_dr.service","upload_data":"{\n  \"cxlx\": \"lhsbxx_dr\",\n  \"jgbh\": \"1305282025\"\n}","sortOrder":10},{"title":"婚姻数据","accept":".xlsx","desc":"支持格式: .xlsx","template_url":"/HFB/common/dmx/management=gjznkm_mbxz.service","template_data":"{\n  \"cxlx\": \"lhhyxx_mbxz\",\n  \"jgbh\": \"1305282025\",\n  \"value1\": \"婚姻数据模板\"\n}","upload_api":"/HFB/common/dmx/management=gjznkm_dr.service","upload_data":"{\n  \"cxlx\": \"lhhyxx_dr\",\n  \"jgbh\": \"1305282025\"\n}","sortOrder":20},{"upload_data":"{\n  \"cxlx\": \"lhbdcxx_dr\",\n  \"jgbh\": \"1305282025\"\n}","upload_api":"/HFB/common/dmx/management=gjznkm_dr.service","template_data":"{\n  \"cxlx\": \"lhbdcxx_mbxz\",\n  \"jgbh\": \"1305282025\",\n  \"value1\": \"不动产数据模板\"\n}","desc":"支持格式: .xlsx","accept":".xlsx","template_url":"/HFB/common/dmx/management=gjznkm_mbxz.service","title":"不动产数据","sortOrder":30}],"key":"https://appcs.jbysoft.com/gjjrgzn/system/config?","title":"灵活缴存扩面","page_key":"lhjckm","id":814,"version":1,"mode":"create","footer_text":"","alert_html":"<div style=''margin-bottom: 12px;''> <div style=''background-color: #ffffff; border: 1px solid #d9d9d9; border-radius: 8px; padding: 20px 24px; line-height: 1.7;''> <div style=''color: #1d1d1f; font-weight: 700; font-size: 16px; margin-bottom: 18px; padding-left: 12px; border-left: 4px solid #1890ff;''> 定义与分类</div> <div style=''margin-bottom: 20px;''><div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''>定义</div><div style=''color: #333; font-size: 13px; line-height: 1.8; margin-bottom: 12px; text-align: justify;''>灵活缴存职工扩面，是指住房公积金管理部门通过社保、婚姻、不动产数据的交叉比对与综合分析，精准识别出未缴纳住房公积金的灵活就业人员，为其提供差异化、针对性的缴存政策指导与服务支持，从而吸纳该群体纳入公积金制度覆盖范围，保障灵活就业人员住房消费与资金储备权益的专项工作。</div></div><div style=''margin-bottom: 0;''><div style=''color: #1890ff; font-weight: 600; font-size: 14px; margin-bottom: 12px;''>分类</div><div style=''padding-left: 0; margin-top: 10px;''><div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 24px; text-indent: -24px; text-align: justify;''>高潜力群体：高潜力群体有稳定社保缴费记录，叠加不动产交易、婚姻住房需求等数据，缴存意愿和能力双高。</div><div style=''color: #555; font-size: 13px; line-height: 1.8; margin-bottom: 10px; padding-left: 24px; text-indent: -24px; text-align: justify;''>中潜力群体：中潜力群体社保缴费断续，有潜在购房刚需但暂未落实行动，具备一定储蓄规划基础，需政策激励激活缴存意愿。</div></div></div></div></div>","import_dialog_title":"","query_label":"若对大模型分析存在其他要求，可填写具体意见，大模型根据您的补充信息进行分析。","query_placeholder":"","import_check_api":"/HFB/common/dmx/management=gjznkm_drzt.service","import_check_api_method":"post","import_check_data":"{\n  \"cxlx\": \"drzt\",\n  \"page_key\": \"lhjckm\",\n  \"jgbh\": \"1305282025\"\n}","import_check_adaptor":""}');
INSERT INTO sys_component_library VALUES(8,'chart_with_ai','通用图表(带AI分析)','chart','通用图表组件，支持6种图表类型。使用chart_type参数选择：pie(饼图,适合占比分布)、bar(柱状图,适合类别对比)、line(折线图,适合趋势展示)、funnel(漏斗图,适合流程转化)、radar(雷达图,适合多维对比)、gauge(仪表盘,适合指标完成度)。支持钻取功能(drilldown_api+drilldown_params+drilldown_columns)和AI分析面板(ai_analysis_text+ai_suggestions)','components/chart_with_ai.j2','{"chart_type":{"type":"string","enum":["pie","bar","line","funnel","radar","gauge"],"description":"图表类型","required":true},"title":{"type":"string","description":"图表标题"},"api_url":{"type":"string","description":"图表数据API地址","required":true},"api_method":{"type":"string","enum":["get","post"],"description":"API请求方法","default":"get"},"api_data":{"type":"object","description":"POST请求时的请求体参数"},"height":{"type":"number","description":"图表高度","default":400},"chart_options":{"type":"object","description":"图表特定配置"},"drilldown_api":{"type":"string","description":"钻取详情API地址"},"drilldown_method":{"type":"string","enum":["get","post"],"description":"钻取API请求方法","default":"get"},"drilldown_data":{"type":"object","description":"钻取API POST请求时的基础参数"},"drilldown_columns":{"type":"array","description":"钻取表格列定义","items":{"type":"object"}},"export_api":{"type":"string","description":"导出API地址"},"ai_analysis_text":{"type":"string","description":"AI生成的风险分析"},"ai_suggestions":{"type":"string","description":"AI生成的规避建议"},"enable_drilldown":{"type":"boolean","description":"是否启用钻取","default":true}}','{"chart_type":"pie","title":"数据分布","api_url":"/api/demo/chart/data","height":400}',NULL,1,'2025-12-19 11:57:57','2025-12-19 11:57:57');
INSERT INTO sys_component_library VALUES(9,'alert','提示框/告警','display','提示框组件，用于显示提示信息、警告、错误或成功消息。使用 alert_html 参数传入预生成的 HTML 内容。','components/alert.j2','{"alert_html":{"type":"string","description":"提示框的完整HTML内容，包含样式和消息","required":true}}','{}','用于页面顶部提示、操作结果反馈、重要告警信息展示等。示例：alert_html="<div class=alert alert-warning>这是一条警告消息</div>"',1,'2025-12-22 04:49:07','2025-12-22 04:49:07');
INSERT INTO sys_component_library VALUES(10,'ai_form','AI提问表单','form','AI智能分析表单组件，用于向AI发送分析请求并动态加载返回结果。支持自定义标题、输入框文字、按钮文字和API地址。','components/ai_form.j2','{"title":{"type":"string","description":"表单标题","default":"向 AI 提问"},"label":{"type":"string","description":"输入框标签","default":"请输入分析需求"},"placeholder":{"type":"string","description":"输入框占位符"},"default_value":{"type":"string","description":"输入框默认值"},"button_text":{"type":"string","description":"按钮文字","default":"开始分析"},"api_url":{"type":"string","description":"AI分析API地址","required":true},"api_method":{"type":"string","enum":["get","post"],"description":"API请求方法","default":"post"},"page_id":{"type":"string","description":"页面ID参数"},"workflow_type":{"type":"string","description":"工作流类型"}}','{}','用于AI智能页面生成、数据分析等场景。示例：api_url="/api/ai/generate-page"',1,'2025-12-22 05:56:36','2025-12-22 05:56:36');
INSERT INTO sys_component_library VALUES(11,'stats_cards','统计指标卡片','display','展示多个关键业务指标，支持静态数据或API动态加载，支持趋势箭头显示','components/stats_cards.j2','{"type":"object","properties":{"title":{"type":"string","description":"组标题"},"border_color":{"type":"string","enum":["red","blue","green","orange","gray"],"description":"边框颜色"},"columns":{"type":"integer","default":5,"description":"每行显示列数"},"items":{"type":"array","description":"指标数据列表","items":{"type":"object","properties":{"label":{"type":"string","description":"指标名称"},"value":{"type":["string","number"],"description":"指标值"},"unit":{"type":"string","description":"单位"},"sub_label":{"type":"string","description":"副标题"},"trend":{"type":"string","enum":["up","down"],"description":"趋势方向"},"trend_value":{"type":"string","description":"趋势变化值"},"trend_color":{"type":"string","enum":["red","green","auto"],"default":"auto","description":"趋势颜色"}},"required":["label","value"]}},"api_url":{"type":"string","description":"API地址"},"api_method":{"type":"string","enum":["get","post"],"default":"get","description":"API方法"},"api_data":{"type":"object","description":"API参数"},"api_headers":{"type":"object","description":"API请求头"}}}','{"columns":5,"border_color":"gray"}',unistr('## 使用示例\u000a\u000a### API 动态加载\u000a\u000a**调用方式：**\u000a```json\u000a{\u000a  "component_id": "stats_cards",\u000a  "params": {\u000a    "title": "实时业务指标",\u000a    "border_color": "blue",\u000a    "columns": 4,\u000a    "api_url": "/HFB/common/dmx_risk/management=stats_overview.service",\u000a    "api_method": "post",\u000a    "api_data": {\u000a      "cxlx": {\u000a        "moduleKey": "fxgl",\u000a        "ywflKey": "jcdjfx"\u000a      },\u000a      "jgbh": "1305282025",\u000a      "date_range": "2025-01"\u000a    },\u000a    "api_headers": {\u000a      "Authorization": "Bearer ${token}"\u000a    }\u000a  }\u000a}\u000a```\u000a\u000a**API 返回格式：**\u000a```json\u000a{\u000a  "status": 0,\u000a  "msg": "success",\u000a  "data": {\u000a    "items": [\u000a      {\u000a        "label": "连续缴存6个月",\u000a        "value": "12000",\u000a        "trend": "up",\u000a        "trend_value": "5.2%"\u000a      },\u000a      {\u000a        "label": "还款能力",\u000a        "value": "月收入大于月息存金额的2倍"\u000a      },\u000a      {\u000a        "label": "最大贷款周期",\u000a        "value": "30年"\u000a      }\u000a    ]\u000a  }\u000a}\u000a```\u000a\u000a**API 接口要求：**\u000a- 返回数据必须包含 `items` 数组\u000a- 每个 item 至少包含 `label` 和 `value`\u000a- 可选字段：`trend`, `trend_value`, `trend_color`, `unit`, `sub_label`'),1,'2025-12-25 01:08:09','2025-12-25 01:08:09');
INSERT INTO sys_component_library VALUES(12,'data_table','CRUD数据表格','table','通用数据表格组件,封装AMIS CRUD完整功能。支持分页(可自定义分页参数名)、序号列、筛选表单、批量操作、行操作等。支持POST固定参数配置。','components/data_table.j2','{"type":"object","properties":{"api_url":{"type":"string","description":"数据API地址"},"api_method":{"type":"string","enum":["get","post"],"default":"post"},"api_data":{"type":"object","description":"POST请求的固定参数"},"page_field":{"type":"string","default":"page","description":"分页页码字段名"},"page_size_field":{"type":"string","default":"perPage","description":"分页大小字段名"},"columns":{"type":"array","description":"表格列定义"},"enable_sequence":{"type":"boolean","default":true,"description":"是否显示序号列"},"sequence_label":{"type":"string","default":"序号","description":"序号列标题"},"filter_form":{"type":"array","description":"筛选表单字段配置"},"per_page":{"type":"integer","default":10},"per_page_options":{"type":"array","default":[10,20,50,100]},"enable_batch":{"type":"boolean","default":false},"batch_actions":{"type":"array"},"header_toolbar":{"type":"array"},"footer_toolbar":{"type":"array"},"primary_field":{"type":"string","default":"id"}},"required":["api_url"]}','{"api_method":"post","enable_sequence":true,"sequence_label":"序号","per_page":10,"per_page_options":[10,20,50,100],"enable_batch":false,"primary_field":"id","page_field":"page","page_size_field":"perPage"}',NULL,1,'2026-01-16 02:07:35','2026-01-16 02:07:35');
INSERT INTO sys_page_templates_config VALUES(22,'active_demo','主动服务模板','通用主动服务页面，支持服务卡片配置与动态数据刷新','pages/active_demo.j2','["⚙️ 其他配置"]','{"type":"object","properties":{"title":{"type":"string","title":"标题文本","description":"标题文本","ui:group":"📄 页面头部配置","ui:groupOrder":1,"ui:order":1,"default":"页面标题"},"show_refresh_button":{"type":"boolean","title":"是否显示刷新按钮","description":"是否显示刷新按钮","ui:group":"📄 页面头部配置","ui:groupOrder":1,"ui:order":2,"default":true},"refresh_button_text":{"type":"string","title":"刷新按钮文本","description":"刷新按钮文本","ui:group":"📄 页面头部配置","ui:groupOrder":1,"ui:order":3,"default":"刷新数据"},"reload_target":{"type":"string","title":"刷新目标组件名称","description":"刷新目标组件名称","ui:group":"📄 页面头部配置","ui:groupOrder":1,"ui:order":4,"default":"service_cards_grid"},"cards":{"type":"array","title":"卡片列表","description":"卡片配置列表，每个卡片包含：","ui:group":"🎴 服务卡片配置","ui:groupOrder":2,"ui:order":5,"items":{"type":"object","title":"卡片","properties":{"title":{"type":"string","title":"标题"},"icon":{"type":"string","title":"图标","description":"FontAwesome图标类名，如 fa fa-home"},"desc":{"type":"string","title":"描述","format":"textarea"},"api":{"type":"string","title":"数据接口API"},"api_data":{"type":"json","title":"数据接口参数"},"target_label":{"type":"string","title":"数据标签","default":"目标群体"},"target_value":{"type":"string","title":"静态数据值","description":"不使用API时显示此静态值"},"button_label":{"type":"string","title":"按钮文本","default":"一键提醒"},"crud_config":{"type":"json","title":"详情弹窗配置","description":"完整 AMIS JSON 配置 (dialog.body)"}}},"default":[]},"columns":{"type":"number","title":"每行显示的列数, 默认 4","description":"每行显示的列数, 默认 4","ui:group":"🎴 服务卡片配置","ui:groupOrder":2,"ui:order":6,"default":4},"service_name":{"type":"string","title":"组件名称, 默认 \"service_cards_grid\"","description":"组件名称, 默认 \"service_cards_grid\"","ui:group":"🎴 服务卡片配置","ui:groupOrder":2,"ui:order":7,"default":"service_cards_grid"},"footer_text":{"type":"string","description":"页面底部版权文字 (自动推断)","ui:group":"🦶 页面底部配置","ui:groupOrder":100,"ui:order":8,"defa